// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 응시
// ==========================================
// 응시 — 무엇이 진짜 무엇인지 보는 눈. 호러 · 공포 — 보고 있는 것, 부르는 것, 끌고 가는 것.
// 여기서는 보는 눈이 제일 먼저 들킨다. 오래 보는 쪽이 보이는 쪽이 된다.
// scholar 학자 · hexer 주술사 · exorcist 퇴마사 · physiog 관상가 · detective 탐정

// ------------------------------------------
// 학자 · 자원 없음
// ------------------------------------------
kJob('scholar', 'A', [

{ at:'A', t:'복도 — 코팅된 수칙',
  x:`복도 벽에 종이 한 장이 붙어 있다. 손으로 쓴 수칙을 코팅했다. 번호가 열까지 있다.<br><br>
    「둘. 이름이 불려도 돌아보지 않는다.」 「다섯. 불이 꺼지면 그 자리에 앉는다.」 반듯한 글씨다. 코팅 안쪽에 공기 방울이 갇혀 있다.<br>
    일곱째 줄만 코팅 위에 적혔다. 같은 글씨체다. 「일곱. 불리면 대답한다.」<br><br>
    둘째 줄과 일곱째 줄이 서로를 지운다. 등 뒤 복도 끝에서 누가 숨을 들이쉰다. 부르기 직전의 숨이다.`,
  o:[
    { l:'① 일곱째 줄이 어떻게 쓰였는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`뜻은 접어 두고 획을 봤다. 획에는 순서가 있다. 사람 손은 위에서 아래로, 왼쪽에서 오른쪽으로 긋는다.<br><br>일곱째 줄은 획이 거꾸로 그어졌다. 끝에서 시작해 머리에서 끝난다. 종이 뒤에서 비쳐 보고 따라 쓴 글씨다. 글자를 뒤에서만 본 손이다.<br>둘째 줄을 지켰다. 이름이 불렸다. 돌아보지 않았다.<br><br>글은 뜻보다 먼저 손을 남긴다. 누가 어느 쪽에서 썼는지가 뜻보다 정직하다. 눈이 이제 글자 앞에서 손부터 찾는다.`,
      ng:`획을 따라가는 동안 이름이 불렸다. 바로 귀 뒤에서.<br><br>대답이 목까지 올라왔다. 이를 악물다 혀끝을 씹었다. 비린 맛이 입에 돈다.<br>읽던 줄을 놓쳤다. 어느 쪽이 먼저 쓰였는지 끝내 모른다. 복도를 빠져나오는 내내 손으로 입을 막고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-16 } },
    { l:'② 코팅 안쪽 열 줄만 따른다.', k:'steady', dc:22,
      ok:`코팅 위의 것은 나중에 온 것이다. 나중에 온 것은 원래 없던 것이다. 안쪽 열 줄만 외웠다.<br><br>걷기 시작하자 이름이 불렸다. 일행 목소리다. 다음엔 어머니 목소리다. 돌아보지 않았다. 대답하지 않았다.<br>복도 끝 문에 손이 닿았을 때 등 뒤에서 혀 차는 소리가 났다. 수칙을 쓴 사람도 이 소리를 들었을 것이다.`,
      ng:`열 줄을 외우며 걷는데 머릿속에서 줄이 하나 늘었다. 열하나.<br><br>외운 적 없는 줄이다. 「열하나. 대답하지 않으면 데리러 간다.」<br>발걸음이 느려졌다. 뒤에서 걸음 소리가 빨라졌다. 문을 밀고 넘어지듯 나왔다. 어깨가 문틀에 부딪혀 한동안 팔이 올라가지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'③ 일곱째 줄을 지우고 바르게 고쳐 쓴다.', k:'fix', dc:23,
      doom:{ title:'수칙 일곱', what:'수칙 종이 뒤 벽 속으로 끌려갑니다', dc:18, sec:50,
        text:`소매로 일곱째 줄을 문질러 지웠다. 그 자리에 숯으로 고쳐 썼다. 「일곱. 불려도 대답하지 않는다.」<br><br>숯이 멈추지 않는다. 손이 다음 줄을 쓴다. 「여덟. 고쳐 쓴 사람이 지킨다.」 이쪽 글씨다.<br>코팅 너머에서 종이가 부푼다. 안쪽에서 손바닥이 밀어 온다. 쓰는 손목을 종이째 쥔다. 차고 납작한 손이다.<br><br>당긴다. 벽 쪽으로. 종이가 찢어지지 않는다. 손목이, 팔꿈치가 종이 너머로 들어간다.`,
        dieText:`복도 벽 수칙은 이제 열한 줄이다.<br><br>코팅 안쪽에 공기 방울이 하나 늘었다. 사람 얼굴만 하다.<br>다음에 이 복도를 지나는 사람은 그 방울 안에서 누가 입을 벙긋거리는 걸 본다. 수칙을 읽어 주는 입 모양이다.` },
      ok:`일곱째 줄을 소매로 문질러 지웠다. 숯을 쥐었다가 내려놓았다. 아무것도 쓰지 않았다.<br><br>빈 줄은 지킬 사람이 없다. 고쳐 쓰면 고친 사람이 그 줄의 주인이 된다. 학자는 남의 기록에 제 글씨를 얹지 않는다.<br>이름이 불렸다. 둘째 줄이 남아 있다. 돌아보지 않고 걸었다. 빈 줄 자리에서 종이가 한 번 부풀다 가라앉았다.`,
      win:{ exp:24, dream:3, spirit:8 } }
  ] },

{ at:'A1', t:'부조정실 — 오늘의 큐시트',
  x:`부조정실 책상에 판이 하나 놓였다. 집게에 큐시트가 물려 있다. 「방글 동산」. 오늘 날짜.<br><br>
    칸이 넷이다. 순서, 내용, 시간, 비고. 시작 노래 1분 30초. 인형극 4분. 칼싸움 놀이 3분. 연필 글씨가 반듯하다.<br>
    맨 끝 줄은 「오늘의 친구 — 무대로」. 시간 칸이 비었다.<br><br>
    모니터 벽에서 숫자가 줄어든다. 방송까지 남은 시간이다. 시간 칸을 다 더하면 방송 길이가 나온다. 손가락이 벌써 접히고 있다.`,
  o:[
    { l:'① 시간 칸을 다 더해 빈 데를 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`위에서부터 더했다. 이십구 분 삼십 초. 방송은 삼십 분이다. 삼십 초가 빈다.<br><br>비고 칸을 비스듬히 봤다. 연필로 썼다 지운 홈이 있다. 「광고」. 그 삼십 초 동안은 카메라 불이 다 꺼진다. 아무것도 이쪽을 안 본다.<br>모니터 숫자가 그 자리에 왔을 때 무대 옆 통로를 지났다. 카메라 세 대가 고개를 숙이고 있었다.<br><br>표는 칸을 읽는 게 아니다. 칸 사이를 읽는 것이다. 더한 값이 모자라면 모자란 만큼이 길이 된다. 이제 숫자가 줄지어 있으면 먼저 빈 데가 보인다.`,
      ng:`더하다가 셈이 어긋났다. 다시 더했다. 또 어긋난다. 어디서 십 초씩 늘어난다.<br><br>고개를 드니 모니터 하나에 뒤통수가 찍혀 있다. 이쪽 뒤통수다. 화면 밑에 자막이 지나간다. 오늘의 친구 — 준비 중.<br>뒤를 돌아봤다. 카메라는 없다. 화면 속 이쪽은 돌아보지 않았다. 부조정실을 나올 때까지 그 화면을 등지고 걸었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 시작 노래가 나오는 동안 무대 옆을 지난다.', k:'hide', dc:22,
      ok:`큐시트대로라면 첫 일 분 삼십 초는 노래다. 노래하는 동안 카메라는 언니만 잡는다.<br><br>반주가 나왔다. 무대 옆 통로로 몸을 낮춰 들어갔다. 카메라 불이 셋 다 무대 가운데를 향해 있다.<br>노래가 끝나기 열 박자 전에 통로를 빠져나왔다. 등 뒤에서 박수가 났다. 아무도 없는 방청석에서.`,
      ng:`반주가 나왔다. 무대 옆 통로로 들어섰다. 그런데 노래가 짧다. 큐시트보다 짧다.<br><br>일 분도 안 돼 박수가 터진다. 카메라 하나가 고개를 돌린다. 빨간 불이 이쪽을 잡는다.<br>바닥에 엎드려 기었다. 빨간 불이 그 자리에 오래 머물렀다. 무릎이 다 까졌다. 노래가 다시 처음부터 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'교실동 — 물에 잠긴 판서',
  x:`교실 칠판에 판서가 남았다. 국어 시간이다. 시 한 편을 옮겨 적었다. 물이 칠판 가운데까지 찼다.<br><br>
    물 위로 나온 것은 줄마다 앞 절반이다. 「물이 들어오면」 「줄을 서서」 「이름을 부르면」 「손을 내밀면」.<br>
    나머지 반은 물 밑에서 흔들린다. 분필 글씨가 물속에서도 하얗다.<br><br>
    교탁 위 출석부가 펼쳐져 있다. 수업 중이다. 의자 스물몇 개가 물속에서 칠판 쪽을 보고 있다.`,
  o:[
    { l:'① 물 위의 반만으로 시를 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`물속 글씨가 너무 선명하다. 분필은 물에 풀린다. 물에 잠긴 반은 진작 다 풀렸어야 한다.<br><br>그러니 아래 반은 물이 찬 다음에 누가 새로 쓴 것이다. 선생이 쓴 건 위 반뿐이다. 위 반은 끝이 없는 말이다. 끝이 없는 말은 아무것도 시키지 않는다.<br>출석부가 넘어가는 소리가 났다. 위 반 어디에도 대답하라는 말은 없다. 입을 닫고 교실을 지났다.<br><br>글은 놓인 자리가 먼저 말해 준다. 남아 있을 수 없는 자리에 남은 글은 나중에 온 글이다. 눈이 글자보다 먼저 글자가 놓인 자리를 본다.`,
      ng:`위 반을 읽다 보니 아래 반이 저절로 읽힌다. 물결이 글씨를 위로 올려 보낸다.<br><br>「이름을 부르면 / 대답을 하고」. 읽는 순간 출석부가 넘어간다. 이쪽 이름이 물 밑에서 불렸다.<br>입술이 움직였다. 소리는 안 냈다. 그래도 의자 하나가 물속에서 조금 이쪽으로 돌았다. 교실을 나올 때까지 그 의자가 따라 돌았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-26 } },
    { l:'② 물에 얼굴을 넣고 아래 반을 읽는다.', k:'steady', dc:23,
      doom:{ title:'아래 반', what:'칠판 밑 물속으로 끌려 내려갑니다', dc:18, sec:50,
        text:`숨을 들이쉬고 얼굴을 물에 넣었다. 차다. 분필 글씨가 눈앞에 있다.<br><br>「물이 들어오면 / 아래로 오너라」. 「손을 내밀면 / 꼭 잡아 주어라」. 다 읽기도 전에 뒷목에 손이 얹힌다. 작은 손이다. 쓰다듬듯이.<br>그 손이 누른다. 아래로. 다른 손들이 소매를, 허리띠를, 발목을 잡는다. 수업 중에 일어선 학생을 앉히는 손이다.<br><br>칠판 밑으로 끌려 내려간다. 의자 하나가 비어 있다. 거기까지만 가면 된다는 듯이.`,
        dieText:`출석부가 한 장 넘어갔다.<br><br>칠판 아래 반에 한 줄이 늘었다. 분필 글씨가 물속에서 하얗다.<br>「다 읽은 친구는 / 앉아서 기다려라」. 물속 의자가 하나도 비어 있지 않다.` },
      ok:`숨 한 번만큼만 넣었다. 첫 줄 아래 반만 읽고 바로 뺐다.<br><br>「물이 들어오면 / 아래로 오너라」. 그것만으로 충분하다. 아래 반은 이쪽을 부르는 글이다.<br>나머지는 안 읽었다. 머리에서 물이 뚝뚝 떨어진다. 뒷목이 이상하게 따뜻하다. 누가 방금까지 손을 대고 있던 것처럼.`,
      win:{ exp:23, dream:3, mind:6 } },
    { l:'③ 교탁 위 출석부를 덮는다.', k:'hide', dc:22,
      ok:`물을 젓지 않고 교탁까지 갔다. 출석부를 덮었다.<br><br>넘어가던 소리가 멈췄다. 출석부 없이 출석은 못 부른다. 의자들이 칠판 쪽을 본 채 가만히 있다.<br>교실을 빠져나와 문을 닫았다. 문 너머에서 출석부 표지를 손톱으로 긁는 소리가 났다. 아주 작은 손톱이다.`,
      ng:`덮었다. 젖은 출석부가 손을 떠나자마자 저절로 펴진다. 펴진 장이 이쪽 이름이 있는 장이다.<br><br>다시 덮으려는데 표지가 손바닥에 들러붙는다. 떼어 내자 살갗이 같이 일어났다.<br>교실을 나올 때 손바닥에서 물이 배어 나왔다. 피가 아니라 물이다. 한참 멎지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A', t:'계단 — 둘인 층수 표지',
  x:`계단참마다 층수 표지가 붙어 있다. 내려갈수록 숫자가 커진다. 셋. 넷. 넷. 다섯.<br><br>
    넷이 둘이다. 글씨체도 색도 같다. 같은 것이 둘이면 하나는 원본이고 하나는 베낀 것이다.<br>
    일행은 그냥 내려가자고 한다. 표지가 틀릴 수도 있지 않느냐고.<br><br>
    두 번째 넷 계단참 문이 반쯤 열려 있다. 안이 깜깜하다. 거기서 누가 층을 센다. 낮게. 넷, 넷, 넷.`,
  o:[
    { l:'① 두 표지 가운데 베낀 쪽을 가린다.', k:'gaze', dc:22,
      ok:`첫 번째 넷은 나사 녹이 흘러내려 표지 밑으로 갈색 줄이 졌다. 오래 붙어 있던 표지다.<br><br>두 번째 넷에도 녹 줄이 있다. 그런데 위로 흘렀다. 녹까지 그려 넣은 손이 물이 아래로 흐른다는 걸 몰랐다.<br>그 층은 없는 층이다. 일행 눈을 가리게 하고 그 계단참을 멈추지 않고 지났다. 반쯤 열린 문 쪽으로 아무도 고개를 돌리지 않았다.<br><br>문 안에서 세던 소리가 끊겼다. 다섯 표지 아래에서 다들 숨을 몰아쉬었다.`,
      ng:`둘을 번갈아 봤다. 똑같다. 볼수록 더 똑같아진다. 처음엔 달랐던 것 같은데.<br><br>문 안에서 세는 소리가 이쪽 목소리로 바뀌었다. 넷, 넷. 입술이 따라 움직이려 한다.<br>일행이 팔을 잡아끌었다. 계단을 내려오다 발을 헛디뎠다. 정강이가 모서리에 찍혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 표지는 보지 않고 계단 수로 층을 센다.', k:'sense', dc:22,
      ok:`층마다 스물두 계단이다. 세 층을 세어 확인했다.<br><br>두 번째 넷에서는 스물세 계단이다. 하나가 많다. 많은 하나가 어느 것인지 발로 짚어 찾았다. 열한 번째. 다른 계단보다 조금 무르다.<br>그 칸을 넘어 밟았다. 일행에게도 넘으라고 했다. 등 뒤에서 무른 칸이 한 번 들썩였다. 숨 쉬듯이.`,
      ng:`세다가 숫자를 놓쳤다. 열하나였는지 열둘이었는지.<br><br>다음 발이 무른 칸을 디뎠다. 발목까지 빠진다. 계단이 아니라 다른 무엇이다. 따뜻하다.<br>빼냈다. 신발 한 짝이 남았다. 그 칸 밑으로 천천히 들어갔다. 맨발로 다섯 층을 더 내려갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'A', t:'문 앞 — 틀리게 읽는 목소리',
  x:`닫힌 문 너머에서 누가 책을 읽는다. 또박또박. 아이에게 읽어 주는 목소리다.<br><br>
    아는 이야기다. 어릴 때 수없이 읽었다. 그런데 한 낱말씩 틀린다. 「옛날 옛적에」가 「오늘 지금에」로. 「산 너머」가 「문 너머」로.<br>
    틀릴 때마다 목소리가 멈춘다. 고쳐 줄 사람을 기다리는 틈이다.<br><br>
    입이 근질거린다. 틀린 것을 듣고 그냥 넘어가 본 적이 없는 입이다.`,
  o:[
    { l:'① 문에 대고 바르게 고쳐 준다.', k:'gaze', dc:23,
      doom:{ title:'읽어 줄래', what:'문 안쪽으로 옷깃을 잡혀 끌려 들어갑니다', dc:18, sec:50,
        text:`「옛날 옛적에.」 고쳐 주었다. 목소리가 멈춘다. 오래.<br><br>「그럼 네가 읽어 줄래.」 문이 안쪽으로 열린다. 저절로. 안에 작은 의자와 펼친 책 한 권. 아무도 없다.<br>문틈에서 손이 나와 옷깃을 쥔다. 고마워서 붙드는 손처럼 부드럽다. 그런데 놓지 않는다.<br><br>끌려 들어간다. 의자 쪽으로. 펼친 책 첫 줄이 보인다. 「오늘 지금에」.`,
        dieText:`문 너머에서 이야기가 끝까지 읽힌다. 처음부터 끝까지 바르게.<br><br>읽는 목소리가 이쪽 목소리다. 한 낱말도 안 틀린다.<br>문 앞에 신발이 한 켤레 놓였다. 가지런히. 다음 사람이 오면 그 목소리가 다시 틀리기 시작한다.` },
      ok:`고쳐 주려던 말을 입안에서만 했다. 소리는 내지 않았다.<br><br>목소리가 기다린다. 아무도 안 고친다. 한참 뒤에 목소리가 제가 어디까지 읽었는지 잃어버렸다. 같은 줄을 두 번 읽고 멈췄다.<br>문은 열리지 않았다. 그 앞을 지나왔다. 입안이 쓰다. 틀린 것을 두고 온 맛이다.`,
      win:{ exp:23, dream:3, spirit:7 } },
    { l:'② 귀를 막고 원래 이야기를 머릿속으로 끝까지 왼다.', k:'steady', dc:22, wake:1,
      ok:`귀를 막았다. 머릿속에서 처음부터 읽었다. 옛날 옛적에. 산 너머. 한 글자도 안 틀리게.<br><br>문 너머 목소리가 머릿속 문장에 밀린다. 틀리려다가 바른 쪽으로 끌려온다. 「오늘…… 옛날」. 목소리가 더듬는다.<br>머릿속 이야기가 끝날 때 문 앞을 다 지났다.<br><br>외워 둔 글은 방패가 된다. 머릿속에 꽂아 둔 책이 문 한 짝만큼 단단해졌다. 읽어 둔 것이 많을수록 들어올 자리가 적다.`,
      ng:`머릿속에서 읽는데 문 너머 목소리를 따라 문장이 바뀐다. 「산 너머」가 「문 너머」로 외워진다.<br><br>원래 어땠는지 떠오르지 않는다. 수없이 읽은 이야기인데.<br>문 앞을 지나고 나서도 한참 기억을 더듬었다. 끝내 못 찾았다. 어릴 때 읽은 책 한 권이 통째로 바뀌었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'분장실 — 괄호 친 대본',
  x:`분장대 위에 대본이 펼쳐져 있다. 「방글 동산」 대본이다. 언니 대사, 방글이 대사, 뭉치 대사.<br><br>
    대사 사이 괄호 안에 지문이 있다. (웃으며) (손을 흔들며) (친구를 안아 준다).<br>
    마지막 장 괄호만 펜이 다르다. 잉크가 아직 번진다. (오늘의 친구가 들어온다).<br><br>
    대본은 소리 내어 읽으라고 쓴 글이다. 거울 둘레 전구가 하나씩 켜진다. 읽을 사람을 기다린다.`,
  o:[
    { l:'① 대사는 건너뛰고 괄호 안만 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`대사는 말이다. 괄호는 일이다. 괄호 안만 골라 읽었다.<br><br>(뭉치, 왼쪽 문으로 들어와 친구 뒤에 선다). (방글이, 노래가 끝나면 친구 손을 잡는다). 다음 장면이 미리 적혀 있다. 누가 어디서 나오는지.<br>왼쪽 문을 피해 오른쪽으로 돌았다. 노래가 끝날 때 손 닿는 거리에 아무도 없게 했다. 복도 왼쪽 문이 열렸다 닫혔다.<br><br>대본은 말보다 괄호가 무섭다. 괄호 안이 실제로 일어날 일이다. 이제 무엇을 읽든 눈이 먼저 괄호를 찾는다.`,
      ng:`괄호를 따라 넘기다 손이 멈췄다. 새 괄호가 있다. 방금 생겼다.<br><br>(친구가 대본을 읽는다). 읽고 있다. 지금.<br>대본을 덮었다. 전구가 한꺼번에 켜졌다. 거울 속 이쪽 얼굴이 하얗게 날아간다. 분장실을 나오는 동안 눈앞에 둥근 빛 자국이 둥둥 떠다녔다. 한참 앞이 잘 안 보였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 마지막 장을 반으로 접어 끼워 둔다.', k:'hide', dc:22,
      ok:`마지막 장을 접어 앞장 사이에 끼웠다. 펼쳐도 안 보이게.<br><br>전구가 켜지다 멈춘다. 다음 장면이 없으면 들어올 차례도 없다.<br>분장실을 나왔다. 복도에서 인형탈 하나가 서성인다. 어디로 들어가야 하는지 모르는 걸음이다. 그 옆을 숨죽이고 지났다.`,
      ng:`접는데 종이가 안 접힌다. 접은 자리가 다시 펴진다. 몇 번을 접어도.<br><br>네 번째에 종이 모서리가 손톱 밑을 파고들었다. 피가 괄호 위에 떨어진다. 번지는 잉크와 섞인다.<br>(오늘의 친구가 들어온다). 글씨가 더 진해졌다. 손톱 밑이 한참 욱신거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-20 } },
    { l:'③ 언니 대사를 한 줄 소리 내어 읽는다.', k:'bond', dc:23,
      doom:{ title:'첫 대사', what:'하얀 장갑들에게 무대로 끌려 나갑니다', dc:18, sec:50,
        text:`「친구야, 이리 와.」 소리 내어 읽었다. 목소리가 맑고 높게 나온다. 이쪽 목소리가 아니다.<br><br>거울 뒤 커튼이 열린다. 그 너머에 무대 조명이 있다. 하얀 장갑들이 줄지어 손을 내민다. 손가락이 넷이다.<br>장갑들이 손목을, 어깨를, 허리를 잡는다. 출연자를 무대로 모시는 손이다. 공손하다. 세다.<br><br>끌려 나간다. 박수가 터진다. 대본 다음 줄이 머릿속에서 저절로 읽힌다.`,
        dieText:`분장대 위 대본이 저절로 한 장 넘어갔다.<br><br>새 장의 첫 괄호. (오늘의 친구, 언니와 함께 노래한다).<br>거울 둘레 전구가 하나씩 꺼진다. 거울 속 분장실 의자에 누가 앉아 있다. 웃는 화장을 하고.` },
      ok:`언니 대사 가운데 맨 끝 장의 한 줄을 골라 읽었다. 「친구들, 다음에 또 만나요.」<br><br>전구가 하나씩 꺼진다. 끝인사가 나오면 방송은 끝난다. 대본이 그렇게 정해 두었다.<br>거울 뒤 커튼 너머에서 장갑들이 손을 거두는 기척이 났다. 분장실을 나올 때 목소리가 아직 조금 높았다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'도서관 — 대출 카드',
  x:`도서관 서가 아래 칸은 물에 잠겼다. 위 칸 책들 뒤표지 안쪽에 대출 카드가 꽂혀 있다.<br><br>
    이름, 대출일, 반납일. 반납일 도장이 전부 같은 날이다. 물이 들어온 날이다. 그날 다들 책을 반납했다.<br>
    한 권만 반납일 칸이 비었다. 대출자 이름은 물에 번졌다.<br><br>
    사서 책상에 도장이 놓여 있다. 인주가 아직 붉다. 반납 안 된 책을 그냥 두지 못하는 손이 여기 또 하나 있다.`,
  o:[
    { l:'① 번진 이름을 다른 카드의 글씨와 맞춰 본다.', k:'gaze', dc:22, wake:1,
      ok:`카드 수십 장을 펼쳐 놓고 글씨를 맞췄다. 획 끝이 모두 아래로 처지는 손이 하나 있다. 사서 글씨다. 모든 카드의 책 제목을 그 손이 적었다.<br><br>번진 이름도 그 손이다. 사서가 그날 책 한 권을 빌렸다. 『본관 설비 도면』. 학생 대신 길을 찾으려고. 반납하지 못했다.<br>사서 책상 위 칸 서랍에 그 책이 있었다. 물에 불었지만 접어 둔 장은 펴진다. 계단 옆 배수로가 그려져 있다.<br><br>이름은 지워져도 손버릇은 다른 카드에 남는다. 한 사람의 글씨를 백 장에서 찾아내는 눈이 생겼다. 사람을 글씨로 다시 세운다.`,
      ng:`맞추다 보니 번진 이름이 차츰 또렷해진다. 물이 빠지듯이.<br><br>이쪽 이름이다. 대출일이 오늘이다. 반납 예정일 칸에 도장이 막 찍힌다. 철컥.<br>사서 책상 쪽을 봤다. 도장이 제자리에 있다. 인주가 손가락 모양으로 눌려 있다. 도서관을 나올 때까지 등 뒤에서 도장 찍는 소리가 따라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 반납함 안을 뒤진다.', k:'luck', dc:21,
      ok:`반납함 뚜껑이 녹슬어 반쯤 열린다. 안에 마른 책 몇 권. 물이 여기까지는 안 들었다.<br><br>책 사이에 깡통이 하나 끼어 있다. 누가 반납하는 척 숨겨 둔 간식이다. 뚜껑을 비틀자 끈적한 냄새가 난다. 꿀이다. 아직 굳지 않았다.<br>한 줌을 떴다. 반납함은 원래 남이 넣은 것을 꺼내면 안 되는 곳이다. 그래도 떴다.`,
      ng:`투입구에 손을 넣자 안쪽에서 무엇이 손을 받는다. 책을 받듯이. 손바닥 밑에 손바닥이 있다.<br><br>받은 손이 손목을 쥐고 당긴다. 반납함 안쪽으로. 팔꿈치까지 들어갔다가 겨우 뺐다.<br>손목 안쪽에 붉은 도장이 찍혀 있다. 반납. 날짜는 없다. 문질러도 지워지지 않는다.`,
      win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 지운 이름 한 줄',
  x:`벽에 명단이 걸려 있다. 앞서 온 일행 같다. 이름 다섯.<br><br>
    넷은 이름 위에 줄이 그어졌다. 줄 그은 이름은 셀 수 있다. 다섯째는 지우개로 지웠다. 지운 이름은 없던 것이 된다.<br>
    연필은 지워도 종이에 홈이 남는다. 비스듬히 보면 읽힌다.<br><br>
    등 뒤에서 일행이 수를 센다. 하나, 둘, 셋, 넷, 다섯. 다섯째에서 잠깐 멈칫한다.`,
  o:[
    { l:'① 지운 자리의 홈을 읽는다.', k:'gaze', dc:22,
      ok:`등불을 낮게 대고 비스듬히 봤다. 홈이 그림자를 만든다. 읽힌다.<br><br>일행 하나의 이름이다. 지금 이 복도에 서 있는 사람. 본인은 이 명단을 처음 본다고 한다. 글씨는 본인 것이다.<br>펜으로 그 홈 위를 꾹꾹 눌러 다시 썼다. 지우개로는 안 지워지게. 다 쓰고 나서 일행을 세었다. 다섯이다. 멈칫하지 않았다.<br><br>명단 아래 바닥에서 지우개 가루가 한 줌 쓸려 갔다. 바람도 없는데 어둠 쪽으로.`,
      ng:`읽으려고 볼수록 홈이 얕아진다. 종이가 저 혼자 펴진다.<br><br>다 펴졌다. 아무것도 없다. 일행을 세었다. 넷이다. 다시 세었다. 넷.<br>누가 빠졌는지 생각이 안 난다. 다들 마찬가지다. 한참 뒤 어둠 속에서 다섯째가 비틀거리며 걸어 나왔다. 이름을 불러 주지 못했다. 이름이 떠오르지 않았다.`,
      win:{ exp:22, dream:3, spirit:7 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 일행 이름을 하나씩 소리 내어 부른다.', k:'bond', dc:22,
      ok:`한 사람씩 이름을 불렀다. 크게. 대답을 받을 때마다 어깨를 짚었다.<br><br>넷째까지 바로 대답했다. 다섯째는 이름을 듣고 한 박자 뒤에 대답했다. 제 이름인지 잠깐 몰랐다고 한다.<br>그 이름을 두 번 더 불렀다. 대답이 빨라졌다. 명단 앞을 떠날 때 다섯째가 제 이름을 혼자 중얼거리고 있었다.`,
      ng:`다섯째 이름을 부르려는데 입에서 안 나온다. 혀끝에 걸려 있다.<br><br>당사자도 대답을 못 한다. 제 이름이 생각나지 않는다고. 둘이 마주 보고 서 있었다.<br>명단 홈을 손가락으로 더듬어 겨우 읽어 냈다. 그사이 다른 일행 하나가 제 이름을 두 번 틀리게 말했다. 다들 이름을 손등에 적었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 같은 꿈 다섯 개',
  x:`쉬는 틈에 잠깐씩 졸았다. 깨어서 꿈 얘기를 했다. 다섯이 같은 꿈을 꿨다.<br><br>
    긴 복도. 끝에 문 하나. 문에 번호가 붙어 있다. 번호는 다들 기억이 안 난다고 한다.<br>
    같은 일을 여럿이 말하면 따로 받아 적어야 한다. 서로 듣고 맞춰지기 전에.<br><br>
    벌써 서로 말을 맞추고 있다. 「맞아, 불이 깜빡였지.」 아까는 아무도 불 얘기를 안 했다.`,
  o:[
    { l:'① 한 사람씩 떼어 놓고 따로 받아 적는다.', k:'fix', dc:22,
      ok:`한 명씩 구석으로 불러 받아 적었다. 다른 사람 말은 들려주지 않았다.<br><br>다섯 장을 나란히 놓았다. 다 같은 데는 서로 들은 것이다. 한 사람만 말한 것 하나가 남는다. 「문고리가 안쪽에 달려 있었다.」<br>안에서만 여는 문이다. 이쪽에서 열 문이 아니다. 그날부터 문고리가 바깥에 없는 문 앞에서는 다들 멈췄다.`,
      ng:`떼어 놓고 받아 적는데 넷째가 구석에서 오래 안 나온다.<br><br>가 보니 벽을 보고 서 있다. 꿈 얘기를 한다. 이번엔 꿈속에 이쪽이 나온다. 복도 끝 문을 이쪽이 열어 주었다고.<br>그 말을 받아 적던 손이 떨렸다. 다섯 장 가운데 한 장이 이쪽 글씨가 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 꿈속 문 번호를 끝까지 떠올린다.', k:'gaze', dc:23,
      doom:{ title:'문 번호', what:'등 뒤 문 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`눈을 감고 꿈을 다시 걸었다. 복도, 깜빡이는 불, 문. 번호가 떠오른다. 한 자리씩.<br><br>다 떠올랐다. 눈을 떴다. 등 뒤 벽에 문이 있다. 쉬는 내내 등을 기대고 있던 벽이다. 그 번호가 붙어 있다.<br>문고리가 안쪽에 달려 있다. 철컥. 안에서 돌아간다.<br><br>문틈으로 팔들이 나와 겨드랑이를 끼고 들어 올린다. 잠든 아이를 안아 옮기는 손이다. 끌려 들어간다. 다리가 바닥에 끌린다.`,
        dieText:`일행이 다시 졸았다. 꿈을 꿨다.<br><br>긴 복도, 끝에 문 하나. 이번엔 다들 번호를 기억한다. 하나가 늘었다.<br>문 너머에서 누가 받아 적는 소리가 난다. 꿈 얘기를 하나씩. 따로따로.` },
      ok:`첫 자리까지만 떠올렸다. 거기서 눈을 떴다. 더 떠올리면 안 될 것 같았다.<br><br>그 숫자로 시작하는 문을 모두 피하기로 했다. 쉬던 자리 등 뒤 벽에도 문이 하나 있다. 그 숫자로 시작한다.<br>다들 일어나 자리를 옮겼다. 옮긴 뒤에 그 문에서 철컥 소리가 났다. 아무도 기대고 있지 않았다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 다섯 이야기에 없는 것을 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`다들 복도를 말했다. 불을 말했다. 문을 말했다. 아무도 제 몸을 말하지 않았다. 손도, 발도, 옆 사람도.<br><br>다섯이 같은 꿈을 꾼 게 아니다. 다섯이 하나의 눈으로 본 것이다. 복도를 걸어 문으로 오는 무엇의 눈으로. 그 문은 지금 여기다.<br>다들 일으켜 곧장 떠났다. 한참 뒤에 지나온 쪽에서 문이 열리는 소리가 났다.<br><br>여럿이 말한 것보다 여럿이 다 빠뜨린 것이 크다. 빈 데를 읽는 눈이 하나 더 깊어졌다. 이제 이야기를 들으면 거기 없는 것부터 센다.`,
      ng:`없는 것을 찾으려 다섯 이야기를 다시 들었다. 들을 때마다 이야기가 하나씩 길어진다.<br><br>복도가 길어지고 문이 가까워진다. 이번엔 문 앞에 누가 서 있었다고 한다. 다섯이 다 그렇게 말한다.<br>그게 누구냐고 묻자 다섯이 동시에 이쪽을 가리켰다. 그러고는 아무도 그런 말을 한 기억이 없다고 했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 빠진 회차',
  x:`선반에 테이프가 회차 순서로 꽂혀 있다. 1회부터 천 몇백 회까지. 이름표 글씨가 깔끔하다.<br><br>
    군데군데 빈칸이 있다. 빠진 자리에 먼지가 네모나게 비어 있다. 누가 꺼내 갔다.<br>
    빈칸을 셌다. 그다음엔 빈칸과 빈칸 사이를 셌다. 손이 먼저 셌다.<br><br>
    부조정실 쪽에서 테이프 감기는 소리가 난다. 휘리릭. 멈춤. 휘리릭.`,
  o:[
    { l:'① 빈칸 사이의 간격을 따진다.', k:'gaze', dc:22,
      ok:`처음 빈칸에서 다음 빈칸까지 쉰여섯 회. 그다음은 마흔아홉. 마흔둘. 서른다섯. 칠씩 줄어든다.<br><br>마지막 빈칸에서 일곱을 더 가면 오늘 회차다. 오늘은 빈칸이 되는 날이다. 빈칸이 생긴 날마다 이름표 옆에 연필로 작게 적혀 있다. 「오늘의 친구 출연」.<br>일행에게 말했다. 오늘은 누구도 무대 쪽 문 근처에 서지 말자고. 다들 고개를 끄덕였다. 끄덕이는 손이 다들 떨렸다.`,
      ng:`세다가 선반 끝에서 테이프 하나가 저절로 빠져나온다. 한 칸만큼. 쓰윽.<br><br>이름표에 오늘 날짜가 적혀 있다. 아직 녹화 전인데. 칸 안쪽에 이쪽 그림자가 비친다.<br>밀어 넣었다. 다시 나온다. 세 번째에 테이프를 빼서 선반 맨 아래 깊숙이 넣었다. 부조정실에서 감는 소리가 그쳤다. 대신 누가 선반을 하나씩 더듬는 소리가 들렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 맨 아래 칸 상자를 연다.', k:'luck', dc:21,
      ok:`맨 아래 칸에 상자가 있다. 「출연 어린이 선물」. 테이프로 봉했다.<br><br>안에 작은 꾸러미가 줄지어 있다. 비닐에 싼 꿀 사탕이다. 녹아서 한 덩이가 됐다. 비닐째 떼어 냈다.<br>꾸러미마다 이름표가 붙어 있었다. 아이 이름이다. 받으러 오지 않은 선물이다. 하나만 가져갔다. 이름표가 없는 것으로.`,
      ng:`상자 안에 꾸러미 대신 테이프가 들어 있다. 이름표가 아이 이름이다. 회차 번호가 없다.<br><br>맨 위 테이프가 저 혼자 감긴다. 상자 안에서. 작게, 아이 웃음소리가 샌다.<br>뚜껑을 닫고 상자를 깔고 앉았다. 감기는 소리가 엉덩이 밑에서 오래 났다. 일어서자 다리에 힘이 하나도 없었다.`,
      win:{ exp:14, item:'꿀 한 줌', mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'교무실 — 이백열세 번',
  x:`교무실 캐비닛 위 칸이 물 밖이다. 학적부가 꽂혀 있다. 1번부터 212번까지.<br><br>
    212번 다음 장에 213이 적혀 있다. 칸 모양은 같다. 줄 간격이 조금 좁다. 자로 대고 손으로 그어 넣은 칸이다.<br>
    이름 칸은 비었다. 입학일 칸에 오늘 날짜가 있다.<br><br>
    물이 교무실 책상 다리를 핥는다. 발밑에서만 물이 조금씩 높아진다.`,
  o:[
    { l:'① 213번 칸을 끝까지 읽는다.', k:'gaze', dc:23,
      doom:{ title:'입학', what:'교무실 바닥 물속으로 끌려 가라앉습니다', dc:18, sec:45,
        text:`칸을 하나씩 내려 읽었다. 보호자, 주소, 전 학교. 다 이쪽 것이다. 이쪽밖에 모르는 것까지.<br><br>비고 칸. 「기숙 배정 완료. 아직 대답을 안 함.」<br>발밑 물이 무릎까지 올라왔다. 이쪽 자리에서만. 물속에서 손들이 발목을 쥔다. 차고 작다. 입학식에 늦은 아이 손을 끄는 손이다.<br><br>당긴다. 바닥 쪽으로. 교무실 바닥이 거기서는 깊다. 학적부가 손에서 안 떨어진다.`,
        dieText:`학적부 213번 이름 칸이 채워졌다. 젖은 글씨다.<br><br>교무실 칠판 재적 칸이 고쳐졌다. 213.<br>물은 다시 책상 다리를 핥는 높이로 내려갔다. 캐비닛 위 칸에 학적부가 꽂혀 있다. 214가 그어져 있다.` },
      ok:`비고 칸 앞에서 멈췄다. 보호자 칸에 이쪽 것이 적힌 걸 보고 덮었다. 더 읽으면 다 맞는 것이 된다.<br><br>덮은 학적부를 캐비닛 위 칸에 그대로 꽂았다. 아무것도 적지 않았다.<br>발밑 물이 한 뼘 내려갔다. 이쪽 발목에 젖은 손자국이 찍혀 있다. 둘레만 하얗다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 213번 칸을 그은 것이 무엇인지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`1번부터 212번은 만년필 잉크다. 해가 지나 갈색으로 바랬다.<br><br>213번 칸은 바래지 않았다. 잉크가 아니다. 물이다. 마르지 않는 물로 그은 줄이다. 학교가 적은 게 아니다. 물이 적었다.<br>마른 소매로 꾹 눌러 찍었다. 줄이 소매에 옮아 번졌다. 칸이 사라졌다. 발밑 물이 한 뼘 내려갔다.<br><br>무엇으로 썼는지가 누가 썼는지를 말한다. 눈이 글자 아래, 글자를 만든 것까지 내려간다. 종이 위의 것을 이제 한 겹 더 읽는다.`,
      ng:`잉크인지 물인지 가리려고 손끝을 댔다. 손끝이 젖는다. 차다.<br><br>젖은 손끝에서 줄이 이쪽 손으로 옮겨 온다. 손가락 마디마다 가는 줄. 칸이다. 이쪽 손에 칸이 그어진다.<br>소매로 박박 닦았다. 줄은 닦였다. 손끝 감각이 한동안 안 돌아왔다. 물속에 오래 담근 손처럼 쭈글쭈글했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'벽 — 무릎 높이의 글씨',
  x:`벽 아래쪽, 무릎 높이에 글씨가 긁혀 있다. 손톱으로 쓴 것이다.<br><br>
    한 줄로 길게 이어진다. 앞 글자는 깊고 굵다. 뒤로 갈수록 얕아진다. 마지막은 실금이다.<br>
    엎드린 채 쓴 글씨다. 움직이면서 쓴 글씨다. 바닥에 끌려가면서.<br><br>
    일행이 등불을 들어 위를 비춘다. 위에는 아무것도 없다고 한다.`,
  o:[
    { l:'① 얕아지는 글씨를 끝까지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`쪼그려 앉아 손가락으로 홈을 따라갔다. 「위」. 「위에」. 「위에서」. 같은 말을 몇 번이고 다시 시작했다. 끝까지 못 썼다.<br><br>글자가 오른쪽으로 기울었다. 쓰던 몸이 오른쪽으로 끌려갔다. 위에서 내려와 오른쪽으로 끌고 가는 것이다.<br>왼쪽 벽에 붙어 걷게 했다. 등불은 위로만. 한 번, 천장에서 무엇이 오른쪽으로 미끄러져 가는 소리가 났다. 아무도 끌려가지 않았다.<br><br>글씨의 기울기에 쓰던 사람의 몸이 남는다. 엎드린 손, 끌리던 쪽. 글자에서 그 글자를 쓴 몸을 다시 일으켜 세우는 법을 알았다.`,
      ng:`엎드려 읽는 사이 머리 위로 바람이 지나갔다. 머리카락 끝이 들린다.<br><br>천장에서 물이 한 방울 목덜미에 떨어졌다. 차지 않다. 미지근하다. 침처럼.<br>몸을 굴려 벽에서 떨어졌다. 등불을 들어 올렸을 때 천장엔 아무것도 없었다. 목덜미가 그 자리만 오래 끈적했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 읽지 않고 벽을 등진 채 지나간다.', k:'steady', dc:22,
      ok:`읽지 않았다. 다 읽는 것보다 지나가는 게 먼저다. 벽에 등을 대고 옆걸음으로 갔다.<br><br>등 뒤 벽에서 손톱 긁는 소리가 아주 작게 난다. 이쪽 등이 닿은 자리마다. 누가 아직 쓰고 있다.<br>벽이 끝나는 데서 다들 숨을 몰아쉬었다. 긁는 소리가 마지막에 한 글자를 끝냈다. 무슨 글자인지는 아무도 보러 가지 않았다.`,
      ng:`벽을 등지고 걷는데 무릎 뒤에 무엇이 닿는다. 손톱이다. 벽에서 나온 손톱이다.<br><br>긁는다. 바지 너머로. 글자를 쓰듯이. 한 획, 두 획.<br>뛰었다. 무릎 뒤가 화끈거린다. 나중에 보니 살갗에 얕은 글자 하나가 그어져 있었다. 「위」.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'A', t:'갈림길 — 저마다 다르게 읽히는 표지판',
  x:`갈림길에 표지판이 섰다. 화살표 둘. 글씨가 적혀 있다.<br><br>
    일행이 저마다 다르게 읽는다. 하나는 「출구」, 하나는 「집」, 하나는 「엄마」. 다들 제가 읽은 쪽으로 몸이 기운다.<br>
    이쪽 눈에는 처음 보는 글자다. 아는 글자가 많은 눈에도 처음 보는 글자다.<br><br>
    못 읽는 사람은 이쪽 하나다. 그게 다행인지는 모른다.`,
  o:[
    { l:'① 뜻을 버리고 모양만 베껴 센다.', k:'gaze', dc:22,
      ok:`읽지 않고 셌다. 왼쪽 화살표에 획이 열하나. 오른쪽에 열둘. 나머지는 똑같다.<br><br>오른쪽에만 있는 획 하나는 갈고리 모양이다. 글자가 아니다. 그림이다. 손가락 넷을 오므린 손.<br>왼쪽으로 갔다. 다들 투덜거렸다. 오른쪽 길 끝에서 문 여는 소리가 났다. 반가운 사람이 문을 열어 주는 소리처럼 들렸다. 아무도 돌아보지 않게 했다.`,
      ng:`세다 보니 글자가 읽히기 시작한다. 처음 보는 글자인데.<br><br>「여기」. 이쪽 눈에는 그렇게 읽힌다. 몸이 저절로 오른쪽으로 기운다. 두 발짝을 갔다.<br>일행이 뒤에서 허리를 붙들었다. 넘어지며 표지판에 이마를 찧었다. 눈썹 위가 찢어져 피가 눈으로 들어갔다. 그 덕에 한동안 표지판이 안 보였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 일행에게 각자 읽은 것을 말하게 하고 맞춰 본다.', k:'bond', dc:22,
      ok:`한 사람씩 말하게 했다. 출구, 집, 엄마, 쉬는 곳.<br><br>다 가고 싶은 데다. 가고 싶은 데를 보여 주는 표지판은 미끼다. 미끼는 두 갈래 다 미끼다.<br>둘 다 버리고 왔던 길로 조금 돌아가 표지 없는 샛길로 들어섰다. 다들 아쉬운 얼굴로 갈림길을 돌아봤다. 표지판이 이쪽을 향해 조금 돌아서 있었다.`,
      ng:`「엄마」라고 읽은 일행이 말하다 말고 걷기 시작한다. 이쪽 말이 안 들린다.<br><br>쫓아가 팔을 잡았다. 뿌리친다. 둘이 한데 엉켜 굴렀다. 돌바닥에 팔꿈치가 갈렸다.<br>겨우 끌고 돌아왔다. 그 일행은 한참 울었다. 왜 우는지 본인도 몰랐다.`,
      win:{ exp:20, dream:2, spirit:6 }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 표지판을 등지고 바람이 오는 쪽을 찾는다.', k:'sense', dc:22,
      ok:`표지판을 보지 않았다. 손가락을 적셔 들었다. 한쪽이 서늘하다.<br><br>오른쪽 길에서는 바람이 안 온다. 왼쪽은 바람이 들어온다. 열린 데가 있다는 뜻이다.<br>왼쪽으로 갔다. 표지판은 끝까지 안 봤다. 읽을 수 없는 글자는 안 보는 게 낫다.`,
      ng:`바람이 양쪽에서 다 온다. 같은 세기로. 같은 온도로.<br><br>바람이 아니라 숨이다. 양쪽 어둠이 같이 숨을 쉰다.<br>손가락을 거두고 한참 서 있었다. 숨소리가 점점 가까워졌다. 결국 아무 쪽으로나 뛰었다. 다리가 풀릴 때까지.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A1', t:'소품 창고 — 판자 그림책',
  x:`소품 창고 선반에 커다란 그림책이 세워져 있다. 방송에서 언니가 읽어 주던 책이다. 표지가 판자다.<br><br>
    아는 옛이야기다. 산에서 길 잃은 아이가 집으로 돌아오는 이야기. 마지막 장에서 어머니가 문을 열어 준다.<br>
    책장이 풀로 붙어 마지막 장만 펼쳐진다. 그림 속 아이가 이쪽을 보고 있다. 원래 그림에선 아이가 등을 보인다.<br><br>
    마지막 장 밑에 글귀가 한 줄 있다. 언니가 읽던 줄이다.`,
  o:[
    { l:'① 원래 이야기와 다른 데를 짚는다.', k:'gaze', dc:22,
      ok:`원래 그림을 머릿속에 펴 놓고 겹쳐 봤다. 다른 데가 셋이다.<br><br>아이가 앞을 본다. 문이 열려 있다. 문 안이 집이 아니라 동산 세트다. 웃는 해, 털북숭이, 목이 긴 새.<br>이 책은 집으로 가는 책이 아니다. 동산으로 들이는 책이다. 그림책을 엎어 판자 쪽이 위로 오게 눕혔다. 엎어진 책은 아무도 안 읽는다. 창고 안이 조금 어두워졌다.`,
      ng:`다른 데를 찾느라 그림을 오래 봤다. 그림 속 아이도 오래 이쪽을 봤다.<br><br>아이 손이 조금 올라와 있다. 아까는 내려가 있었다. 손가락이 넷이다.<br>뒷걸음질 치다 선반에 등을 부딪쳤다. 위 칸 소품들이 쏟아졌다. 판자 해님이 어깨를 찍었다. 웃는 얼굴이 바닥에서 이쪽을 올려다봤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 마지막 글귀를 소리 내어 읽는다.', k:'steady', dc:23,
      doom:{ title:'마지막 장', what:'그림책 속으로 빨려 들어갑니다', dc:18, sec:45,
        text:`「그래서 아이는 동산에서 오래오래 살았어요.」 소리 내어 읽었다.<br><br>그림 속 아이가 웃는다. 손을 내민다. 판자 밖으로. 그 손이 이쪽 손목을 잡는다. 종이처럼 얇고 판자처럼 단단하다.<br>당긴다. 그림 쪽으로. 얼굴이 종이에 닿는다. 물감 냄새가 난다. 종이가 얼굴을 받아들인다. 어깨가 따라 들어간다.<br><br>그림 속 동산이 가까워진다. 웃는 해가 이쪽을 맞는다.`,
        dieText:`그림책은 선반에 다시 세워졌다. 마지막 장이 펼쳐진 채로.<br><br>그림 속에 아이가 둘이다. 둘 다 이쪽을 본다. 하나는 어른 키다.<br>다음 방송에서 언니가 이 책을 읽어 줄 것이다. 「그래서 아이들은」.` },
      ok:`글귀를 읽되 한 낱말을 바꿔 읽었다. 원래 이야기대로. 「그래서 아이는 집에서 오래오래 살았어요.」<br><br>그림 속 아이가 멈칫한다. 천천히 돌아선다. 원래 그림처럼 등을 보인다. 문 안이 흐려진다.<br>원래 이야기를 아는 사람이 고쳐 읽으면 책도 원래대로 돌아간다. 판자 표지가 저절로 덮였다. 풀로 붙어 있던 책장이었다.`,
      win:{ exp:24, dream:4, spirit:7 } }
  ] },

{ at:'A2', t:'사감실 — 근무 일지',
  x:`사감실 책상에 근무 일지가 펼쳐져 있다. 날짜마다 한 줄. 「점호 이상 없음. 재적 212, 현원 212.」<br><br>
    물이 든 날부터 글씨가 번졌다. 잉크가 아니라 물로 쓴 것처럼. 그래도 읽힌다. 매일 쓰였다. 오늘 날짜까지.<br>
    오늘 줄은 반만 쓰였다. 「점호 — 현원」. 그다음이 비었다.<br><br>
    복도 끝에서 열쇠 꾸러미 소리가 난다. 찰랑. 찰랑. 이쪽으로.`,
  o:[
    { l:'① 물 든 뒤의 줄을 처음부터 다시 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`몇 해치 같은 줄 사이로 손가락을 내렸다. 212, 212, 212. 그러다 한 줄. 「현원 211. 결석 1 — 찾는 중.」 다음 날 다시 212.<br><br>211인 날이 일곱 번 있다. 그때마다 다음 날 212로 돌아온다. 사감은 결석한 아이를 반드시 찾아온다. 찾은 날 일지 귀퉁이에 침대 번호가 적혀 있다. 전부 빈 침대 번호다.<br>오늘 남은 빈 침대 번호를 외웠다. 그 호실 근처에는 아무도 가지 않게 했다. 열쇠 소리가 사감실 앞을 지나갔다.<br><br>기록은 매일 같을 때보다 하루 틀릴 때 말을 한다. 같은 줄 천 개 사이에서 틀린 하루를 집어내는 눈이 생겼다.`,
      ng:`줄을 따라 내려가는데 오늘 줄의 빈칸이 채워진다. 번진 글씨로. 손이 안 보이는데.<br><br>「현원 211.」 일행 수를 뺀 숫자다. 그다음 글자가 이어진다. 「결석 —」.<br>일지를 덮고 책상 밑으로 들어갔다. 열쇠 소리가 문 앞에서 오래 멈췄다. 책상 밑 물이 턱까지 찼다. 숨을 아꼈다. 가슴이 터질 것 같았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20, spirit:-18 } },
    { l:'② 일지를 그대로 두고 사감실을 빠져나간다.', k:'hide', dc:22,
      ok:`일지에 손대지 않았다. 의자도 그대로 두었다. 물을 젓지 않고 문 쪽으로 갔다.<br><br>열쇠 소리가 복도 모퉁이를 돈다. 그 반대쪽으로 빠졌다. 모퉁이 하나를 사이에 두고 엇갈렸다.<br>등 뒤에서 사감실 문이 열리고 닫혔다. 펜으로 무언가 적는 소리. 오늘 줄이 채워졌다. 숫자는 보지 못했다.`,
      ng:`빠져나가다 문턱에 걸렸다. 물이 첨벙 튄다. 작은 소리다. 그래도 났다.<br><br>열쇠 소리가 멈춘다. 그리고 빨라진다. 찰랑찰랑찰랑.<br>복도를 내달렸다. 물이 다리를 붙잡는다. 계단참까지 쫓겼다. 숨이 끊어질 것 같았다. 열쇠 소리는 계단 앞에서 멈췄다. 사감은 층을 바꾸지 않는다. 다행히도.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } },
    { l:'③ 책상 서랍을 연다.', k:'luck', dc:21,
      ok:`맨 아래 서랍이 물 밖이다. 열었다. 기름종이로 싼 꾸러미가 있다.<br><br>말린 고기다. 사감이 밤 점호 뒤에 혼자 먹던 것이다. 학생들에게 몰래 나눠 주던 것인지도 모른다. 꾸러미가 여러 개로 나뉘어 있다. 한 사람 몫씩.<br>하나를 집었다. 나머지는 그대로 두었다. 서랍을 닫는데 일지 오늘 줄에서 펜이 조금 움직였다.`,
      ng:`서랍을 열자 열쇠가 쏟아진다. 수십 개. 호실 번호가 붙어 있다.<br><br>그 소리가 복도로 퍼진다. 찰랑. 대답하듯이 복도 끝에서도 찰랑.<br>서랍을 닫을 새도 없이 물속에 웅크렸다. 사감실 문 앞에 무엇이 섰다. 오래. 이쪽을 세는 것 같았다. 물속에서 숨을 참은 가슴이 아직도 아프다.`,
      win:{ exp:15, item:'말린 고기' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 넘어가는 책갈피',
  x:`늘 책 한 권을 품에 넣고 다닌다. 쉬는 틈에 폈다.<br><br>
    책갈피가 어제보다 열 장 뒤에 꽂혀 있다. 거기까지 읽은 적이 없다.<br>
    넘겨 보니 책갈피가 지나간 장은 글씨가 없다. 하얗다. 책갈피 앞쪽 장은 그대로다.<br><br>
    누가 이쪽 책을 읽고 있다. 읽은 데를 가져가면서.`,
  o:[
    { l:'① 비어 버린 장의 앞뒤를 맞춰 무엇을 가져갔는지 본다.', k:'gaze', dc:22,
      ok:`하얀 장 앞뒤를 맞춰 봤다. 앞장 끝 문장과 뒷장 첫 문장이 이어지지 않는다. 그 사이에 무엇이 있었는지 짐작이 간다.<br><br>사람들이 주고받는 말이다. 대화만 빠졌다. 서술은 남았다. 읽는 것이 말하는 법을 배우고 있다. 사람 사이의 말을.<br>그날 밤부터 부르는 목소리가 조금 자연스러워졌다. 그래도 이쪽은 안다. 이 책에서 배운 말투다. 그 말투로 부르면 대답하지 않는다.`,
      ng:`맞춰 보는 동안 책장이 한 장 저절로 넘어간다. 이쪽 손가락 밑에서.<br><br>지금 펼친 장의 글씨가 한 줄씩 지워진다. 위에서부터. 누가 읽어 내려가는 속도로.<br>책을 덮었다. 덮은 책 속에서 장 넘기는 소리가 계속 났다. 품에 넣지 못하고 바닥에 두었다. 아끼던 책이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-22, spirit:-20 } },
    { l:'② 책갈피 뒤쪽 장을 모두 찢어 불에 넣는다.', k:'break', dc:22,
      ok:`책갈피 뒤쪽을 한꺼번에 뜯었다. 아끼던 책이다. 손이 망설였다. 그래도 뜯었다.<br><br>불에 넣었다. 종이가 오그라들며 탄다. 타는 소리 사이로 누가 아쉬워하는 숨이 섞였다.<br>그날 밤 책갈피는 움직이지 않았다. 남은 책은 반쪽이다. 반쪽이라도 끝까지 읽을 수 있는 반쪽이다.`,
      ng:`찢는데 책갈피가 따뜻하다. 사람 손가락 하나만큼.<br><br>책갈피를 뽑아 던졌다. 바닥에서 저 혼자 미끄러져 어둠 쪽으로 간다. 그쪽에 누가 펼친 손바닥이 있는 것처럼.<br>찢은 장은 불에 넣었다. 남은 장 가운데 몇 장이 젖어 있다. 침 묻은 손가락으로 넘긴 자국이다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 들려주면 멈추는 것',
  x:`복도 끝 어둠에서 무엇이 다가온다. 발소리가 작다. 아이 키다.<br><br>
    일행 하나가 중얼거리던 셈을 멈추자 발소리가 빨라졌다. 다시 세자 멈췄다.<br>
    말을 듣는 동안은 멈춘다. 듣는 걸 좋아한다. 듣다 끝나면 다가온다.<br><br>
    머릿속에는 들려줄 것이 많다. 끝이 있는 것도, 끝이 없는 것도.`,
  o:[
    { l:'① 아는 이야기를 처음부터 들려준다.', k:'steady', dc:22,
      ok:`긴 이야기를 골랐다. 천천히 시작했다. 발소리가 멈춘다. 어둠 속에서 쪼그려 앉는 기척이 난다.<br><br>걸으면서 이야기했다. 이야기가 끝으로 갈수록 그것이 몸을 앞으로 기울인다. 숨소리가 가까워진다. 일부러 옆길로 샜다. 이야기 속 사람이 길을 잃게 했다.<br>복도 끝 문에 닿았을 때 이야기를 끝냈다. 문을 닫자마자 문 너머에서 작은 손이 문을 두드렸다. 그다음은? 그다음은?`,
      ng:`이야기를 시작했는데 생각보다 일찍 끝으로 간다. 머릿속 책장이 저절로 넘어간다.<br><br>「그래서 다 잘 살았대.」 말하고 아차 했다. 조용하다.<br>발소리가 뛰어온다. 다리 사이를 무엇이 빠르게 지나갔다. 정강이에 이빨 자국 같은 것이 남았다. 아이 이빨이다. 복도 끝까지 달렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 끝이 없는 것을 읽어 준다 — 책 뒤의 찾아보기를.', k:'gaze', dc:22, wake:1,
      ok:`머릿속에서 두꺼운 책 맨 뒤를 폈다. 찾아보기. 「가랑비, 십이 쪽. 가래, 사십 쪽. 가로등, 백일 쪽.」<br><br>이야기가 없다. 끝도 없다. 다음 낱말이 계속 온다. 발소리가 멈췄다. 기다린다. 아무 일도 안 일어난다. 그래도 다음이 있다.<br>어둠 속 숨소리가 고르게 늘어졌다. 잠든 아이 숨이다. 그 옆을 낮은 목소리로 읽으며 지났다. 「하늘, 삼백 쪽. 하품, 삼백이 쪽.」<br><br>읽는 것에도 쓰임이 있다. 무엇을 골라 읽어 주느냐가 길이 되기도 한다. 머릿속 책장이 이제 연장통처럼 보인다.`,
      ng:`찾아보기를 읽는데 한 낱말에서 혀가 굳는다. 처음 보는 낱말이다. 사람 이름 같다.<br><br>그 낱말을 읽자 숨소리가 멈춘다. 어둠 속에서 무엇이 벌떡 일어선다. 제 이름을 들은 것이다.<br>복도를 거꾸로 달렸다. 등 뒤로 발소리가 붙었다가 떨어졌다. 한참을 돌아서 겨우 다른 길로 빠졌다. 그 낱말이 머릿속에서 지워지지 않는다.`,
      win:{ exp:23, dream:3, mind:6 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'인형극 무대 — 노래 가사집',
  x:`인형극 무대 앞 보면대에 가사집이 있다. 「방글 동산 다 같이 노래」. 1절, 2절, 후렴.<br><br>
    3절이 있다. 아래에 작게 적혀 있다. 「3절은 방송에서 부르지 않음」.<br>
    3절 가사에 빈칸이 있다. 「○○야, ○○야, 동산으로 오너라」. 음표 위에.<br><br>
    무대 위 손 인형들이 고개를 든다. 반주가 시작된다. 1절이다.`,
  o:[
    { l:'① 빈칸에 이름 아닌 것을 넣어 부른다.', k:'bond', dc:23,
      doom:{ title:'3절', what:'손 인형들에게 무대 막 뒤로 끌려 들어갑니다', dc:18, sec:50,
        text:`3절이 왔다. 빈칸에 지어낸 이름을 넣어 불렀다. 아무도 아닌 이름이다.<br><br>손 인형들이 일제히 이쪽을 본다. 지어낸 이름은 주인이 없다. 주인 없는 이름은 부른 사람 것이 된다.<br>무대 아래에서 손들이 올라온다. 인형 속에 들어가 있던 손들이다. 인형을 벗은 손. 발목을, 무릎을 쥔다.<br><br>무대 막 뒤로 끌려 들어간다. 반주가 후렴으로 넘어간다. 막 안쪽이 따뜻하고 좁다. 손이 많다.`,
        dieText:`반주가 끝났다. 손 인형들이 고개를 숙인다.<br><br>무대 위에 인형이 하나 늘었다. 새 인형이다. 아직 이름표가 없다. 얼굴이 낯익다.<br>가사집 3절 빈칸이 채워졌다. 처음 보는 이름이다. 이쪽이 지어낸 이름이다.` },
      ok:`빈칸에 「아무개야, 아무개야」를 넣어 불렀다. 이름이 아니라 이름의 자리다.<br><br>손 인형들이 두리번거린다. 아무개가 누군지 찾는다. 아무도 아니다. 모두이기도 하다.<br>인형들이 서로를 본다. 제가 아무개인지 모른다. 그사이 무대 앞을 지났다. 후렴이 끝날 때 인형들이 다 같이 고개를 숙였다. 서로를 부른 것처럼.`,
      win:{ exp:24, dream:4 } },
    { l:'② 3절 박자를 세어 끼워 넣은 줄을 찾는다.', k:'gaze', dc:22,
      ok:`1절과 2절은 줄마다 넷, 넷이다. 3절 셋째 줄만 넷, 다섯이다. 한 글자가 남는다.<br><br>남는 글자는 「와」다. 오라는 글자. 원래 노래에 없던 글자다. 누가 끼워 넣었다.<br>3절이 오기 전에 일행에게 입을 다물게 했다. 그 줄만 아무도 안 부르면 노래가 한 박자 빈다. 반주가 비틀거렸다. 인형들이 박자를 놓쳤다. 그사이 무대를 지났다.`,
      ng:`세다가 후렴이 끝났다. 2절이 끝났다. 생각보다 빠르다.<br><br>3절 반주가 시작된다. 입이 저절로 열린다. 「○○야」. 이쪽 이름이 들어간다. 첫 음만.<br>손으로 입을 틀어막았다. 인형들이 한꺼번에 고개를 돌렸다. 무대 앞을 기어서 빠져나왔다. 목구멍 안쪽이 노래를 다 못 부른 채 오래 근질거렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 가사집을 보면대에서 내려 엎어 둔다.', k:'hide', dc:22,
      ok:`반주가 1절일 때 보면대 쪽으로 몸을 낮춰 갔다. 가사집을 내려 바닥에 엎었다.<br><br>가사가 안 보이면 3절은 없다. 방송에서 안 부른 노래는 적혀 있어야만 불린다.<br>2절이 끝나고 반주가 처음으로 돌아갔다. 1절. 인형들이 같은 노래를 다시 불렀다. 그 노래를 등 뒤에 두고 무대를 빠져나왔다.`,
      ng:`가사집을 내리는데 보면대가 쓰러진다. 쇳소리가 무대에 울린다.<br><br>인형들이 노래를 멈추고 이쪽을 본다. 반주만 혼자 간다. 3절로.<br>엎어 둔 가사집 아래에서 종이 넘기는 소리가 났다. 무대를 등지고 뛰었다. 넘어져 손바닥이 찢어졌다. 등 뒤에서 3절이 한 소절 불렸다. 아이 목소리 하나로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 — 교가 석판',
  x:`종탑 계단참 벽에 석판이 박혀 있다. 교가를 새겼다. 「맑은 물 굽이도는 언덕 위에」.<br><br>
    4절까지 있다. 1절부터 3절은 정으로 새긴 날카로운 글씨다. 4절만 획 끝이 둥글다. 물에 오래 깎인 것처럼.<br>
    그런데 석판은 물 위에 있다. 물이 여기까지 온 적은 없다.<br><br>
    계단 아래 물속에서 누가 흥얼거린다. 가락이 교가다.`,
  o:[
    { l:'① 둥근 획 끝으로 4절이 어떻게 새겨졌는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`획 끝을 손가락으로 쓸었다. 정 자국이 없다. 반들반들하다. 무엇으로 판 게 아니다. 같은 자리를 수없이 쓸어서 팬 것이다. 손가락으로. 매일.<br><br>4절을 읽었다. 「아침 일곱 시 저녁 아홉 시 / 한 사람도 빠짐없이」. 점호 노래다. 교가 끝에 점호가 붙어 있다. 흥얼거림이 4절에 닿으면 점호가 시작된다.<br>물속 흥얼거림이 3절로 넘어갔다. 계단을 서둘러 올라 위층 종탑 들보 밑에 숨었다. 4절이 끝나자 물속에서 이름을 부르기 시작했다.<br><br>닳은 자리는 손이 몇 번 지나갔는지를 말한다. 새긴 글과 닳은 글을 가려 읽는 눈이 생겼다. 돌에서 손길이 읽힌다.`,
      ng:`손가락으로 쓸어 보다 손끝이 그 홈에 맞는다는 걸 알았다. 꼭 맞는다. 이쪽 손가락 굵기다.<br><br>손가락이 저절로 획을 따라간다. 아침 일곱 시. 저녁 아홉 시. 한 사람도.<br>떼려는데 떨어지지 않는다. 일행이 손목을 잡아 뜯어냈다. 손끝 살갗이 벗겨졌다. 돌에 이쪽 지문이 하얗게 남았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 4절을 젖은 흙으로 덮어 바른다.', k:'fix', dc:22,
      ok:`계단참 구석에 쌓인 비둘기 똥과 젖은 흙을 이겨 4절 위에 발랐다. 홈이 다 메워지게.<br><br>물속 흥얼거림이 3절 끝에서 멈춘다. 다음 가사를 찾는다. 석판에 없으면 노래도 없다.<br>흥얼거림이 3절을 다시 부른다. 또 멈춘다. 그 사이를 틈타 계단을 지났다. 손에서 고약한 냄새가 오래 났다.`,
      ng:`바르는 사이 흥얼거림이 4절에 닿았다. 바르지 못한 마지막 줄이 남았다.<br><br>「한 사람도 빠짐없이」. 물속에서 이름이 불린다. 맨 처음 이름이 이쪽이다.<br>입을 앙다물었다. 대답이 이 사이로 새어 나오려 한다. 한참을 그렇게 서 있었다. 턱이 저려 감각이 없어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 이쪽 글씨의 쪽지',
  x:`쉬다 일어나니 무릎 위에 쪽지가 있다. 이쪽 글씨다. 확실히 이쪽 글씨다.<br><br>
    「다음 문은 열지 말 것. 맨 뒤에 있는 사람은 일행이 아님.」<br>
    쓴 기억이 없다. 돌아보면 맨 뒤에 일행이 하나 서 있다. 등불 밖이라 얼굴이 반만 보인다.<br><br>
    그 일행도 손에 쪽지를 쥐고 있다.`,
  o:[
    { l:'① 쪽지의 획 하나하나를 이쪽 버릇과 견준다.', k:'gaze', dc:22,
      ok:`이쪽 글씨는 이쪽이 제일 잘 안다. 받침 ㅎ의 꼭지를 떼어 쓰는 버릇. 오래전에 고친 버릇이다. 지금은 붙여 쓴다.<br><br>쪽지의 ㅎ은 꼭지가 떨어져 있다. 어릴 때 글씨다. 누가 이쪽의 옛 글씨를 보고 베꼈다. 지금의 이쪽을 모르는 손이다.<br>쪽지를 접어 버렸다. 맨 뒤 일행에게 손짓했다. 그 사람도 제 쪽지를 펴 보였다. 「맨 앞에 있는 사람은 일행이 아님.」 그 사람 옛 글씨였다. 둘 다 태웠다.`,
      ng:`견주는데 이쪽 버릇이 무엇이었는지 헷갈린다. 꼭지를 붙였던가, 뗐던가.<br><br>쪽지 글씨가 볼수록 맞다. 이쪽이 쓴 것 같다. 쓴 기억이 없는데.<br>맨 뒤 일행을 오래 봤다. 그 사람도 이쪽을 오래 봤다. 둘 다 한 발짝씩 물러섰다. 그 뒤로 다음 쉬는 자리까지 둘은 서로 등을 보이지 않았다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ mind:-22, spirit:-20 } },
    { l:'② 쪽지를 맨 뒤 일행에게 그대로 보여 준다.', k:'bond', dc:22,
      ok:`숨기지 않았다. 다가가 쪽지를 내밀었다.<br><br>그 사람 얼굴이 굳는다. 제 쪽지를 내민다. 「맨 앞에 있는 사람은 일행이 아님.」 그 사람 글씨다.<br>둘이 나란히 쪽지를 들고 서 있었다. 그러다 웃음이 났다. 이걸 쓴 것은 일행을 쪼개고 싶었다. 쪼개지지 않았다. 쪽지를 같이 불에 넣었다.`,
      ng:`다가가 내밀었다. 그 사람이 반 걸음 물러선다. 등불 밖으로.<br><br>얼굴이 안 보인다. 「이리 와서 봐.」 그 사람 목소리다. 조금 낮다.<br>망설이는 사이 그 사람이 등불 안으로 들어왔다. 진짜 일행이다. 놀란 얼굴이다. 그런데 방금 들은 목소리는 등불 밖, 그 사람 등 뒤에서 났다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-20, spirit:-26 } }
  ] }

]);

// ------------------------------------------
// 주술사 · 마력
// ------------------------------------------
kJob('hexer', 'A', [

{ at:'A', t:'복도 — 발목 높이의 붉은 실',
  x:`복도를 가로질러 실 한 가닥이 걸려 있다. 발목 높이다. 붉다. 등불을 대야 겨우 보인다.<br><br>
    양 끝이 벽에 박힌 못에 감겼다. 한쪽 못에서 실이 벽을 타고 위로, 어둠 속으로 이어진다. 그 끝 어딘가에 방울이 달렸다. 바람에 아주 작게 운다.<br>
    매듭이 실 가운데 하나 있다. 묶는 매듭이 아니다. 세는 매듭이다. 지나간 수만큼 한 번씩 꼬이는.<br><br>
    꼬임이 아홉이다. 열이 되면 무엇이 오는지는 실을 맨 손만 안다.`,
  o:[
    { l:'① 매듭의 꼬임을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`꼬임은 지나간 수를 센다. 그런데 세는 건 발이 아니다. 실이 흔들린 수다. 넘는 발이 실을 건드리면 한 번.<br><br>그러니 안 건드리면 안 센다. 매듭 꼬임 방향을 보면 실이 어느 쪽으로 흔들릴 때 감기는지도 보인다. 왼쪽으로 흔들릴 때만 감긴다.<br>일행에게 오른발부터, 실 오른쪽으로 크게 넘게 했다. 다섯이 넘었다. 꼬임은 아홉에서 멈춰 있었다.<br><br>매듭은 묶인 모양이 아니라 꼬인 방향으로 읽는다. 남이 맨 매듭 안에서 그 매듭이 무엇을 기다리는지가 보인다. 손이 매듭을 보면 먼저 방향을 더듬는다.`,
      ng:`꼬임을 세느라 허리를 숙였다. 머리카락 한 올이 실에 닿았다.<br><br>꼬임이 열이 됐다. 위쪽 어둠에서 방울이 한 번 크게 울었다. 그리고 무엇이 벽을 타고 내려오는 소리가 났다. 손톱이 벽지를 긁는 소리.<br>다 같이 뛰었다. 등 뒤에서 방울 소리가 바닥까지 내려왔다. 복도 끝 문을 닫고 등을 댔다. 문 너머에서 아홉 번, 열 번 실 꼬는 소리가 들렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마력을 써서 매듭을 거꾸로 다시 맨다.', k:'gaze', dc:23, cost:{ mana:28 },
      ok:`매듭에 손끝을 대고 마력을 흘렸다. 꼬임을 하나씩 풀어 거꾸로 감았다. 열이 되면 오는 것이 아니라, 열이 되면 돌아가는 것으로.<br><br>다 감고 일부러 실을 툭 건드렸다. 꼬임이 열이 됐다.<br>위쪽 어둠에서 방울이 울었다. 그리고 무엇이 벽을 타고 올라가는 소리. 멀어진다. 위로, 더 위로.<br><br>실은 그대로 두고 넘었다. 다음에 넘는 사람도 돌려보낼 것이다.`,
      ng:`거꾸로 감는데 매듭이 손끝을 문다. 실이 손가락에 한 바퀴 감긴다. 꽉.<br><br>마력이 실을 타고 위로 빨려 올라간다. 방울이 미친 듯이 운다. 손가락 끝이 하얗게 질렸다.<br>이로 실을 끊었다. 입술이 실에 베였다. 끊긴 실이 위로 휙 딸려 올라갔다. 손가락에 붉은 고리 자국이 남았다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ hp:-24, spirit:-20, mana:-5 } },
    { l:'③ 실을 건드리지 않게 조심조심 넘는다.', k:'evade', dc:23,
      doom:{ title:'열 번째', what:'붉은 실에 발목이 감겨 끌려 올라갑니다', dc:18, sec:50,
        text:`숨을 멈추고 발을 들었다. 실 위로. 아주 천천히.<br><br>실이 따라 올라온다. 이쪽 발목 높이에 맞춰. 바람도 없는데. 발을 내려놓는 순간 실이 발목을 한 바퀴 돈다.<br>꼬임이 열이 된다. 위에서 방울이 한 번 운다. 실이 팽팽해진다. 당긴다. 위로.<br><br>발이 바닥에서 뜬다. 거꾸로 매달려 벽을 따라 끌려 올라간다. 어둠 속에서 손톱이 벽지를 긁으며 마중 나온다.`,
        dieText:`복도에 실이 다시 걸렸다. 발목 높이에. 붉게.<br><br>매듭 꼬임이 하나로 돌아갔다. 처음부터 다시 센다.<br>위쪽 어둠에서 방울 소리가 한동안 둘이었다. 하나는 이쪽 신발 끈에 달려 있었다.` },
      ok:`발을 들기 전에 신발을 벗었다. 맨발로 넘었다. 발바닥 땀까지 닦고.<br><br>실이 따라 올라오려다 멈춘다. 실은 가죽 냄새를 따라온다. 맨발엔 냄새가 적다.<br>다 넘고 신발을 실 너머로 던져 건넸다. 실이 신발이 지나간 자리에서 한 번 출렁였다. 꼬임은 아홉에 머물렀다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'A1', t:'의상실 — 실로 묶인 지퍼',
  x:`의상실 한가운데 뭉치가 서 있다. 갈색 털북숭이 인형탈. 걸린 게 아니라 서 있다. 등 지퍼가 목까지 올라갔다.<br><br>
    지퍼 손잡이에 실이 묶였다. 실은 지퍼 틈으로 안쪽에 들어가 있다. 안에서 누가 쥐고 있다.<br>
    매듭이 손잡이에 세 번 감겼다. 안에서 맨 매듭이다. 밖에서 열지 못하게.<br><br>
    탈 안에서 숨소리가 난다. 땀 냄새는 안 난다.`,
  o:[
    { l:'① 바깥쪽 손잡이에 이쪽 매듭을 덧맨다.', k:'fix', dc:22, wake:1,
      ok:`안에서 맨 매듭은 안에서 여는 매듭이다. 밖에서 막으려면 밖에서도 맨다.<br><br>품에서 실을 꺼내 손잡이에 감았다. 안쪽 매듭과 반대 방향으로 세 번. 이제 안에서 당기면 밖의 매듭이 조인다.<br>탈 안에서 실을 당기는 기척이 났다. 지퍼가 한 칸 내려가려다 멈춘다. 다시 당긴다. 멈춘다.<br><br>남이 맨 매듭에 맞매듭을 거는 손이 생겼다. 한 실에 두 뜻을 묶으면 서로를 잡는다. 손가락이 그 감기는 방향을 이제 저절로 안다.`,
      ng:`감는 사이 지퍼가 한 칸 내려갔다. 안에서 당겼다.<br><br>틈으로 안이 보인다. 털 안쪽에 털이 또 있다. 그 안쪽에 눈이 하나.<br>매듭을 마저 감았다. 손이 떨려 엉성하다. 지퍼는 그 칸에서 멈췄다. 의상실을 나올 때까지 그 틈에서 눈이 이쪽을 따라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 지퍼 틈으로 들어간 실을 읽는다.', k:'gaze', dc:22,
      ok:`실이 지퍼 틈에서 어느 쪽으로 기울었는지 봤다. 아래로 처졌다. 쥔 손이 허리 높이다. 아이 키다.<br><br>그리고 실이 가늘게 떤다. 쥔 손이 떨고 있다. 안에서 맨 매듭은 나오려는 매듭이 아니다. 아무도 못 들어오게 맨 매듭이다.<br>지퍼를 건드리지 않았다. 의상실 문을 닫아 주었다. 숨소리가 조금 느려졌다.`,
      ng:`실을 들여다보는데 실이 이쪽으로 기운다. 지퍼 틈에서 실이 한 뼘 더 나온다.<br><br>실 끝이 이쪽 손가락을 찾는다. 감으려고. 손을 뺐다.<br>털북숭이 머리가 천천히 이쪽으로 돈다. 몸은 그대로. 의상실을 나올 때 등 뒤에서 지퍼 내려가는 소리가 났다. 끝까지 듣지 않고 뛰었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'기숙사 — 바늘이 꽂힌 명찰',
  x:`기숙사 호실 옷장 문이 열려 있다. 교복이 걸렸다. 가슴에 명찰을 꿰매는 중이다. 손은 안 보이는데 바늘이 움직인다.<br><br>
    맨 끝 교복 명찰은 반쯤 꿰맸다. 이쪽 이름이다. 실이 이름 획을 따라 들어갔다 나온다. 바늘이 아직 꽂혀 있다.<br>
    박음질이다. 한 땀 뒤로 가서 두 땀 앞으로. 쉽게 안 풀리게 박는 바느질이다.<br><br>
    한 획이 남았다. 바늘이 천천히 그 획으로 간다.`,
  o:[
    { l:'① 땀의 순서를 읽어 거꾸로 푼다.', k:'gaze', dc:22, wake:1,
      ok:`박음질은 끝에서부터 풀면 엉킨다. 첫 땀이 어디인지부터 찾았다. 이름 첫 획 머리, 실 매듭이 숨은 데.<br><br>거기서부터 한 땀씩 거꾸로 뽑았다. 뒤로 하나, 앞으로 둘을 뒤집어서. 이름이 한 획씩 지워진다. 바늘이 움직이다 길을 잃고 멈췄다.<br>마지막 땀을 뽑자 명찰이 그냥 헝겊이 됐다. 옷장 안 다른 교복들이 조금 흔들렸다.<br><br>바느질도 매듭이다. 시작을 찾으면 끝까지 풀린다. 박힌 이름을 땀 하나하나로 읽고 거슬러 뽑는 손이 생겼다.`,
      ng:`첫 땀을 찾는 사이 바늘이 마지막 획에 닿았다. 한 땀.<br><br>가슴이 따끔하다. 옷 너머로. 명찰 자리다. 바늘이 이쪽 옷에도 들어간 것처럼.<br>명찰을 칼로 도려냈다. 실이 질기다. 손등을 몇 번이고 그었다. 도려낸 명찰을 물에 던졌다. 가라앉지 않고 떠서 이쪽을 향해 흘러왔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 바늘을 한 번에 뽑아 버린다.', k:'break', dc:23,
      doom:{ title:'박음질', what:'실에 꿰여 옷장 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`바늘을 잡아 확 뽑았다. 실이 길게 딸려 나온다. 끝이 안 보인다.<br><br>뽑힌 실이 손목을 한 바퀴 감는다. 바늘이 저 혼자 움직인다. 이쪽 소매에 한 땀. 앞으로 둘, 뒤로 하나.<br>옷장 안 교복들이 일제히 소매를 든다. 실이 당겨진다. 이쪽 소매가 교복 소매에 박혀 간다.<br><br>끌려 들어간다. 옷장 안으로. 교복과 교복 사이에 한 사람 자리가 비어 있다. 거기 걸린다.`,
        dieText:`옷장 문이 닫혔다. 안에서 바늘 소리가 조금 더 났다.<br><br>다음 점호 때 옷장 앞에서 열쇠 소리가 멈췄다. 하나, 둘. 걸린 교복 수를 센다.<br>맨 끝 교복 명찰이 다 꿰매져 있다. 교복 안이 사람 모양으로 부풀어 있다.` },
      ok:`바늘을 뽑기 전에 실 끝을 이쪽 엄지에 감아 쥐었다. 그리고 뽑았다.<br><br>실이 딸려 나온다. 끝까지. 엄지에서 감긴 채 멈춘다. 끝이 이쪽에 있으면 실은 이쪽 것이다.<br>실째 둘둘 말아 등불에 태웠다. 명찰의 이름이 반쯤 꿰맨 채로 풀려 흐려졌다. 옷장 문이 저절로 닫혔다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 마력을 실어 마지막 획에 다른 이름을 박는다.', k:'fix', dc:22, cost:{ mana:30 },
      ok:`바늘을 잡지 않고 실을 잡았다. 마력을 실어 마지막 획을 비틀었다. 이쪽 이름이 아닌 이름으로 끝나게.<br><br>획 하나만 바꿔도 다른 이름이 된다. 아무도 아닌 이름.<br>바늘이 마지막 땀을 박고 매듭을 지었다. 명찰은 다 됐다. 아무도 그 이름을 안 쓴다. 옷장 안 교복 하나가 영영 주인을 기다리게 됐다.`,
      ng:`비틀던 획이 손에서 미끄러진다. 마력이 실을 타고 바늘로 간다. 바늘이 그걸 먹고 빨라진다.<br><br>한 획이 아니라 두 획이 박혔다. 명찰 이름이 이쪽 이름과 반쯤 같고 반쯤 다르다.<br>가슴이 이상하게 무겁다. 반쯤 불린 사람처럼. 그 무게가 다음 층까지 따라왔다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-26, mana:-5 } }
  ] },

{ at:'A', t:'쉬는 자리 — 하나 많은 인형',
  x:`쉬려고 둘러앉은 자리 둘레에 작은 인형들이 놓여 있다. 헝겊과 머리카락으로 만들었다.<br><br>
    다섯이다. 일행 수다. 저마다 일행 하나씩을 향해 앉혀 놓았다. 머리카락 색이 하나씩 맞는다.<br>
    여섯째가 하나 더 있다. 그것만 일행 모두를 등지고 어둠 쪽을 보고 있다.<br><br>
    누가 먼저 와서 앉혀 둔 것이다. 이쪽이 여기 앉을 줄 알았던 손이다.`,
  o:[
    { l:'① 마력을 써서 여섯째를 일행 쪽으로 돌려 앉힌다.', k:'gaze', dc:22, cost:{ mana:27 }, wake:1,
      ok:`다섯은 이쪽을 보는 인형이다. 보는 쪽이 보이는 쪽을 쥔다. 여섯째는 어둠을 본다. 어둠에 있는 무엇을 이쪽으로 부르는 인형이다.<br><br>여섯째를 집어 마력을 불어넣고 돌렸다. 이쪽 일행을 보게. 이제 그 인형은 이쪽 편이다. 다섯 인형을 하나씩 집어 어둠 쪽으로 돌려 앉혔다. 이쪽을 보던 눈들이 밖을 지킨다.<br>밤새 어둠에서 무엇이 가까이 왔다가 인형 여섯과 눈이 마주치고 물러갔다.<br><br>남이 놓은 인형도 방향만 바꾸면 이쪽 것이 된다. 놓인 물건이 어디를 보는지 먼저 읽는 버릇이 손에 붙었다.`,
      ng:`여섯째를 돌리는데 목이 돌아가지 않는다. 몸만 돈다. 머리는 계속 어둠을 본다.<br><br>마력이 인형 목에서 걸려 버린다. 인형 안쪽에서 무엇이 버틴다. 손바닥이 차갑다.<br>억지로 비틀자 머리카락 매듭이 툭 끊겼다. 인형 머리가 떨어져 어둠 쪽으로 굴러갔다. 그 밤 아무도 눈을 붙이지 못했다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-24, mana:-5 } },
    { l:'② 인형 여섯을 한데 모아 태운다.', k:'break', dc:22,
      ok:`여섯을 모았다. 머리카락이 서로 엉키지 않게 하나씩 떼어. 불에 넣었다.<br><br>머리카락 타는 냄새가 났다. 인형마다 타는 소리가 다르다. 다섯은 바삭하고 여섯째만 젖은 소리가 난다.<br>다 타고 나서 일행 모두 머리를 한 번씩 만져 봤다. 아무도 빠진 데가 없었다. 그 자리를 떠나 다른 데서 쉬었다.`,
      ng:`모으는데 다섯째 인형이 손에서 따뜻하다. 머리카락이 이쪽 머리 색이다.<br><br>불에 넣자 이쪽 머리 꼭대기가 화끈거린다. 타는 냄새가 이쪽 머리에서도 난다.<br>인형을 꺼내 발로 비볐다. 정수리에 손바닥만 한 데가 그을린 것처럼 아팠다. 거울은 보지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'계단 — 이름을 가져가는 부름',
  x:`계단 아래에서 누가 이름을 부른다. 일행 하나의 이름이다. 한 번.<br><br>
    불린 일행이 고개를 갸웃한다. 제 이름이 무엇이었느냐고 묻는다. 정말로 모른다.<br>
    부르는 것은 이름을 가져간다. 다음 이름을 고르는 숨이 계단 아래에서 올라온다.<br><br>
    이름은 매듭이다. 사람과 몸을 묶어 둔 매듭. 그 매듭을 풀어 가는 소리다.`,
  o:[
    { l:'① 가짜 이름을 종이에 매어 쥐고 대신 대답한다.', k:'gaze', dc:23,
      doom:{ title:'가짜 이름', what:'가짜 이름을 따라 계단 아래로 끌려갑니다', dc:18, sec:50,
        text:`지어낸 이름을 마음속으로 정했다. 부르는 것이 이쪽을 부를 때 그 이름으로 대답했다.<br><br>대답이 너무 빨랐다. 지어낸 이름이 종이에 매이지 못하고 이쪽 혀에 붙었다. 진짜 이름이 떠오르지 않는다. 지어낸 이름만 남았다.<br>계단 아래에서 그 이름을 부른다. 다정하게. 이제 그것만이 이쪽 이름이다. 몸이 대답하듯 계단을 내려간다.<br><br>일행이 붙잡는다. 진짜 이름을 불러 준다. 낯선 말처럼 들린다. 발이 계속 내려간다. 끌려가는 쪽이 이쪽이 아니라 이름이다.`,
        dieText:`계단 아래에서 대답 소리가 났다. 지어낸 이름으로.<br><br>그 뒤로 부르는 소리가 그쳤다. 한 사람 몫으로 배가 부른 것처럼.<br>일행은 끝까지 진짜 이름을 기억했다. 계단 맨 아래 벽에 그 지어낸 이름이 손톱으로 새겨져 있었다.` },
      ok:`지어낸 이름을 종이에 적었다. 종이를 실로 감아 매듭을 짓고 손에 쥐었다. 이름을 이쪽 혀가 아니라 매듭에 묶었다.<br><br>부르는 것이 이쪽을 불렀다. 매듭을 쥔 채 지어낸 이름으로 대답했다.<br>종이가 손에서 쑥 빠져나간다. 계단 아래로. 어둠이 그것을 받아 간다. 이쪽 이름은 이쪽에 그대로 있다.<br><br>먼저 이름을 잃은 일행의 손바닥에 그 사람 이름을 실로 감아 주었다. 조금씩 돌아왔다.`,
      win:{ exp:24, dream:4, mind:6 } },
    { l:'② 다들 손가락을 깨물고 속으로 제 이름을 왼다.', k:'steady', dc:22,
      ok:`손가락 끝을 깨물게 했다. 아픈 데가 있으면 몸이 제 것인 줄 안다. 그리고 속으로 제 이름을 쉼 없이 외게 했다.<br><br>계단 아래에서 이름이 불린다. 외는 이름과 부르는 이름이 겹친다. 이쪽이 먼저 쥐고 있으면 가져가지 못한다.<br>부르는 소리가 몇 번 헛돌다 멀어졌다. 손가락에 이 자국이 남았다. 이름 하나 지키는 데 그 정도는 싸다.`,
      ng:`외는데 부르는 소리가 이쪽 외는 박자를 따라온다. 한 박자 앞서서.<br><br>이쪽 이름을 이쪽보다 먼저 말한다. 머릿속에서 이름이 반쯤 빠져나간다. 첫 글자만 남는다.<br>손가락을 피가 나도록 깨물었다. 겨우 붙들었다. 계단을 다 내려와서도 한동안 이름 끝 글자가 낯설었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-22 } }
  ] },

{ at:'A1', t:'방청석 — 손등의 웃는 해',
  x:`방청석에 앉자 손등이 간지럽다. 보니 도장이 찍혀 있다. 웃는 해 모양. 붉은 인주.<br><br>
    언제 찍혔는지 모른다. 일행 손등에도 다 있다. 로비에서 본 종이가 떠오른다. 재입장 도장.<br>
    표식이다. 손등에 찍는 표식은 그 손이 누구 것인지를 적는다.<br><br>
    방청석 위 표지판이 깜빡인다. 박수. 박수를 치려면 손등이 위로 간다. 무대에서 다 보인다.`,
  o:[
    { l:'① 표식이 무엇을 묶는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`해 모양을 들여다봤다. 햇살이 열두 갈래다. 갈래 끝이 모두 안쪽으로 굽었다. 바깥으로 비추는 해가 아니다. 안으로 거두는 해다.<br><br>찍힌 손이 다시 돌아오게 하는 표식이다. 나가도 돌아온다. 끊으려면 갈래 하나를 바깥으로 펴면 된다. 숯으로 갈래 끝 하나를 밖으로 이어 그었다. 일행 손등에도.<br>표지판이 켜졌다. 박수를 쳤다. 손등이 위로 갔다. 무대 쪽에서 아무도 이쪽 손을 세지 않았다.<br><br>표식은 그림이 아니라 문장이다. 선 하나만 고쳐도 뜻이 바뀐다. 남이 찍은 표에서 고칠 한 획을 찾는 눈이 생겼다.`,
      ng:`들여다보는데 도장 인주가 번진다. 손등에서 손목으로. 햇살이 길어진다.<br><br>표지판이 켜졌다. 손이 저절로 마주친다. 짝. 짝. 번진 인주가 손바닥까지 묻는다.<br>무대 쪽 스피커에서 웃음이 났다. 손도장 아주 예쁘게 찍은 친구! 손을 무릎 밑에 숨겼다. 오래도록 손목이 따끔거렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 침을 묻혀 도장을 문질러 지운다.', k:'heal', dc:22,
      ok:`침을 묻혀 손등을 문질렀다. 인주는 침에 약하다. 붉은 해가 번지며 흐려진다.<br><br>다 지워지지는 않았다. 웃는 입만 남았다. 입만 있는 해는 아무것도 못 본다.<br>일행 손등도 하나씩 문질러 주었다. 박수 표지판이 켜졌을 때 다들 손등이 빈 채로 손뼉을 쳤다.`,
      ng:`문지르는데 인주가 지워지지 않고 살갗 속으로 스민다. 붉은 해가 손등 안쪽에서 비친다.<br><br>문지른 자리가 벌겋게 부었다. 해가 더 또렷해졌다.<br>표지판이 켜지자 부은 손등이 저 혼자 위로 올라갔다. 다른 손으로 눌러 내렸다. 손목 뼈가 아플 만큼.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-20 } },
    { l:'③ 손을 주머니에 넣고 박수를 치지 않는다.', k:'hide', dc:23,
      doom:{ title:'박수', what:'방청석 위로 손에서 손으로 실려 갑니다', dc:18, sec:50,
        text:`손을 주머니에 넣었다. 표지판이 켜졌다. 박수. 빈 의자들이 손뼉을 친다. 이쪽만 손이 없다.<br><br>주머니 속 손등이 뜨겁다. 해 도장이 주머니 천을 뚫고 비친다. 붉게. 어두운 방청석에서 그것만 보인다.<br>보이지 않는 손들이 주머니에서 이쪽 손을 꺼낸다. 손등을 위로 해서 높이 든다. 몸이 따라 들린다. 의자 위로.<br><br>손에서 손으로 넘어간다. 앞줄로. 무대로. 몸 밑에서 박수가 끊이지 않는다.`,
        dieText:`표지판이 꺼졌다. 박수도 꺼졌다.<br><br>무대 위 조명 아래에 손 하나가 높이 들려 있다. 손등에 웃는 해. 몸은 조명 밖이라 안 보인다.<br>스피커에서 언니 목소리가 났다. 재입장 고마워요, 친구야.` },
      ok:`손을 주머니에 넣기 전에 주머니 안쪽에 실을 감아 매듭을 지었다. 손을 넣고 그 매듭을 쥐었다.<br><br>표지판이 켜졌다. 이쪽만 손뼉을 안 친다. 손등 도장이 주머니 속에서 뜨거워진다. 그래도 매듭이 손을 묶고 있다. 안 빠진다.<br>보이지 않는 손들이 주머니 둘레를 더듬다 놓았다. 꺼낼 수 없는 손은 셀 수도 없다. 표지판이 꺼질 때 손바닥에 매듭 자국이 깊게 남았다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'세탁실 — 이름 수놓인 교복',
  x:`세탁실 줄에 교복이 줄줄이 널려 있다. 물 밖인데도 젖어 있다. 물기가 안 빠진다.<br><br>
    다들 허리 아래가 젖어 이가 딱딱 부딪친다. 선반 위에 개어 둔 교복은 말라 있다. 따뜻해 보인다.<br>
    마른 교복에도 이름이 수놓여 있다. 이쪽 일행 이름이다. 다섯 벌.<br><br>
    입으라고 개어 둔 옷이다. 입으면 교복 주인이 된다. 교복 주인은 이 학교 학생이다.`,
  o:[
    { l:'① 수실이 무엇으로 되었는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`수를 손톱으로 들어 봤다. 실이 아니다. 머리카락이다. 길고 검다. 꼬아서 실처럼 만들었다.<br><br>입학 매듭이다. 몸에 닿으면 머리카락이 살갗에 뿌리를 내린다. 그러면 이름이 옷이 아니라 몸에 붙는다.<br>칼끝으로 이름 수를 하나씩 뜯어냈다. 머리카락이 꿈틀하다 늘어졌다. 이름 없는 교복은 그냥 마른 천이다. 다들 갈아입고 몸을 녹였다.<br><br>무엇으로 맸는지 알면 무엇을 매어 두려는지 보인다. 실의 재료부터 읽는 손이 생겼다. 손톱이 먼저 실을 들춘다.`,
      ng:`손톱으로 들어 보는데 수실이 손톱 밑으로 파고든다. 가늘게, 깊게.<br><br>빼냈다. 손톱 밑에 검은 털 한 올이 남았다. 뽑히지 않는다. 뿌리를 내렸다.<br>칼끝으로 손톱 밑을 후볐다. 피가 났다. 털이 겨우 빠졌다. 교복은 아무도 입지 않았다. 다들 젖은 채로 떨며 다음 층으로 갔다.`,
      win:{ exp:23, dream:3, hp:8 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 교복을 모두 뒤집어 안팎을 바꿔 입힌다.', k:'fix', dc:22,
      ok:`옷을 뒤집으면 이름이 안쪽으로 간다. 안쪽 이름은 몸에 닿지만 밖에서는 안 보인다.<br><br>그런데 그건 더 나쁘다. 그래서 한 번 더 손을 썼다. 뒤집은 다음 소매를 서로 묶었다. 앞섶을 거꾸로 여몄다. 학교가 입히는 방식과 하나도 맞지 않게.<br>학교 옷이 학교 옷처럼 입혀지지 않으면 교복이 아니다. 다들 우스꽝스러운 꼴로 몸을 녹였다. 복도에서 열쇠 소리가 지나가다 이쪽을 세지 않았다.`,
      ng:`뒤집어 입었다. 안쪽 이름이 살에 닿는다. 차다. 그다음엔 따뜻하다. 너무 따뜻하다.<br><br>가슴에 이름 자국이 남는 느낌이 든다. 허겁지겁 벗었다. 피부에 수놓인 글씨 모양으로 붉은 자국이 나 있다. 거꾸로 된 이름이다.<br>자국은 다음 층에 가서야 옅어졌다. 그동안 일행 하나가 자꾸 이쪽을 다른 이름으로 불렀다.`,
      win:{ exp:18, dream:2, hp:7 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'문 — 안쪽에서 박은 못',
  x:`복도 끝 문이 못으로 막혀 있다. 못 끝이 이쪽으로 튀어나왔다. 안쪽에서 박은 것이다.<br><br>
    못이 열둘이다. 문틀을 따라 둥글게 박혔다. 못마다 머리에 실이 한 번씩 감겼다.<br>
    문 너머에서 아무 소리도 안 난다. 숨소리조차.<br><br>
    일행은 이 문 말고 길이 없다고 한다. 못을 뽑자고 한다.`,
  o:[
    { l:'① 못이 박힌 꼴을 읽는다.', k:'gaze', dc:22,
      ok:`둥글게 박은 못은 가두는 못이다. 막는 못은 일자로 박는다. 열둘이 둥글게. 무엇을 안에 넣고 바깥에서 박은 것처럼 보이지만 안쪽에서 박았다.<br><br>안에 있던 사람이 제 자신을 가뒀다. 안에 든 것이 자기라서. 실 매듭은 문 쪽에서 묶었다. 「열지 마시오」라는 뜻이다.<br>못은 하나도 안 뽑았다. 문 앞 바닥을 두드려 보니 마루 아래가 비었다. 마루를 뜯고 그 아래로 돌아갔다. 문 너머에서 끝내 아무 소리도 나지 않았다.`,
      ng:`읽는 사이 못 하나가 조금 들어갔다. 안쪽으로. 누가 머리를 잡고 당긴 것처럼.<br><br>또 하나. 열둘이 차례로. 둥근 못 고리가 조여 든다. 문틀이 삐걱거린다.<br>물러났다. 문이 안쪽으로 오목하게 휘었다. 무엇이 안에서 숨을 들이쉬어 문을 빨아들인다. 다 같이 뒷걸음질 쳤다. 숨을 쉴 때마다 가슴이 아팠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 못을 하나씩 뽑는다.', k:'break', dc:23,
      ok:`뽑기 전에 못 머리마다 감긴 실을 풀지 않고 그대로 두었다. 실째 뽑았다. 못은 빠져도 매듭은 남게.<br><br>열둘을 다 뽑고 문을 반 뼘 열었다. 안은 작은 방이다. 구석에 누가 등을 돌리고 앉아 있다. 머리부터 발끝까지 실로 감겨 있다.<br>문을 도로 닫았다. 뽑은 못을 다시 박았다. 이번엔 바깥에서. 그리고 다른 길을 찾았다.`,
      ng:`셋째 못을 뽑자 문틈으로 실이 쏟아져 나온다. 감겨 있던 실이 풀린다.<br><br>안에서 무엇이 일어서는 소리. 실이 풀리는 만큼 움직인다.<br>뽑은 못을 도로 박았다. 손바닥으로. 손바닥이 찢어졌다. 피 묻은 못 머리에 실이 다시 감겼다. 이쪽 피가 매듭이 됐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-20 } }
  ] },

{ at:'A', t:'복도 — 주인 찾는 저주',
  x:`복도에 찬 기운이 떠다닌다. 한자리에 있지 않다. 사람에서 사람으로 옮겨 다닌다.<br><br>
    닿은 사람은 갑자기 어깨가 무겁다고 한다. 그러다 기운이 다음 사람에게로 간다. 무언가를 찾는 듯이.<br>
    누가 걸어 놓고 잊어버린 저주다. 걸린 사람이 이미 없는데 저주만 남아 주인을 찾는다.<br><br>
    지금 일행 가운데 제일 어린 사람 어깨에 앉았다. 그 사람 숨이 짧아진다.`,
  o:[
    { l:'① 저주에 적힌 이름을 읽는다.', k:'gaze', dc:22,
      ok:`찬 기운 한가운데를 봤다. 저주에는 늘 이름이 박혀 있다. 누구를 향해 걸었는지.<br><br>오래된 이름이다. 획이 낡았다. 이 일행 누구의 이름도 아니다. 비슷한 사람을 찾는 중이다. 비슷한 나이, 비슷한 키.<br>어린 일행에게 신발을 바꿔 신게 했다. 이쪽 겉옷을 입혔다. 비슷하지 않게. 찬 기운이 그 사람 어깨에서 떨어져 나가 복도 끝으로 흘러갔다.`,
      ng:`이름을 읽으려는데 획이 자꾸 바뀐다. 옮겨 앉을 때마다 그 사람 이름으로.<br><br>읽는 동안 기운이 이쪽으로 왔다. 어깨가 내려앉는다. 숨이 짧아진다.<br>한참 버텼다. 무릎이 꺾일 즈음 기운이 다음 사람에게로 갔다. 이쪽 어깨에는 손바닥 자국 같은 멍이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-20 } },
    { l:'② 어린 일행 대신 이쪽이 그것을 받는다.', k:'steady', dc:23,
      doom:{ title:'주인 없는 저주', what:'저주가 이쪽을 주인으로 삼았습니다', dc:18, sec:45,
        text:`어린 일행 어깨에 손을 얹고 기운을 이쪽으로 당겼다. 받겠다고 속으로 말했다.<br><br>기운이 넘어온다. 생각보다 무겁다. 아주 오래 쌓인 무게다. 무릎이 바닥에 닿는다.<br>저주가 이쪽 이름을 읽는다. 주인과 같지는 않다. 그런데 받겠다고 했다. 받겠다는 사람이 주인이다.<br><br>가슴이 조여 온다. 숨이 반만 들어간다. 그다음엔 반의반만.`,
        dieText:`복도의 찬 기운이 사라졌다. 저주는 주인을 찾았다.<br><br>일행 가운데 제일 어린 사람이 끝까지 그 자리를 떠나지 못했다. 무릎 꿇은 사람의 어깨를 붙들고.<br>그 사람 어깨에는 지금도 손바닥 하나만큼 무게가 있다고 한다. 가볍지 않은 무게다.` },
      ok:`받기 전에 바닥에 이쪽 이름을 적고 그 위에 손바닥을 댔다. 받는 건 이쪽 이름이다. 몸은 그 이름 위에 잠깐 얹혀 있을 뿐이다.<br><br>기운이 넘어왔다. 무겁다. 무릎이 꺾인다. 손바닥 밑 이름이 뜨거워진다. 무게가 이름으로 흘러 들어간다.<br>손을 뗐다. 바닥에 적은 이름이 검게 그을려 있다. 이쪽 이름 하나를 버렸다. 이쪽에는 이름이 하나 더 있다. 아무에게도 말하지 않는 이름이.`,
      win:{ exp:24, dream:4, spirit:6 } },
    { l:'③ 마력을 써서 헝겊 인형을 만들어 저주를 옮겨 돌려보낸다.', k:'gaze', dc:22, cost:{ mana:30 }, wake:1,
      ok:`옷자락을 찢어 인형을 만들었다. 어린 일행 머리카락 한 올을 감고 마력을 불어넣었다. 비슷한 사람을 하나 더 만든 것이다.<br><br>찬 기운이 인형으로 옮겨 앉는다. 인형 등에 처음 걸었던 사람을 향한 매듭을 지었다. 돌아갈 길이다. 인형을 복도 저쪽으로 던졌다.<br>한참 뒤에 아주 먼 데서 무엇이 숨 막히는 소리가 났다. 오래 기다린 소리 같았다.<br><br>저주는 길을 잃으면 아무나 문다. 길을 내주면 제 집으로 간다. 떠도는 것에 돌아갈 매듭을 지어 주는 손이 생겼다.`,
      ng:`인형으로 옮기는데 기운이 망설인다. 인형과 진짜 사람 사이에서.<br><br>마력이 모자랐다. 반만 옮겨 갔다. 나머지 반은 어린 일행 어깨에 남았다. 이제 둘이다. 둘 다 반만 무겁다.<br>인형을 던졌다. 반쪽 기운이 따라갔다. 나머지 반은 그 사람이 그날 내내 지고 다녔다. 대신 짐을 들어 주었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-24, mana:-5 } }
  ] },

{ at:'A1', t:'세트 뒤 — 무대 감독의 카드',
  x:`세트 뒤에서 무대 감독이 등을 돌리고 서 있다. 헤드셋을 쓰고 큰 종이 카드를 한 장씩 넘긴다. 웃어요. 박수. 이동.<br><br>
    카드가 넘어갈 때마다 건물이 그대로 한다. 위층에서 웃음이 나고 박수가 난다. 카드는 명령이다. 이 건물의 주문이다.<br>
    카드 뭉치 옆 소품 상자에 빈 카드와 굵은 펜이 있다.<br><br>
    주문은 쓴 대로 일한다. 누가 썼든.`,
  o:[
    { l:'① 마력을 실은 카드를 한 장 써서 뭉치 사이에 끼운다.', k:'fix', dc:23, cost:{ mana:29 },
      ok:`빈 카드에 굵게 썼다. 「광고」. 글자에 마력을 눌러 담았다. 감독이 다음 장을 넘기기 직전 뭉치 맨 앞에 슬쩍 끼웠다.<br><br>카드가 넘어간다. 광고. 위층이 한꺼번에 조용해진다. 카메라 불이 다 꺼지는 소리가 계단을 타고 내려온다.<br>감독이 카드를 든 채 서 있다. 광고 다음 카드는 아직 없다. 그동안 4층 계단을 다 올라갔다.<br><br>감독은 끝내 돌아보지 않았다. 남의 주문 사이에 제 주문을 끼우는 일. 뭉치 안에서는 누가 쓴 카드인지 모른다.`,
      ng:`쓰고 끼우려는데 카드가 마력에 젖어 축축하다. 감독이 다음 장을 넘기다 손끝이 멈춘다.<br><br>천천히, 그 카드를 뭉치에서 뽑아낸다. 뒤통수가 이쪽을 본 채로. 카드를 구겨 버린다.<br>다음 카드가 넘어간다. 이쪽 이름. 헤드셋에서 작게 소리가 샌다. 대기해 주세요. 세트 뒤 구석에 웅크려 한참 숨을 죽였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26, mana:-5 } },
    { l:'② 카드 옆면에 비친 다음 장을 읽는다.', k:'gaze', dc:22,
      ok:`카드 뭉치 옆면으로 다음 장 글씨가 비쳐 보인다. 거꾸로. 거꾸로 읽는 것에는 익숙하다.<br><br>다음은 「박수」. 그다음은 「이동」. 그다음은 「오늘의 친구」.<br>이동 카드가 넘어갈 때 감독이 옆으로 비켜선다. 그 틈에 계단에 올랐다. 등 뒤에서 오늘의 친구 카드가 넘어가는 소리가 났다. 아무도 안 불렸다.`,
      ng:`거꾸로 읽는데 글씨가 바로 보인다. 감독이 카드 뭉치를 뒤집어 들었다. 이쪽에게 보이게.<br><br>맨 위 카드. 「돌아보세요」. 목이 저절로 돈다. 감독 쪽으로.<br>감독 뒤통수가 이쪽을 본다. 헤드셋 아래 귀가 없다. 눈을 질끈 감고 목을 되돌렸다. 목 근육이 끊어지는 것처럼 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A2', t:'종탑 — 매듭진 종줄',
  x:`종탑 한가운데로 종줄이 내려온다. 굵은 밧줄이다. 물에 젖어 검다.<br><br>
    줄에 매듭이 줄지어 있다. 일정한 간격으로. 손으로 하나씩 맨 매듭이다. 아래로 갈수록 새것이다.<br>
    세는 매듭이다. 사람 하나에 매듭 하나. 맨 아래 매듭은 덜 조여 있다.<br><br>
    줄이 아주 조금 흔들린다. 바람이 없는데. 위에서 누가 당겼다 놓는 것처럼.`,
  o:[
    { l:'① 매듭을 손으로 하나씩 짚어 센다.', k:'gaze', dc:23,
      doom:{ title:'종줄', what:'종줄에 손목이 감겨 끌려 올라갑니다', dc:18, sec:50,
        text:`맨 위에서부터 손으로 짚어 내려왔다. 하나, 둘. 백. 이백. 손바닥이 젖은 밧줄에 쓸린다.<br><br>이백열둘. 덜 조인 맨 아래 매듭. 짚는 순간 매듭이 이쪽 손가락을 물고 조인다. 이백열셋.<br>줄이 위로 당겨진다. 종 쪽으로. 손목에 밧줄이 감긴다. 놓으려는데 매듭이 안 놓는다.<br><br>발이 바닥에서 뜬다. 끌려 올라간다. 위에서 종이 흔들린다. 울리지는 않는다. 아직.`,
        dieText:`종이 울렸다. 한 번. 물 위로 멀리.<br><br>종줄 맨 아래 매듭이 단단히 조였다. 이백열셋.<br>그 아래에 새 매듭이 하나 생겼다. 아직 덜 조여 있다. 다음 손을 기다린다.` },
      ok:`손을 대지 않고 눈으로만 셌다. 등불을 줄 따라 천천히 내리며.<br><br>이백열둘. 맨 아래 매듭은 덜 조였다. 누가 짚어 주기를 기다린다. 짚는 손이 이백열셋이 된다.<br>그 매듭을 건드리지 않았다. 대신 바닥에 떨어진 비둘기 깃털 하나를 매듭 고리에 꽂았다. 매듭이 깃털을 물고 조였다. 줄이 한 번 당겨졌다 멈췄다. 이백열셋째는 깃털이다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 줄 맨 아래에 손님 매듭을 하나 지어 둔다.', k:'fix', dc:22, wake:1,
      ok:`이 학교 매듭은 다 사람을 세는 매듭이다. 그 아래에 다른 매듭을 지었다. 한 번 감고 고리를 밖으로 빼는 매듭. 머무는 사람이 아니라 지나가는 사람을 적는 매듭.<br><br>일행 수만큼 고리를 냈다. 다섯. 줄이 흔들리다 멈췄다. 위에서 당기던 손이 고리를 더듬어 보는 기척이 났다.<br>점호 때 이 층에서 이름이 불리지 않았다. 손님은 출석부에 없다.<br><br>남의 셈 아래에 이쪽 셈을 덧다는 법. 같은 줄에 다른 뜻의 매듭을 얹으면 줄이 둘을 다 읽는다. 매듭 하나로 신분이 바뀐다.`,
      ng:`고리를 밖으로 빼는데 젖은 밧줄이 미끄럽다. 고리가 안으로 말려 들어간다.<br><br>다섯 고리가 다 세는 매듭이 됐다. 이백열셋, 넷, 다섯…….<br>급히 풀었다. 매듭 하나가 안 풀린다. 칼로 잘라 냈다. 잘린 밧줄 끝에서 물이 피처럼 똑똑 떨어졌다. 위에서 종이 낮게 웅웅거렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 손금에 생긴 줄',
  x:`쉬는 틈에 손바닥을 봤다. 손금이 하나 늘었다. 가운데에서 손목 쪽으로 곧게 그어졌다.<br><br>
    손금이 아니다. 너무 곧다. 실 자국이다. 보이지 않는 실이 손바닥을 감고 손목으로 빠져나간다.<br>
    손을 들어 보니 손목 끝에서 무엇이 아주 조금 당긴다. 어둠 쪽으로.<br><br>
    누가 이쪽 손에 실을 매어 두었다. 언제였는지 모른다.`,
  o:[
    { l:'① 줄을 따라 실의 끝을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`손목에서 당기는 쪽을 등불로 따라갔다. 공기 중에 먼지가 한 줄로 걸려 있다. 실이 있는 데만.<br><br>실 끝은 멀지 않았다. 벽 틈에 박힌 못 하나. 못에 이쪽 머리카락 한 올이 감겼다. 아까 계단에서 빠진 것이다.<br>못을 뽑지 않았다. 머리카락을 풀어 그 자리에 어둠 쪽 벽의 거미줄을 대신 감았다. 손바닥의 줄이 옅어졌다. 이제 그 실은 벽과 벽을 잇는다.<br><br>매인 실은 끊는 것보다 바꿔 매는 게 낫다. 끊으면 맨 사람이 안다. 바꿔 매면 모른다. 끝을 갈아 끼우는 손이 생겼다.`,
      ng:`따라가는데 실이 짧아진다. 저쪽에서 감아 들이고 있다. 손이 앞으로 끌린다.<br><br>한 걸음, 두 걸음. 일행이 허리를 붙잡았다. 손목이 빠질 듯 아프다.<br>손바닥을 등불 불꽃에 댔다. 실이 지직 타 끊겼다. 손바닥 가운데 화상이 손금처럼 길게 남았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 손바닥에 소금을 비벼 넣는다.', k:'heal', dc:22,
      ok:`소금 한 줌을 손바닥에 놓고 비볐다. 따갑다. 소금은 매인 것을 삭힌다.<br><br>곧은 줄이 소금 아래에서 흐려진다. 손목 끝의 당김이 약해진다. 한참 비비자 아예 사라졌다.<br>남은 건 진짜 손금이다. 원래 있던 것. 손을 오래 쥐었다 폈다.`,
      ng:`비비는데 줄이 소금을 밀어낸다. 소금이 손바닥에서 굴러떨어진다. 한 알도 안 남는다.<br><br>손목 당김이 세진다. 소금을 싫어한 것이다. 그래서 더 서두른다.<br>밤새 손을 기둥에 묶고 버텼다. 아침에 손목에 실 자국이 붉게 패어 있었다. 줄은 그대로다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A', t:'거울 — 덮개 천의 매듭',
  x:`복도 벽에 큰 거울이 걸렸다. 검은 천으로 덮였다.<br><br>
    천 귀퉁이가 매듭으로 묶였다. 그런데 매듭이 거울 쪽에 있다. 천과 거울 사이에. 안쪽에서 맨 것이다.<br>
    거울 안쪽에서 누가 천을 덮고 묶었다. 이쪽을 안 보려고. 아니면 이쪽에게 안 보이려고.<br><br>
    매듭 하나가 풀려 간다. 천 한 귀퉁이가 들려 있다.`,
  o:[
    { l:'① 안쪽 매듭이 무엇을 위한 것인지 읽는다.', k:'gaze', dc:22,
      ok:`매듭 모양을 봤다. 고리가 거울 쪽으로 났다. 당기는 쪽이 거울 안이다. 안에서 붙들고 있는 매듭이다. 바깥 것을 막는 매듭이 아니다.<br><br>거울 안 누군가가 제 쪽을 가리고 있다. 천이 다 풀리면 그 사람이 이쪽을 보게 된다. 그걸 그 사람이 원하지 않는다.<br>들린 귀퉁이 쪽으로 눈을 돌리지 않고 지났다. 지나고 나서 천 안쪽에서 매듭을 다시 조이는 소리가 났다. 고맙다는 소리처럼 들렸다.`,
      ng:`읽으려 다가가는데 들린 귀퉁이 아래로 거울이 보인다. 이쪽 발이 비친다.<br><br>그 옆에 맨발이 하나 더 비친다. 이쪽 옆에. 돌아보면 아무도 없다.<br>거울 속 맨발이 한 걸음 이쪽으로 왔다. 천 매듭이 하나 더 풀렸다. 그 앞을 뛰어서 지났다. 한동안 발밑을 내려다보지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 마력을 써서 이쪽에서도 매듭을 맞매어 둔다.', k:'fix', dc:22, cost:{ mana:26 },
      ok:`천 바깥 귀퉁이를 잡아 마력을 실어 묶었다. 안쪽 매듭과 반대로. 안에서 당기면 바깥이 조이고 바깥에서 당기면 안이 조이게.<br><br>들려 있던 귀퉁이가 내려앉았다. 이제 천은 거울 안에서도 밖에서도 못 젖힌다.<br>천 너머에서 무엇이 숨을 길게 내쉬었다. 안심한 것인지 실망한 것인지는 모른다.`,
      ng:`묶으려 귀퉁이를 잡는 순간 거울 안쪽에서도 같은 귀퉁이를 잡는다. 천 너머로 손가락이 느껴진다. 이쪽 손가락과 똑같은 자리에.<br><br>마력이 천을 타고 안으로 빨려 간다. 저쪽 손가락이 따뜻해진다. 이쪽 손가락이 차가워진다.<br>손을 뗐다. 손끝 감각이 한참 없었다. 거울 안에서 천을 묶는 소리가 났다. 이쪽 방식대로.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24, mana:-5 } },
    { l:'③ 보지 않고 벽에 붙어 지나간다.', k:'hide', dc:22,
      ok:`거울 반대편 벽에 등을 붙였다. 고개를 숙였다. 일행도 그렇게 했다.<br><br>거울 앞을 지날 때 천이 조금 부풀었다. 안에서 누가 천에 얼굴을 대 본 것처럼. 숨소리는 없었다.<br>다 지나고 나서도 아무도 돌아보지 않았다.`,
      ng:`붙어 가는데 반대편 벽에도 작은 거울이 있다. 덮개가 없다.<br><br>작은 거울에 큰 거울이 비친다. 천 아래 들린 귀퉁이로 안쪽이 비친다. 누가 이쪽을 보고 있다. 두 거울을 사이에 두고.<br>눈을 감고 더듬어 지났다. 눈꺼풀 안쪽에 그 얼굴이 남았다. 잠들 때마다 떠올랐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'인형극 무대 — 천장에서 내려온 실',
  x:`인형극 무대 위 천장에서 실이 내려온다. 줄 인형들이 춤춘다. 손발이 실에 매달려 들린다.<br><br>
    실 가운데 몇 가닥이 무대 밖으로 늘어졌다. 방청석 쪽으로. 그중 하나가 일행 하나의 손목에 걸려 있다. 본인은 모른다.<br>
    인형이 팔을 들면 그 일행도 팔을 조금 든다. 같은 박자로.<br><br>
    천장 어둠 속에서 누가 실을 쥐고 있다. 손가락 끝만 보인다.`,
  o:[
    { l:'① 실이 손목 어디에 어떻게 걸렸는지 읽는다.', k:'gaze', dc:22,
      ok:`실은 손목에 매듭으로 매이지 않았다. 고리로 걸렸다. 걸린 고리는 같은 쪽으로 돌려 빼면 빠진다.<br><br>인형이 팔을 내릴 때를 기다렸다. 실이 느슨해진다. 그 순간 고리를 손목 바깥쪽으로 돌려 뺐다. 일행은 아무것도 몰랐다.<br>빠진 고리를 무대 기둥 못에 걸었다. 인형이 팔을 들자 기둥이 삐걱 울었다. 천장 위 손가락이 멈칫했다.`,
      ng:`고리를 보려고 손목을 잡는데 인형이 팔을 든다. 일행 팔이 이쪽 손을 뿌리치며 올라간다.<br><br>세게. 사람 힘이 아니다. 이쪽 얼굴을 쳤다. 코에서 피가 났다.<br>일행이 놀라 사과했다. 본인은 팔을 든 기억이 없다. 실은 그대로 걸려 있었다. 무대를 지나는 내내 그 팔을 붙들고 걸었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 칼로 실을 끊는다.', k:'break', dc:23,
      doom:{ title:'줄 인형', what:'실에 매달려 천장 위로 끌려 올라갑니다', dc:18, sec:50,
        text:`칼로 실을 끊었다. 일행 손목이 툭 떨어졌다.<br><br>끊긴 실 끝이 허공에서 이쪽으로 휜다. 뱀처럼. 이쪽 손목을 감는다. 다른 실들도 내려온다. 팔꿈치, 무릎, 목.<br>천장 위 손가락이 실을 감아올린다. 이쪽 팔이 들린다. 다리가 들린다. 발끝이 무대 바닥에서 떨어진다.<br><br>끌려 올라간다. 줄 인형들 사이로. 인형들이 이쪽을 보며 같은 박자로 고개를 끄덕인다.`,
        dieText:`무대 위 줄 인형이 하나 늘었다. 크다. 사람만 하다.<br><br>그 인형은 춤을 잘 춘다. 박자를 하나도 안 놓친다. 얼굴이 익숙하다.<br>방청석에 앉은 일행 손목에서 실이 저절로 풀렸다. 하나면 됐다는 듯이.` },
      ok:`끊기 전에 실을 쥐고 무대 기둥에 한 바퀴 감았다. 그리고 기둥 쪽에서 끊었다.<br><br>끊긴 실 끝이 허공에서 휜다. 감을 것을 찾는다. 기둥이 먼저 있다. 실이 기둥을 감아 조인다.<br>천장 위 손가락이 실을 감아올린다. 기둥이 삐걱거릴 뿐 안 올라간다. 일행 손목은 자유다. 무대를 서둘러 지났다. 뒤에서 기둥이 빠지는 소리가 났다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'교실동 — 반장 자리의 짚 인형',
  x:`교실에 물이 허리까지 찼다. 맨 앞줄 가운데 자리에 짚 인형이 앉아 있다. 가슴에 명찰. 「반장」.<br><br>
    인형 등에 붉은 실로 반 아이들 이름이 감겨 있다. 서른 개. 매듭 하나에 이름 하나.<br>
    교실 문이 열리자 인형 머리가 들린다. 물속 의자들이 일제히 소리를 낸다. 차렷.<br><br>
    대신 인형이다. 아이들 대신 무엇을 받으라고 누가 만들어 앉혔다.`,
  o:[
    { l:'① 누가 무엇을 대신 받게 했는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`매듭을 하나씩 봤다. 맨 처음 매듭은 단단하고 반듯하다. 어른 손이다. 담임이다. 나머지는 서툴다. 아이들 손이다. 저마다 제 이름을 맸다.<br><br>담임이 아이들 대신 물을 받으라고 만든 인형이다. 아이들은 인형에 기댔다. 인형은 지금도 반을 지킨다. 반장이니까.<br>인형을 부수지 않았다. 풀려 가던 매듭 셋을 고쳐 조였다. 인형 머리가 끄덕였다. 물속 의자들이 조용해졌다. 경례 소리 없이 교실을 지났다.<br><br>매듭에는 맨 손이 남는다. 어른 손과 아이 손, 서두른 손과 오래 공들인 손. 매듭 하나로 맨 사람을 가려내는 눈이 생겼다.`,
      ng:`매듭을 읽는데 인형 머리가 이쪽으로 돈다. 짚 사이로 눈 같은 구멍 둘.<br><br>「전학생.」 물속에서 의자들이 일제히 끌린다. 이쪽 쪽으로. 빈 의자 하나가 등 뒤에 와 닿는다.<br>앉으라는 것이다. 버텼다. 의자가 오금을 친다. 무릎이 꺾였다. 물에 빠지듯 주저앉았다가 겨우 일어섰다. 무릎이 한참 떨렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 인형 눈에 띄지 않게 맨 뒷줄로 돌아간다.', k:'hide', dc:22,
      ok:`벽에 붙어 맨 뒷줄로 돌았다. 물을 젓지 않게 발을 끌며.<br><br>반장은 앞을 본다. 반장은 뒤를 안 본다. 뒤에서 떠드는 아이를 잡는 건 담임 몫이다.<br>교단 위 담임 자리는 비었다. 뒷문으로 빠져나왔다. 등 뒤에서 차렷, 경례 소리가 물속으로 울렸다. 이쪽이 아닌 칠판을 향해.`,
      ng:`맨 뒷줄로 도는데 뒷자리 의자 하나에 발이 걸렸다. 첨벙.<br><br>반장 인형이 고개를 돌린다. 목이 끝까지 돈다. 짚이 비틀리는 소리.<br>「떠든 사람.」 물속에서 손들이 일제히 이쪽을 가리킨다. 손가락이 바지를 꽉 붙든다. 뿌리치느라 정강이를 의자 모서리에 몇 번이고 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 인형 등의 실을 끊어 이름들을 풀어 준다.', k:'break', dc:23,
      ok:`매듭을 끊지 않고 하나씩 풀었다. 이름을 하나씩 읽어 주면서. 대답 대신 물 위에 작은 거품이 하나씩 올라온다.<br><br>서른을 다 풀자 인형이 조금 기운다. 지킬 이름이 없다. 짚이 물을 먹고 천천히 가라앉는다.<br>교실 의자들이 하나씩 떠올랐다. 빈 의자다. 아무도 차렷 하지 않았다. 교실을 나서는데 뒤에서 아이들 웃음소리가 아주 작게 났다. 하교하는 소리처럼.`,
      ng:`끊는 순간 의자들이 일제히 비명을 지른다. 물속에서.<br><br>반장 없는 반은 반이 아니다. 담임도 반장도 없는 교실에서 서른 개의 손이 물 위로 올라온다. 이쪽 쪽으로. 잡을 것을 찾는다.<br>끊은 실을 다시 이었다. 손이 떨려 매듭이 엉성하다. 인형이 다시 머리를 들 때까지 손이 이쪽 옷을 잡아당겼다. 옷이 찢어졌다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A', t:'복도 — 소금 선의 끊긴 데',
  x:`바닥을 가로질러 소금 선이 그어져 있다. 앞서 온 사람이 그었다. 굵고 고르다. 잘 그은 선이다.<br><br>
    한 군데가 끊겼다. 손바닥 하나만큼. 그 틈으로 젖은 발자국이 넘어와 있다. 이쪽 방향으로.<br>
    선 너머 어둠에서 무엇이 기다린다. 숨을 고르는 소리가 난다.<br><br>
    끊긴 자리 소금이 이상하다. 쓸려 나간 쪽이 이쪽이다.`,
  o:[
    { l:'① 소금 선을 이쪽 소금으로 이어 메운다.', k:'fix', dc:22,
      ok:`품의 소금을 털어 틈을 메웠다. 굵게. 다른 데보다 더 굵게.<br><br>넘어와 있던 젖은 발자국이 선 안쪽에 갇혔다. 마지막 발자국 끝에서 물이 끓듯이 거품을 내다 말랐다.<br>선 너머 숨소리가 가까이 왔다가 선 앞에서 멈췄다. 한참 서성였다. 소금 선을 등지고 쉬었다. 아무도 선 쪽으로 다리를 뻗지 않았다.`,
      ng:`메우는데 소금이 모자란다. 틈을 반만 메웠다.<br><br>반만 메운 틈으로 무엇이 몸을 옆으로 해서 비집고 들어온다. 얇게. 종이처럼.<br>소금 주머니째 그쪽에 던졌다. 비명 같은 소리가 났다. 그 소리에 다들 귀를 막고 주저앉았다. 귀가 한동안 웅웅거렸다.`,
      win:{ exp:18, dream:2, spirit:7 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 소금이 어느 쪽에서 쓸렸는지 읽는다.', k:'gaze', dc:22,
      ok:`쓸린 결을 봤다. 소금 알갱이가 선 너머로 흩어졌다. 이쪽에서 밀어서 끊은 것이다. 선 안쪽에 있던 누가.<br><br>앞서 온 사람들 가운데 하나가 선을 끊고 나갔다. 부르는 소리를 따라. 젖은 발자국은 그 사람이 돌아온 발자국이다. 돌아왔는데 사람이 아니다.<br>발자국 끝을 따라갔다. 벽 구석에서 멎었다. 거기 소금을 동그랗게 둘렀다. 원 안에서 무엇이 웅크리는 소리가 났다. 동그란 원 위에 소금을 한 줌 더 얹었다.`,
      ng:`결을 읽는 사이 어둠 저쪽에서 이쪽 이름을 부른다. 앞서 온 사람 목소리다. 모르는 사람인데 이쪽 이름을 안다.<br><br>발이 선 쪽으로 한 걸음 간다. 선 끊긴 틈 쪽으로. 똑같이.<br>일행이 등덜미를 잡아챘다. 넘어지며 소금 선에 손을 짚었다. 손바닥이 쓰라리다. 소금이 상처를 찾아 들어갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'어둠 — 부르면 오는 것',
  x:`복도 저편 어둠에 무엇이 있다. 움직이지 않는다. 기다린다.<br><br>
    벽에 앞서 온 사람이 적어 둔 글이 있다. 「부르면 온다. 이름을 부르면 온다.」<br>
    그런데 그것의 이름은 아무도 모른다. 모르는 이름은 부를 수 없다. 부를 수 없으면 오지 않는다. 그렇게 믿고 싶다.<br><br>
    일행 하나가 무심코 「저게 뭐지」 하고 말했다. 어둠이 한 걸음 다가왔다.`,
  o:[
    { l:'① 아무도 그것을 가리키는 말을 하지 않게 한다.', k:'steady', dc:22,
      ok:`손가락을 입에 댔다. 그것, 저것, 뭐, 아무것도 말하지 말라고. 가리키는 말이 다 이름이 된다.<br><br>다들 입을 다물었다. 손짓으로만 걸었다. 어둠이 다가오지 않는다. 불러 주기를 기다린다.<br>복도를 다 지날 때까지 아무도 말하지 않았다. 지나고 나서도 한동안 다들 말을 잃은 사람 같았다.`,
      ng:`입을 다물게 했는데 누가 숨을 들이켜는 소리를 냈다. 「어」.<br><br>그것도 부르는 말이었다. 어둠이 성큼 다가왔다. 차가운 바람이 얼굴을 쓸었다.<br>다 같이 뛰었다. 누가 넘어졌다. 일으키며 뛰었다. 뛰면서 아무도 아무 말도 못 했다. 숨이 넘어갈 것 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-22 } },
    { l:'② 그것에게 이쪽이 지은 이름을 붙여 부른다.', k:'gaze', dc:23, wake:1,
      ok:`이름을 모르면 지어 주면 된다. 지어 준 이름은 지은 사람 것이다. 이름 붙인 것은 이름 붙인 사람의 말을 듣는다.<br><br>어둠을 똑바로 보고 지은 이름을 한 번 불렀다. 「멈춰라, 이끼.」 어둠이 다가오다 멈췄다. 이끼라는 이름에 묶였다.<br>「이끼, 거기 있어라.」 그것이 거기 있었다. 복도를 다 지나는 동안.<br><br>이름은 붙들어 두는 매듭이다. 이름 없는 것에게 이름을 지어 매는 일. 혀끝에 매듭 하나가 생겼다. 함부로 이름 짓지 말아야 할 혀다.`,
      ng:`이름을 지어 불렀다. 「멈춰라.」 그것이 멈추지 않는다. 그것에게는 이미 이름이 있었다.<br><br>남의 이름 위에 이름을 얹으면 그것은 두 이름을 다 듣는다. 하나는 오라는 이름이다.<br>어둠이 덮쳐 왔다. 등불이 꺼졌다. 손을 휘저으며 뒷걸음질 쳤다. 다시 불을 켰을 때 팔에 긁힌 자국이 셋 나 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } }
  ] },

{ at:'A1', t:'탕비실 — 이름표 붙은 컵',
  x:`탕비실 선반에 컵이 줄지어 있다. 컵마다 이름표 테이프. 직원들 컵이다. 연출, 조명, 음향, 노래 언니.<br><br>
    맨 끝 컵에 이쪽 이름이 붙어 있다. 테이프가 새것이다. 컵에 차가 담겨 있다. 김이 오른다.<br>
    직원 컵에 차를 따라 주는 건 같이 일하자는 뜻이다. 마시면 이 건물 사람이 된다.<br><br>
    다른 컵들은 다 비었다. 바닥에 차 자국이 말라붙었다. 오래전에 다 마셨다.`,
  o:[
    { l:'① 이쪽 이름 컵의 차를 바닥에 쏟아 버린다.', k:'break', dc:23,
      doom:{ title:'직원 컵', what:'쏟은 찻물에 발목이 감겨 끌려갑니다', dc:18, sec:50,
        text:`컵을 들어 바닥에 쏟았다. 김 오르는 차가 타일에 퍼진다.<br><br>퍼지던 찻물이 멈춘다. 그리고 거꾸로 모인다. 이쪽 발쪽으로. 신발 위로 올라온다. 따뜻하다. 발목을 감는다.<br>찻물이 끈이 된다. 끈이 문 쪽으로 당긴다. 복도로. 위층 스튜디오 쪽으로. 출근 시간에 늦은 직원을 끄는 손처럼.<br><br>끌려간다. 바닥에 젖은 줄이 길게 남는다. 위층에서 무대 감독이 카드를 넘기는 소리가 들린다.`,
        dieText:`탕비실 맨 끝 컵에 차가 다시 담겼다. 김이 오른다.<br><br>스튜디오 출연진 명단 맨 아래에 줄이 하나 늘었다. 이쪽 이름. 담당 칸은 「친구」.<br>다른 컵들처럼 그 컵도 언젠가 바닥에 차 자국만 남을 것이다.` },
      ok:`쏟기 전에 컵을 거꾸로 엎어 개수대 배수구에 대고 쏟았다. 바닥에 한 방울도 안 닿게.<br><br>배수구가 꾸르륵 차를 삼킨다. 마시지 않은 차는 갈 데가 없다. 엎어 둔 컵은 다시 안 채워진다.<br>컵을 엎은 채 선반에 두었다. 이름표 테이프를 손톱으로 뜯어 구겨 주머니에 넣었다. 선반의 다른 컵들이 아주 조금 쨍 울었다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 이름표 테이프의 글씨를 읽는다.', k:'gaze', dc:22,
      ok:`테이프 글씨가 다른 컵들과 같은 손이다. 획을 크게 꺾는 손. 무대 감독 카드 글씨다.<br><br>무대 감독이 직원을 들인다. 이름표를 붙이는 사람이 고용하는 사람이다. 그 사람이 아니면 붙인 이름표를 못 뗀다는 뜻이기도 하다.<br>그래서 테이프 위에 한 줄을 더 붙였다. 「퇴사」. 감독 글씨를 흉내 내 꺾어서. 컵 속 김이 멈췄다. 차가 금세 식었다.`,
      ng:`읽는 사이 컵이 손에 들려 있다. 언제 들었는지 모른다. 김이 코끝에 닿는다. 좋은 냄새다.<br><br>입술이 컵에 닿기 직전 일행이 손목을 쳤다. 컵이 떨어져 깨졌다. 찻물이 발등을 데웠다.<br>화상이 생겼다. 발등에 컵 바닥 모양으로 둥글게. 테이프가 붙어 있던 자리만큼 하얗게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'③ 다른 직원 컵 하나를 골라 이쪽 이름표를 옮겨 붙인다.', k:'fix', dc:22,
      ok:`이쪽 이름표를 떼어 빈 컵 하나에 옮겨 붙였다. 「조명」 컵이다. 그 위에.<br><br>이제 차가 담긴 컵에는 이름이 없다. 이름 없는 컵은 아무 직원의 것도 아니다. 차가 김을 내다 식는다.<br>이쪽 이름은 빈 컵에 붙어 있다. 빈 컵은 이미 다 마신 사람의 것이다. 이미 다 마신 사람은 다시 들일 수 없다. 탕비실을 나왔다.`,
      ng:`옮겨 붙이는데 테이프가 손가락에 감긴다. 끈적하게. 떼어 내면 다시 붙는다.<br><br>테이프가 이쪽 손가락에 붙어 버렸다. 손가락에 이쪽 이름이 붙었다. 이름표 붙은 것은 이 건물 것이다.<br>손가락 살갗째 뜯어냈다. 피가 맺혔다. 그 손가락으로 아무것도 쥘 수 없었다. 한참 동안.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A2', t:'수영장 — 레인 줄',
  x:`물 밑 수영장이다. 천장 쪽에 공기가 한 뼘 남았다. 거기 고개만 내밀고 있다.<br><br>
    레인 줄이 물 위에 떠 있다. 줄마다 부표가 꿰어졌다. 색이 반마다 다르다. 1반 빨강, 2반 파랑.<br>
    레인마다 물속에 무엇이 줄지어 서 있다. 차례를 기다리는 아이들 키다.<br><br>
    레인 하나만 비었다. 부표가 하얗다. 어느 반도 아니다. 반대편 출구 사다리가 그 끝에 있다.`,
  o:[
    { l:'① 레인 줄이 무엇을 가르는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`레인 줄은 물을 나누는 줄이다. 수영장에서는 사람을 나누는 줄이다. 이 줄은 반을 나눈다. 반에 든 사람은 제 레인 밖으로 못 나간다.<br><br>하얀 레인은 반이 없는 사람 레인이다. 그런데 비어 있는 까닭이 있다. 부표 하나가 검다. 아주 작게.<br>검은 부표 앞까지만 하얀 레인을 탔다. 거기서 줄 아래로 잠수해 옆 레인으로 넘어갔다가 다시 돌아왔다. 검은 부표 아래 물이 소용돌이쳤다. 지나고 보니 그 아래가 배수구였다.<br><br>줄은 모두 매듭이다. 사람을 가르는 줄도. 어느 줄이 무엇을 가르는지 먼저 읽는 버릇이 붙었다. 경계선을 보는 눈이다.`,
      ng:`읽는 사이 숨이 모자랐다. 공기 한 뼘에 일행 다섯이 고개를 들이민다.<br><br>하얀 레인에 몸을 맡겼다. 검은 부표를 못 봤다. 발밑에서 물이 당긴다. 배수구다.<br>레인 줄을 붙들고 버텼다. 부표들이 손바닥을 짓이겼다. 일행이 뒷덜미를 끌어올렸다. 물을 많이 먹었다. 숨을 쉴 때마다 가슴에서 물소리가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 마력을 써서 레인 줄 하나를 끊고 빈 물길을 낸다.', k:'break', dc:23, cost:{ mana:31 },
      ok:`손을 레인 줄에 대고 마력을 흘렸다. 부표를 꿴 줄이 마력에 삭아 끊어진다.<br><br>1반과 2반 사이 줄이 풀려 가라앉는다. 두 반이 섞인다. 섞인 반은 반이 아니다. 줄지어 있던 것들이 서로를 보며 흐트러진다.<br>흐트러진 틈을 헤엄쳐 건넜다. 사다리를 잡고 올라섰다. 물속에서 아이들이 서로 이름을 묻는 소리가 들렸다.`,
      ng:`줄이 삭다 말았다. 반쯤 끊긴 줄이 꿈틀한다. 마력이 그대로 물에 풀려 나간다.<br><br>두 반이 한꺼번에 이쪽을 본다. 줄을 건드린 사람을. 물속 손들이 몰려온다.<br>사다리까지 헤엄쳤다. 발목을 몇 번이나 잡혔다. 뿌리치느라 발가락이 꺾였다. 겨우 올라섰을 때 다리가 제대로 서지 않았다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-28, spirit:-22, mana:-5 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잠든 일행의 손',
  x:`밤에 눈을 떴다. 일행 하나가 자면서 손을 움직인다. 신발 끈을 매고 있다.<br><br>
    매듭 모양이 낯익다. 이쪽 매듭이다. 이쪽이 매는 방식 그대로. 이쪽에게서 배운 적이 없는 사람이다.<br>
    끈을 감는 손가락 끝이 차다. 그런데 눈은 감고 있다.<br><br>
    매듭이 다 되어 간다. 마지막 고리만 남았다.`,
  o:[
    { l:'① 매듭의 감긴 방향을 읽는다.', k:'gaze', dc:22,
      ok:`이쪽 매듭과 똑같다. 단 하나, 감는 방향이 반대다. 조이는 매듭이 아니라 풀리는 매듭이다.<br><br>누가 이쪽 매듭을 거울에 비춰 배웠다. 그리고 이 사람 몸을 빌려 연습한다. 풀리는 매듭을 묶으면 묶인 것이 풀린다. 이 사람과 몸 사이의 매듭이.<br>마지막 고리를 맺기 전에 손을 덮어 잡았다. 이쪽 방향으로 고쳐 맺었다. 손가락이 따뜻해졌다. 일행이 깨지 않고 돌아누웠다.`,
      ng:`방향을 보려고 몸을 숙이는데 일행 눈이 떠진다. 눈동자가 없다. 흰자만.<br><br>입이 이쪽 목소리로 말한다. 「이렇게 하는 거 맞지?」 마지막 고리가 맺어진다.<br>일행 몸이 한 번 크게 떨렸다. 깨어나서는 아무것도 기억하지 못했다. 신발 끈은 칼로 잘라 버렸다. 이쪽 손이 밤새 떨렸다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 어깨를 흔들어 깨운다.', k:'bond', dc:22,
      ok:`어깨를 잡아 흔들었다. 이름을 불렀다. 진짜 이름을. 세 번.<br><br>일행이 눈을 떴다. 눈동자가 있다. 손에 쥔 신발 끈을 보고 놀란다. 매다 만 끈이 손가락 사이에서 풀려 떨어진다.<br>둘이서 끈을 불에 넣었다. 남은 밤은 서로 등을 대고 앉아 지샜다.`,
      ng:`흔들었다. 안 깬다. 손은 계속 움직인다. 더 빨라진다.<br><br>세게 흔들자 일행 손이 이쪽 손목을 잡는다. 끈째. 끈이 이쪽 손목에도 감긴다. 둘이 한 매듭에 묶인다.<br>한참 뒤에 일행이 깨어났다. 둘 다 손목에 끈 자국이 깊게 패어 있었다. 자국은 한 매듭 모양이었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] }

]);

// ------------------------------------------
// 퇴마사 · 마력
// ------------------------------------------
kJob('exorcist', 'A', [

{ at:'A', t:'쉬는 자리 — 남의 목소리로 하는 잠꼬대',
  x:`쉬는 틈에 일행 하나가 잠들었다. 잠꼬대를 한다. 아이 목소리다. 그 사람 목소리가 아니다.<br><br>
    「여기 추워. 문 어디 있어.」 같은 말을 되풀이한다. 손가락이 허공을 더듬는다. 문고리를 찾는 손이다.<br>
    잠든 몸에 무엇이 다녀가는 중이다. 들어와 앉은 건 아니다. 잠깐 빌려 입었다.<br><br>
    잠든 사람 얼굴이 점점 하얘진다. 빌려 입은 것이 오래 머물면 옷이 늘어난다.`,
  o:[
    { l:'① 잠꼬대를 끝까지 듣고 무엇인지 본다.', k:'gaze', dc:22, wake:1,
      ok:`귀를 대고 들었다. 말끝마다 숨이 짧다. 물에 잠긴 사람 숨이다. 손가락이 찾는 문고리는 낮다. 아이 키다.<br><br>해치러 온 게 아니다. 길을 잃어 아무 몸에나 들어와 문을 찾는 아이다. 귀에 대고 낮게 말해 주었다. 「문은 네 등 뒤에 있다. 돌아서 나가라.」<br>잠든 몸이 한 번 돌아누웠다. 아이 목소리가 「아」 하고 그쳤다. 얼굴에 핏기가 돌았다.<br><br>무엇이 들어와 있는지 먼저 알면 꺼낼 필요가 없을 때도 있다. 붙은 것의 말투에서 그것의 나이와 사정을 읽는 귀가 생겼다. 쫓기 전에 묻는 버릇이다.`,
      ng:`듣는데 잠꼬대가 바뀐다. 「찾았다.」 아이 목소리가 웃는다.<br><br>잠든 일행의 손이 이쪽 손목을 잡는다. 문고리를 잡듯이. 차다. 돌린다.<br>손목이 꺾이기 직전에 소금을 그 손등에 뿌렸다. 손이 풀렸다. 일행은 끝내 깨지 않았다. 손목에 작은 손가락 자국이 다섯 남았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-20 } },
    { l:'② 마력을 써서 잠든 몸에서 끌어낸다.', k:'gaze', dc:23, cost:{ mana:28 },
      ok:`잠든 이마에 손바닥을 얹었다. 마력을 밀어 넣어 안에 든 것을 감쌌다. 작다. 가볍다. 떨고 있다.<br><br>끌어냈다. 천천히. 입김처럼 하얀 것이 입에서 빠져나와 등불 둘레를 한 바퀴 돌았다. 그러고는 어둠으로 흘러갔다.<br>일행이 눈을 떴다. 추운 꿈을 꿨다고 한다. 물속에서 문을 찾는 꿈.`,
      ng:`감싸는 순간 안에 든 것이 놀라 몸 깊이 숨는다. 마력이 그것을 쫓아 들어간다.<br><br>잠든 일행이 비명을 지른다. 두 목소리로. 몸이 활처럼 휜다. 손을 뗐다.<br>한참 뒤에 아이 목소리가 저 혼자 빠져나갔다. 일행은 깨어나서 온몸이 쑤신다고 했다. 이쪽 손바닥에도 얼음 자국이 남았다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-24, spirit:-22, mana:-5 } },
    { l:'③ 흔들어 깨운다.', k:'bond', dc:23,
      doom:{ title:'빌려 입은 몸', what:'건너온 것에게 꿈속으로 끌려갑니다', dc:18, sec:50,
        text:`어깨를 잡고 세게 흔들었다. 일행이 번쩍 눈을 떴다. 제 목소리로 숨을 몰아쉰다.<br><br>안에 있던 것이 나왔다. 그리고 갈 데를 찾는다. 가장 가까운 몸. 흔드는 손을 타고 이쪽 팔로 올라온다. 차갑다.<br>눈꺼풀이 무겁다. 갑자기. 잠이 머리를 누른다. 꿈속 복도가 열린다. 물이 차 있다. 작은 손이 이쪽 손을 쥐고 당긴다.<br><br>끌려간다. 꿈 안쪽으로. 문을 찾으러. 몸은 쉬는 자리에 앉은 채로.`,
        dieText:`일행들이 아무리 흔들어도 깨지 않았다.<br><br>입술이 계속 움직였다. 아이 목소리로. 「여기 추워. 문 어디 있어.」 그러다 목소리가 하나 더 섞였다. 이쪽 목소리로.<br>숨이 천천히 잦아들었다. 손가락은 끝까지 허공을 더듬었다. 낮은 데를.` },
      ok:`흔들기 전에 이쪽 손에 소금을 쥐었다. 그리고 소금 쥔 손으로 어깨를 흔들었다.<br><br>일행이 번쩍 깼다. 안에 있던 것이 튀어나와 가까운 몸을 찾는다. 흔드는 손에 소금이 있다. 피한다. 그 옆으로, 바닥으로, 어둠으로.<br>일행이 숨을 몰아쉬며 이쪽 소매를 붙들었다. 꿈속에서 누가 계속 따라왔다고 했다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A1', t:'의상실 — 안이 따뜻한 인형탈',
  x:`의상실 걸이에 삐뚤이 탈이 걸려 있다. 목이 긴 파란 새. 다른 탈들은 다 차다. 이것만 따뜻하다.<br><br>
    손을 대 보니 천 너머로 체온이 있다. 아이만 하다. 숨을 쉬지는 않는다.<br>
    탈 안에 무엇이 들어 있다. 탈이 아이를 입었는지 아이가 탈을 입었는지는 아직 모른다.<br><br>
    긴 목이 조금 기운다. 이쪽 쪽으로.`,
  o:[
    { l:'① 마력을 써서 탈과 안에 든 것을 떼어 낸다.', k:'gaze', dc:23, cost:{ mana:30 }, wake:1,
      ok:`탈 등에 손바닥을 대고 마력을 흘렸다. 천과 안쪽 사이 틈을 찾았다. 천은 차고 안쪽은 따뜻하다. 그 경계를 손으로 더듬어 갈랐다.<br><br>둘은 달랐다. 탈이 아이를 입고 있었다. 아이는 안에서 웅크렸다. 아주 오래. 경계를 갈라 아이 쪽만 끌어냈다. 가볍다. 등불 아래서 금방 흐려졌다.<br>탈은 걸이에서 빈 천으로 축 늘어졌다. 긴 목이 꺾여 내려왔다.<br><br>씐 것과 씌인 것 사이에는 늘 결이 있다. 차고 따뜻한 경계. 그 결을 손으로 갈라 둘을 떼는 법을 알았다. 붙은 것을 한 덩이로 쫓지 않는다.`,
      ng:`경계를 찾는데 경계가 없다. 탈과 안쪽이 한데 붙었다. 오래 입어서.<br><br>마력이 탈 천에 먹힌다. 탈이 따뜻해진다. 더. 긴 목이 이쪽 어깨에 얹힌다.<br>뿌리치고 물러섰다. 어깨에 깃털 같은 감촉이 오래 남았다. 걸이에 걸린 탈이 이쪽을 향해 천천히 고개를 돌렸다.`,
      win:{ exp:24, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-26, mana:-5 } },
    { l:'② 탈 앞에 쪼그려 앉아 이름을 묻는다.', k:'steady', dc:22,
      ok:`쪼그려 앉아 아이 눈높이에 맞췄다. 탈 부리 아래 그늘에 대고 물었다. 이름이 뭐니.<br><br>대답이 없다. 한참 뒤 탈 안에서 아주 작게 소리가 났다. 이름이 아니라 번호다. 방청객 번호. 접수처에서 받은 번호다.<br>번호 말고 이름을 말해도 된다고 했다. 탈이 조금 더 따뜻해졌다가 식었다. 안에 든 것이 이름을 떠올리고 나간 것이다.`,
      ng:`물었다. 탈 안에서 대답이 왔다. 이쪽 이름이다.<br><br>탈이 이쪽 이름을 제 이름이라고 한다. 긴 목이 내려와 이쪽 얼굴 앞에 멈춘다. 부리 안쪽이 깜깜하다. 들어오라는 듯이.<br>뒤로 넘어지며 물러났다. 일어서는데 다리가 떨렸다. 의상실을 나서는 내내 등 뒤에서 이쪽 이름이 작게 불렸다.`,
      win:{ exp:18, dream:2, spirit:7 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'기숙사 — 이불 속의 대답',
  x:`밤 아홉 시 종이 물 밑에서 울렸다. 복도로 열쇠 소리가 지나간다. 호실마다 문을 열고 이름을 부른다.<br><br>
    이 호실 침대는 여섯. 이불이 다 사람 모양으로 부풀었다. 이름이 불릴 때마다 이불 속에서 대답한다. 「네.」 젖은 목소리.<br>
    다섯째 침대가 두 번 대답했다. 한 번은 제 이름에, 한 번은 남의 이름에.<br><br>
    일행은 벽장 안에 숨어 있다. 다음 호실 차례가 오기 전에 정해야 한다.`,
  o:[
    { l:'① 대답 소리로 이불 속의 것들을 가린다.', k:'gaze', dc:22, wake:1,
      ok:`네 침대의 대답은 똑같이 젖었다. 물에 잠긴 지 오래된 목소리다. 늦지도 빠르지도 않다. 매일 해 온 대답이다.<br><br>다섯째는 다르다. 젖은 척하는 목소리다. 남의 이름에 한 박자 먼저 대답했다. 대답을 가로채는 것이다. 이름을 모으는 것이다.<br>다섯째 이불 둘레에만 소금을 뿌렸다. 다음 날 아침 점호 때 그 침대는 대답을 못 했다. 나머지 넷은 여전히 대답했다. 그 아이들은 쫓을 까닭이 없다.<br><br>씐 것들 사이에도 결이 다르다. 머무는 넋과 사냥하는 것. 목소리 끝의 물기로 그 둘을 가르는 귀가 생겼다.`,
      ng:`듣다가 열쇠 소리가 문 앞에서 멈췄다. 벽장 쪽으로 이름이 불린다. 이쪽 이름이다.<br><br>다섯째 침대가 대신 대답했다. 「네.」 이쪽 목소리로.<br>이불 속 것이 이쪽 대답을 가져갔다. 목소리가 쉬었다. 그날 내내 소리가 잘 안 나왔다. 가끔 이쪽 목에서 젖은 소리가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 다섯째 침대 이불을 걷는다.', k:'bond', dc:23,
      doom:{ title:'다섯째 침대', what:'침대 밑 물속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`벽장에서 나가 다섯째 침대 이불을 확 걷었다.<br><br>안에 아무도 없다. 젖은 시트에 사람 모양 자국만 있다. 그 자국이 이쪽 몸 크기다.<br>침대 밑 물에서 손이 올라온다. 이쪽 발목을 잡는다. 다른 손이 무릎을, 허리띠를. 취침 시간에 침대 밖에 선 학생을 눕히는 손이다.<br><br>침대 밑으로 끌려 들어간다. 침대 밑은 좁은데 깊다. 위에서 열쇠 소리가 다시 다가온다.`,
        dieText:`열쇠 소리가 문을 열었다. 이름을 불렀다. 여섯 침대가 다 대답했다.<br><br>「이상 없음.」 열쇠 소리가 다음 호실로 갔다.<br>다섯째 침대 이불이 사람 모양으로 부풀어 있다. 다음 점호 때 그 침대는 대답을 한 번만 했다. 이쪽 이름에.` },
      ok:`걷기 전에 침대 다리 넷에 소금을 둘렀다. 그리고 이불 귀퉁이를 막대로 들어 걷었다. 손을 안 대고.<br><br>빈 시트에 사람 모양 자국. 침대 밑에서 손이 올라오다 소금 둘레에서 움찔 물러난다.<br>자국이 서서히 말랐다. 이불 속 것이 숨을 데를 잃었다. 벽장으로 돌아왔다. 다음 점호 때 그 침대는 아무 대답도 하지 않았다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 마력으로 일행이 숨은 벽장에 소리 막을 친다.', k:'fix', dc:22, cost:{ mana:27 },
      ok:`벽장 안쪽 네 귀퉁이에 손을 대고 마력을 둘렀다. 안의 소리가 밖으로 안 나가게. 이름이 불려도 대답이 안 새게.<br><br>열쇠 소리가 들어왔다. 이름을 불렀다. 벽장 쪽으로도 불렀다. 벽장 안에서 일행 하나가 저도 모르게 「네」 했다. 소리가 막에 부딪혀 흩어졌다.<br>열쇠 소리가 한참 기다리다 나갔다. 벽장 안에서 다들 손으로 입을 막고 아침을 기다렸다.`,
      ng:`막을 두르는데 벽장 문 틈 하나를 못 막았다. 거기로 소리가 샌다.<br><br>일행 하나의 숨소리가 틈으로 새 나갔다. 열쇠 소리가 그 틈 앞에 섰다. 틈에 열쇠 구멍처럼 눈 하나가 댔다.<br>한참을 마주 봤다. 눈이 떨어졌을 때 다리에 쥐가 났다. 마력이 다 빠져 손이 저렸다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24, mana:-5 } }
  ] },

{ at:'A', t:'복도 — 업힌 것',
  x:`앞서 걷는 일행 하나가 자꾸 허리를 숙인다. 무거운 짐을 진 사람처럼. 짐은 없다.<br><br>
    등불이 그 사람 그림자를 벽에 던진다. 그림자 등에 작은 그림자가 하나 얹혀 있다. 두 팔이 목을 감았다.<br>
    본인은 모른다. 어깨가 결린다고만 한다.<br><br>
    작은 그림자가 이쪽을 돌아본다. 그림자에는 얼굴이 없다. 그래도 돌아본 줄 안다.`,
  o:[
    { l:'① 마력을 써서 등에서 떼어 낸다.', k:'gaze', dc:23, cost:{ mana:28 },
      ok:`일행 등 뒤로 가서 손바닥을 견갑골 사이에 댔다. 마력을 밀어 넣어 목을 감은 팔을 찾았다. 차고 가는 팔이다.<br><br>팔을 하나씩 풀었다. 깍지 낀 손가락부터. 다 풀리자 등의 무게가 이쪽 손으로 옮겨 온다. 그대로 바닥에 내려놓았다.<br>그림자에서 작은 것이 떨어져 나가 벽을 타고 어둠으로 기어갔다. 일행이 허리를 폈다. 그동안 몇 걸음째 무릎이 꺾이고 있었다고 했다.`,
      ng:`팔을 푸는데 깍지가 더 조인다. 일행이 켁 하고 숨이 막힌다.<br><br>손을 뗐다. 작은 그림자가 더 꼭 매달린다. 놀란 아이처럼.<br>한참을 그대로 걸었다. 일행 얼굴이 하얘졌다. 다음 계단참에서 작은 그림자가 저 혼자 내려갔다. 일행 목에 가는 손가락 자국이 붉게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20, mana:-5 } },
    { l:'② 업힌 것이 무엇을 바라는지 본다.', k:'gaze', dc:22, wake:1,
      ok:`그림자를 오래 봤다. 작은 그림자의 다리가 늘어져 있다. 걷지 못하는 다리다. 업혀서 가고 싶은 데가 있다.<br><br>업힌 것은 놓아 달라는 게 아니다. 데려다 달라는 것이다. 어디까지인지만 알면 된다. 그림자가 고개를 돌리는 쪽을 따라갔다. 복도 끝 문 앞에서 그림자 팔이 풀렸다. 문지방 앞에서.<br>작은 그림자가 문 밑으로 스며 나갔다. 일행이 허리를 펴고 놀란 얼굴로 이쪽을 봤다.<br><br>모든 붙은 것을 떼어 쫓을 일은 아니다. 무엇을 바라는지 보이면 내려 줄 데가 보인다. 쫓는 손보다 내려 주는 손이 먼저 나간다.`,
      ng:`보는데 작은 그림자가 이쪽을 향해 팔을 뻗는다. 갈아타려는 것이다.<br><br>목덜미에 찬 것이 닿는다. 일행 그림자에서 이쪽 그림자로 넘어왔다. 어깨가 내려앉는다.<br>무릎이 꺾였다. 한참을 업은 채 걸었다. 복도 끝 문지방에서 그것이 내렸다. 그때까지 숨이 반밖에 안 쉬어졌다.`,
      win:{ exp:23, dream:3, spirit:7 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'문 — 들여보내 달라는 목소리',
  x:`문을 두드린다. 세 번. 쉬고, 세 번.<br><br>
    「나야. 문 좀 열어 줘.」 일행 하나의 어머니 목소리라고 한다. 일행 얼굴이 하얗게 질렸다. 그 어머니는 오래전에 돌아가셨다.<br>
    들어오려면 들여보내 줘야 하는 것이다. 문은 안에서만 열린다. 대답 하나가 문고리다.<br><br>
    문 아래 틈으로 등불이 비친다. 바깥에 그림자가 있다.`,
  o:[
    { l:'① 문틈에 눈을 대고 바깥을 살핀다.', k:'gaze', dc:23,
      doom:{ title:'문틈', what:'문틈 너머로 빨려 나갑니다', dc:18, sec:45,
        text:`엎드려 문틈에 눈을 댔다. 바깥이 보인다. 발이 있다. 맨발이다.<br><br>그 발이 무릎을 꿇는다. 얼굴이 내려온다. 문틈 저편에 눈이 하나 댄다. 이쪽 눈 바로 앞에.<br>눈을 뗄 수가 없다. 저쪽 눈이 이쪽 눈을 당긴다. 얼굴이 문틈에 붙는다. 틈이 넓어진다. 아니, 이쪽이 얇아진다.<br><br>문틈으로 빨려 나간다. 종이처럼 얇게. 바깥 어둠 속에서 누가 반갑게 안는다.`,
        dieText:`문 두드리는 소리가 그쳤다.<br><br>문틈 아래로 등불이 비친다. 바깥에 그림자가 둘이다.<br>얼마 뒤 다시 두드린다. 세 번. 쉬고, 세 번. 「나야. 문 좀 열어 줘.」 이번엔 이쪽 목소리다.` },
      ok:`문틈에 눈을 대지 않았다. 문틈 앞에 등불을 바짝 대고 바닥에 비친 그림자만 봤다.<br><br>그림자 발이 문 쪽을 향해 있다. 발꿈치가 문 쪽이다. 발가락이 뒤를 본다. 문을 향해 선 사람의 발이 아니다.<br>일행에게 그걸 보여 주었다. 일행이 문에서 물러섰다. 「어머니는 발이 바르셨어.」 두드리는 소리가 그쳤다. 틈 밑 그림자가 거꾸로 걸어 멀어졌다.`,
      win:{ exp:24, dream:4, mind:6 } },
    { l:'② 문을 등지고 서서 들어오지 말라고 말한다.', k:'steady', dc:22,
      ok:`문에 등을 대고 섰다. 일행 대신 말했다. 「여기 당신 자리 없다. 들어오지 마라.」<br><br>문밖이 조용하다. 다시 두드린다. 더 약하게. 「추워.」<br>대답하지 않았다. 들어오지 말라는 말은 한 번이면 된다. 두 번 하면 대화가 된다. 대화는 문을 연다. 날이 샐 때까지 문을 등지고 서 있었다. 일행이 옆에서 소리 없이 울었다.`,
      ng:`말했다. 들어오지 말라고. 문밖에서 대답이 온다. 「그럼 네가 나와.」<br><br>문을 등진 등이 차가워진다. 문을 통과해 무엇이 등을 짚는다. 손바닥 다섯 손가락이 견갑골에 닿는다.<br>문에서 떨어지며 넘어졌다. 등에 손바닥 모양 얼음 자국이 남았다. 문밖에서 두드림이 새벽까지 계속됐다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'녹음 부스 — 언니의 마지막 녹음',
  x:`녹음 부스 빨간 등이 켜져 있다. 안에서 노래 언니 목소리가 난다. 「친구야, 이리 와.」 맑고 높다. 테이프다.<br><br>
    그런데 테이프가 아닌 소리도 섞여 있다. 노래가 끝날 때마다 아주 작게 숨을 고르는 소리. 녹음된 숨이 아니다. 지금 쉬는 숨이다.<br>
    언니가 아직 여기 있다. 제 목소리 녹음에 매여서. 같은 노래를 끝없이 다시 부른다.<br><br>
    부르는 말이 미끼인지, 붙잡힌 사람의 노래인지는 보는 눈만 안다.`,
  o:[
    { l:'① 노래와 숨을 갈라 언니가 무엇인지 본다.', k:'gaze', dc:22, wake:1,
      ok:`노래와 숨 사이를 들었다. 노래는 이쪽을 부른다. 숨은 이쪽을 말린다. 노래가 끝날 때마다 숨이 「오지 마」 하고 떨린다.<br><br>부르는 건 테이프다. 언니가 아니다. 언니는 테이프에 묶인 채 테이프를 따라 부를 수밖에 없다. 매번 노래 끝에서 숨으로 겨우 말린다.<br>부스 문에 손바닥을 대고 언니 숨에게만 들리게 말했다. 「안 들어간다. 알았다.」 숨이 한 번 길게 놓였다. 노래는 계속됐다. 부스 앞을 지났다.<br><br>붙잡힌 것과 붙잡는 것이 한 소리에 섞여 있을 때가 있다. 그 둘을 귀로 갈라 듣는 법. 씐 것의 목소리 밑에서 씌인 사람의 숨을 찾는다.`,
      ng:`노래와 숨을 가르려 귀를 기울이다 노래 쪽에 귀가 기운다. 맑다. 따뜻하다.<br><br>발이 부스 문 쪽으로 반 걸음 간다. 숨소리가 그 순간 떨린다. 「오지 마.」 그 소리에 정신이 들었다.<br>물러섰다. 귀 안에 노래가 남았다. 다음 층까지 흥얼거림이 이쪽 입에서 새 나왔다. 언니의 숨이 그때마다 떨리는 것 같았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 언니의 마지막 노래를 끝까지 같이 불러 준다.', k:'bond', dc:22,
      ok:`노래 끝 소절을 같이 불렀다. 언니 목소리 아래로 낮게. 한 번도 끝까지 불러 준 사람이 없었을 노래다.<br><br>마지막 음에서 같이 멈췄다. 테이프가 다음 바퀴로 넘어가려다 걸린다. 끝까지 불린 노래는 다시 시작할 까닭이 없다.<br>빨간 등이 꺼졌다. 부스 안에서 숨이 한 번 길게 놓였다. 그러고는 아무 소리도 나지 않았다. 보내 준 것이다. 노래로.`,
      ng:`같이 부르는데 언니 목소리가 이쪽 목소리를 따라온다. 아니, 이쪽이 언니 목소리를 따라간다. 높게, 더 높게.<br><br>목이 갈라진다. 끝 소절에 닿기 전에 목소리가 끊겼다. 기침이 났다. 피 맛이 났다.<br>테이프가 다시 처음으로 돌아갔다. 「친구야, 이리 와.」 노래가 끝까지 불리지 못한 채로.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 부스 안에 들어가 테이프에서 언니를 떼어 낸다.', k:'steady', dc:23,
      doom:{ title:'녹음 중', what:'녹음 부스 안으로 끌려 들어갑니다', dc:18, sec:45,
        text:`부스 문을 열고 들어갔다. 문이 등 뒤에서 닫힌다. 쉭. 밖의 소리가 다 끊긴다.<br><br>데크 위에서 테이프가 돈다. 손을 뻗었다. 마이크 앞 빨간 등이 밝아진다. 녹음이 시작된다. 이쪽 숨소리가 녹음된다.<br>언니 숨이 귀 뒤에서 떨린다. 「왜 왔어.」 마이크가 이쪽 쪽으로 기운다. 이쪽 목소리를 당긴다. 몸이 마이크 쪽으로 끌려간다.<br><br>목소리가 빠져나간다. 테이프에 감긴다. 한 바퀴, 또 한 바퀴.`,
        dieText:`빨간 등이 꺼졌다.<br><br>부스 안은 비었다. 테이프가 한 바퀴 감겨 멈췄다.<br>다시 켜졌을 때 노래가 두 목소리로 나왔다. 하나는 맑고 높다. 하나는 그 아래에서 낮게 따라 부른다. 노래가 끝날 때마다 숨이 둘이다.` },
      ok:`부스 문 사이에 신발 한 짝을 끼워 닫히지 않게 했다. 그리고 들어갔다. 마이크 쪽으로는 고개를 돌리지 않았다.<br><br>데크에서 테이프를 들어냈다. 마이크 등이 깜빡였다. 문이 신발을 물고 덜컹거린다. 테이프를 쥐고 빠져나왔다.<br>부스 밖에서 테이프 리본을 손가락으로 끝까지 풀었다. 노래가 묶여 있던 결을 하나씩. 다 풀자 부스 안에서 숨이 길게 놓였다. 보내 주었다.`,
      win:{ exp:24, dream:4, spirit:6 } }
  ] },

{ at:'A2', t:'양호실 — 데리러 오지 않는 보호자',
  x:`양호실 커튼 친 침대에 누가 누워 있다. 커튼 너머로 작은 몸 모양이 비친다.<br><br>
    침대 머리맡 종이에 적혀 있다. 「열 남. 보호자 연락함. 데리러 오실 때까지 쉼.」 날짜가 물이 들어온 날이다.<br>
    커튼 너머에서 작은 목소리가 묻는다. 「엄마 왔어요?」<br><br>
    물이 들어온 날부터 기다렸다. 아무도 오지 않았다. 아무도 올 수 없었다.`,
  o:[
    { l:'① 커튼 너머의 것이 무엇인지 본다.', k:'gaze', dc:22, wake:1,
      ok:`커튼을 걷지 않고 비친 몸을 봤다. 작다. 이불을 턱까지 끌어올렸다. 열이 나서 떨던 자세 그대로다. 해칠 것이 아니다. 기다리는 것이다.<br><br>기다리는 넋은 기다릴 까닭이 끝나야 간다. 커튼 앞에 앉아 말했다. 「엄마는 못 오셔. 네가 가야 해. 가면 계셔.」 거짓말인지 아닌지는 모른다. 그래도 말했다.<br>한참 조용하더니 이불이 천천히 꺼졌다. 커튼에 비친 몸 모양이 없어졌다. 머리맡 종이에 「귀가」라고 적혀 있었다. 이쪽이 쓰지 않았다.<br><br>보내는 일은 쫓는 일보다 말이 많이 든다. 머무는 까닭을 보고 그 까닭을 끝내 주는 말을 찾는 눈이 생겼다.`,
      ng:`보는데 커튼에 비친 몸이 일어나 앉는다. 「엄마?」 목소리가 기쁘다. 이쪽을 보고 있다.<br><br>커튼 아래로 작은 맨발이 내려온다. 이쪽 쪽으로. 아니라고 말해야 하는데 말이 안 나온다.<br>맨발이 이쪽 발등에 올라섰다. 차다. 얼음처럼. 한참 뒤에야 내려갔다. 실망한 걸음이다. 발등이 시퍼렇게 얼었다.`,
      win:{ exp:23, dream:3, spirit:7 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 마력으로 온기를 덮어 재워 준다.', k:'heal', dc:22, cost:{ mana:26 },
      ok:`커튼 아래로 손을 넣어 이불 위에 얹었다. 마력을 온기로 바꿔 덮었다. 열 내린 아이를 덮어 주듯이.<br><br>떨림이 멎는다. 작은 숨이 길어진다. 잠든다. 기다리던 것이 잠깐 기다림을 잊는다.<br>양호실 약장을 열었다. 마른 약초가 종이에 싸여 있다. 아이 열을 내리려고 준비해 둔 것이다. 한 뭉치를 챙겼다. 나머지는 머리맡에 두었다.`,
      ng:`온기를 덮었는데 이불 속이 너무 차다. 마력이 녹이기 전에 식는다.<br><br>아이가 이쪽 손을 잡는다. 따뜻한 쪽으로. 놓지 않는다. 온기가 손에서 빠져나간다.<br>손이 하얗게 질릴 때까지 잡혀 있었다. 아이가 잠들어서야 놓았다. 손가락이 굽혀지지 않는다.`,
      win:{ exp:20, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, mind:-18, mana:-5 } }
  ] },

{ at:'A', t:'거울 — 늦게 따라 하는 사람',
  x:`복도 거울 앞을 일행이 한 줄로 지난다. 거울에 다섯이 비친다.<br><br>
    셋째 사람이 비친 모습만 반 박자 늦다. 손을 들면 조금 뒤에 든다. 고개를 돌리면 조금 뒤에 돈다.<br>
    거울이 늦는 게 아니다. 셋째의 몸이 늦다. 늦는 쪽이 진짜고 빠른 쪽이 따라 하는 쪽일 수도 있다.<br><br>
    셋째가 거울을 보고 웃는다. 거울 속 셋째는 아직 웃지 않았다.`,
  o:[
    { l:'① 어느 쪽이 따라 하는지 가린다.', k:'gaze', dc:22,
      ok:`셋째에게 아무 말 없이 손뼉을 한 번 쳐 보라고 했다. 소리를 봤다. 거울 속 손이 마주치는 때와 소리가 나는 때.<br><br>소리는 거울 속 손이 마주칠 때 났다. 늦은 쪽이다. 거울 속이 진짜다. 거울 밖 셋째가 반 박자 먼저 움직인다. 미리 알고 따라 하는 것이다.<br>거울 밖 셋째 손목에 소금을 쥐여 주었다. 손이 데인 듯 펴졌다. 무엇이 거울 밖 몸에서 빠져나가 거울 속으로 숨었다. 셋째가 제 박자로 숨을 쉬었다.`,
      ng:`가리려고 보는 사이 거울 속 셋째가 이쪽을 본다. 거울 밖 셋째는 앞을 보는데.<br><br>거울 속 셋째가 손가락으로 이쪽을 가리킨다. 그러자 거울 속 이쪽이 반 박자 늦어진다.<br>거울 앞을 뛰어 지났다. 지나고 나서 손을 들어 보았다. 들려는 생각보다 손이 조금 늦게 올라왔다. 한참 그랬다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 거울을 깨뜨린다.', k:'break', dc:22,
      ok:`거울 한가운데를 등불 자루로 내리쳤다. 금이 거미줄처럼 퍼졌다.<br><br>조각마다 셋째가 비친다. 하나도 늦지 않는다. 조각 하나만 아무것도 비치지 않는다. 빈 조각이다.<br>그 조각을 소금에 싸서 버렸다. 셋째가 어깨를 털며 몸이 가벼워졌다고 했다. 깨진 거울은 다시 보지 않았다.`,
      ng:`내리치자 거울이 깨지지 않고 휜다. 물처럼. 자루가 거울 속으로 쑥 들어갔다.<br><br>안에서 누가 자루를 잡아당긴다. 손이 끌려 들어간다. 손목까지 거울 속이 차다.<br>온 힘으로 뺐다. 손등이 거울 테두리에 긁혀 피가 났다. 거울 표면에 이쪽 피가 번졌다. 거울 속에서는 번지지 않았다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'A', t:'어둠 — 이쪽 이름으로 우는 아이',
  x:`어둠 속에서 아이가 운다. 이쪽 이름을 부르며. 「언니. 형. 무서워.」 이쪽을 아는 목소리다.<br><br>
    가 보지 않을 수 없는 울음이다. 일행도 발을 멈췄다.<br>
    길 잃은 넋이 우는 것일 수도 있다. 넋의 울음을 빌려 쓰는 것일 수도 있다. 미끼는 늘 제일 가여운 소리로 운다.<br><br>
    울음이 조금 가까워졌다. 울면서 다가오는 아이는 없다.`,
  o:[
    { l:'① 울음 속에 든 것을 본다.', k:'gaze', dc:22,
      ok:`울음을 들으며 등불을 낮췄다. 바닥을 봤다. 울음이 나는 쪽에서 물이 흘러온다. 눈물이 아니다. 짐승 침처럼 끈적하다.<br><br>우는 소리는 하나인데 숨소리는 둘이다. 하나는 작고 떨린다. 하나는 크고 고르다. 고른 숨이 우는 숨을 쥐고 있다.<br>다가가지 않았다. 대신 울음 쪽으로 소금을 한 줌 길게 뿌렸다. 고른 숨이 멎었다. 작은 울음만 남았다가 흐려졌다. 쥐고 있던 손이 놓친 것이다.`,
      ng:`보는 사이 울음이 이쪽 이름을 더 또렷이 부른다. 어릴 때 이쪽을 부르던 동생 목소리다.<br><br>몸이 앞으로 기운다. 일행이 뒤에서 허리띠를 잡았다. 그 순간 울음이 그쳤다. 대신 웃음이 났다.<br>등불 앞까지 젖은 손자국이 줄지어 다가와 있었다. 한 걸음만 더 갔어도 닿았다. 무릎이 떨려 한동안 못 걸었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 다가가 아이를 안아 든다.', k:'bond', dc:23,
      doom:{ title:'안긴 것', what:'안아 든 것에게 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`다가가 무릎을 꿇었다. 작은 것이 품에 안긴다. 가볍다. 떨고 있다. 안심이 됐다.<br><br>안긴 것이 이쪽 목을 감는다. 두 팔로. 그리고 더 감는다. 팔이 셋이다. 넷이다.<br>무게가 갑자기 커진다. 작은 것이 아니었다. 품 안에서 어둠이 일어선다. 안긴 채로 이쪽을 들어 올린다.<br><br>끌려간다. 안긴 채로. 어둠 쪽으로. 귀에 대고 아직도 운다. 이쪽 이름으로.`,
        dieText:`울음이 그쳤다.<br><br>얼마 뒤 어둠 속에서 다시 울음이 났다. 이번엔 일행 하나의 이름을 부른다. 「누나. 무서워.」<br>목소리가 이쪽 목소리다. 어릴 때의.` },
      ok:`다가가기 전에 겉옷을 벗어 소금을 뿌렸다. 그리고 다가가 아이에게 겉옷째 덮어 안았다.<br><br>품 안에서 두 가지가 갈린다. 겉옷 안에 남은 작고 가벼운 것. 소금을 피해 빠져나간 크고 무거운 것.<br>남은 것을 안고 등불로 돌아왔다. 겉옷을 펴자 아무도 없다. 젖은 자국과 따뜻함만. 넋은 안긴 채로 떠났다. 안아 준 뒤에 떠났다.`,
      win:{ exp:24, dream:4, spirit:7 } },
    { l:'③ 마력을 써서 미끼가 된 넋을 쥔 손에서 빼낸다.', k:'gaze', dc:22, cost:{ mana:30 }, wake:1,
      ok:`울음 쪽으로 손을 뻗어 마력을 길게 보냈다. 실처럼. 울음에 닿았다. 작고 떨리는 것. 그것을 쥔 큰 손.<br><br>큰 손가락 사이로 마력을 밀어 넣어 하나씩 폈다. 펴진 틈으로 작은 넋을 끌어냈다. 이쪽으로. 등불 안으로.<br>작은 것이 등불 둘레를 한 바퀴 돌고 위로 흩어졌다. 어둠 속 큰 것이 빈손을 쥐었다 폈다. 미끼를 잃은 손은 울 줄 모른다. 조용해졌다.<br><br>미끼가 된 넋도 넋이다. 쥔 것과 쥐인 것을 가려 쥐인 쪽만 빼내는 손. 붙잡힌 것을 구해 내는 결을 하나 더 익혔다.`,
      ng:`마력이 울음에 닿는 순간 큰 손이 마력을 쥔다. 실을 감듯이. 이쪽으로 거꾸로 온다.<br><br>손끝부터 차가워진다. 팔꿈치까지. 끊어야 한다. 끊으면 작은 넋도 놓친다.<br>끊었다. 울음이 뚝 그쳤다. 작은 넋이 어떻게 됐는지는 모른다. 팔이 한참 얼음 같았다. 마음은 더 차가웠다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-26, mana:-5 } }
  ] },

{ at:'A1', t:'방청석 — 눌린 방석',
  x:`방청석 의자 방석이 군데군데 눌려 있다. 엉덩이 모양으로. 작다. 아이들 자리다.<br><br>
    눌린 자리가 아직 따뜻하다. 표지판이 켜지면 그 자리들에서 박수가 난다.<br>
    맨 앞줄 가운데 자리만 눌리지 않았다. 방석이 새것처럼 볼록하다. 누가 앉을 자리다.<br><br>
    방청석 통로로 지나가려면 그 자리 앞을 지나야 한다.`,
  o:[
    { l:'① 눌린 자리마다 무엇이 앉아 있는지 본다.', k:'gaze', dc:22,
      ok:`의자를 하나씩 봤다. 눈에 힘을 빼고 비스듬히. 눌린 방석 위에 희미하게 앉아 있다. 아이들이다. 무릎을 모으고 손을 무릎에 얹었다. 방송을 보러 온 자세다.<br><br>나쁜 것들이 아니다. 아직 방송이 끝나지 않아 못 간 아이들이다. 맨 앞줄 빈자리는 아이들이 비워 둔 자리가 아니다. 누가 아이들을 위해 따로 마련한 자리다. 새로 올 아이를 위한.<br>아이들 사이로 지나며 맨 앞줄 빈 방석을 뒤집어 놓았다. 뒤집힌 자리엔 아무도 못 앉는다. 아이들 몇이 이쪽을 돌아보는 기척이 났다.`,
      ng:`보는데 아이들이 일제히 이쪽을 본다. 눈이 없다. 그래도 본다.<br><br>맨 앞줄 빈자리 쪽으로 아이들 손이 일제히 가리킨다. 앉으라고. 같이 보자고.<br>통로를 뒷걸음질로 빠져나왔다. 아이들 손가락이 그 내내 이쪽을 따라왔다. 박수 표지판이 켜졌다. 박수가 이쪽 등을 떠밀었다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 아이들 사이에 끼어 앉아 박수를 같이 친다.', k:'hide', dc:22,
      ok:`빈자리 말고 눌린 자리 옆 의자에 앉았다. 표지판이 켜지자 같이 박수를 쳤다. 아이들처럼 가볍게.<br><br>방청석은 앉아 있는 사람을 뽑지 않는다. 뽑히는 건 서 있는 사람이다. 맨 앞 빈자리를 채우려고 바람잡이가 통로를 오간다. 이쪽은 아이들 사이에서 안 보인다.<br>박수가 꺼지자 몸을 낮춰 옆 통로로 빠졌다. 옆자리 눌린 방석이 한 번 들썩였다. 같이 가자는 것처럼.`,
      ng:`앉았는데 의자가 이쪽 무게에 삐걱 운다. 아이들 의자는 소리가 안 난다.<br><br>바람잡이 사진 얼굴이 이쪽을 향한다. 오, 무거운 친구가 있네요! 웃음이 터진다.<br>아이들 틈에서 일어나 뛰었다. 아이들 손이 이쪽 옷자락을 잡아당긴다. 앉으라고. 소매가 찢어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'식당 — 수저를 놓는 손',
  x:`식당 배식대 앞 긴 식탁에 수저가 놓여 있다. 물이 가슴까지 찼는데 식탁 위는 마른 데가 있다.<br><br>
    보이지 않는 손이 수저를 하나씩 놓는다. 자리마다. 숟가락, 젓가락. 정성스럽게. 흐트러진 것은 바로잡는다.<br>
    벌써 이백 몇 벌이다. 식당 아주머니의 손이다. 아이들 밥때를 한 번도 거르지 않은 손.<br><br>
    식탁 끝에 일행 수만큼 수저가 더 놓였다. 막 놓였다.`,
  o:[
    { l:'① 이쪽 자리에 앉아 수저를 든다.', k:'gaze', dc:23,
      doom:{ title:'밥때', what:'수저를 든 채 숨이 물로 찹니다', dc:18, sec:45,
        text:`이쪽 자리에 앉았다. 숟가락을 들었다. 차다. 은빛이다. 오래 닦은 숟가락이다.<br><br>식탁 위로 밥이 퍼진다. 보이지 않는 손이 국을 떠 준다. 따뜻한 김이 오른다. 배가 고팠다. 한 숟가락을 떴다.<br>입에 넣는 순간 맛이 없다. 물이다. 차다. 목으로 넘어간다. 숨 쉬는 자리로.<br><br>숟가락을 놓으려는데 손이 안 놓는다. 다음 숟가락을 뜬다. 가슴까지 찬 물이 안에서도 찬다.`,
        dieText:`식당 긴 식탁에 다들 앉아 있다. 이백 몇. 고개를 숙이고.<br><br>식당 아주머니 손이 빈 그릇을 거둔다. 하나씩. 정성스럽게.<br>식탁 끝 자리 하나도 거두었다. 숟가락이 반듯하게 놓였다. 다음 밥때를 기다린다.` },
      ok:`앉기 전에 숟가락을 뒤집어 놓았다. 오목한 데가 아래로 가게. 다 먹은 사람은 그렇게 놓는다.<br><br>보이지 않는 손이 그 숟가락을 집어 본다. 오래 들고 있다. 그러고는 다른 숟가락들 사이에 거둬 넣었다. 다 먹은 아이는 밥을 더 주지 않는다.<br>식탁 끝 일행 몫 수저가 하나씩 거둬졌다. 아주 따뜻한 손이 등을 한 번 쓸고 지나갔다. 잘 먹었다는 듯이.`,
      win:{ exp:24, dream:4, hp:8 } },
    { l:'② 수저 놓는 손이 무엇인지 본다.', k:'gaze', dc:22, wake:1,
      ok:`손이 놓이는 자리를 봤다. 수저를 놓을 때마다 허공이 조금 일그러진다. 굽은 허리, 두툼한 손목, 앞치마 끈. 식당 아주머니다. 해칠 손이 아니다.<br><br>밥때를 지키는 손이다. 아이들이 다 먹을 때까지 안 가는 손. 아이들은 물 밑에서 더 먹지 못한다. 그래서 끝나지 않는다.<br>배식대 앞에 서서 큰 소리로 말했다. 「다 먹었습니다. 잘 먹었습니다.」 일행도 따라 했다. 손이 멈췄다. 한참 뒤 식탁 끝부터 수저가 하나씩 거둬졌다. 오래 걸렸다. 다 거두고 앞치마 끈이 풀려 물에 떴다.<br><br>머무는 넋은 맡은 일이 끝나야 간다. 그 일을 끝내 줄 말 한마디를 찾는다. 쫓는 손이 아니라 끝내 주는 입이 퇴마사에게 하나 더 생겼다.`,
      ng:`보는데 손이 이쪽을 발견한다. 반가운 듯이. 이쪽 어깨를 잡아 자리로 데려간다.<br><br>세다. 앉혀야 한다는 손이다. 밥은 앉아서 먹어야 한다. 의자에 무릎이 꺾여 털썩 앉았다.<br>숟가락을 쥐여 주는 손을 뿌리치고 일어섰다. 손이 몇 번이나 어깨를 눌렀다. 어깨뼈가 욱신거린다. 식당을 나올 때까지 그 손이 서운해하는 게 느껴졌다.`,
      win:{ exp:23, dream:3, spirit:7 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 숨이 여섯',
  x:`등불을 줄이고 쉬었다. 조용하다. 숨소리만 들린다.<br><br>
    다섯이다. 일행 다섯. 하나, 둘, 셋, 넷, 다섯. 그런데 다섯째 숨 뒤에 하나가 더 있다. 아주 느리다.<br>
    찬 공기에 숨이 하얗게 보인다. 입김이 다섯 갈래 오른다. 여섯째는 입김이 안 보인다.<br><br>
    입김이 없는 숨은 몸이 없는 숨이다.`,
  o:[
    { l:'① 여섯째 숨이 어디서 나는지 본다.', k:'gaze', dc:22, wake:1,
      ok:`숨을 죽이고 숨소리를 하나씩 지워 나갔다. 일행 입김을 하나씩 눈으로 짚었다. 남는 소리 하나.<br><br>둘째와 셋째 사이다. 둘 사이 바닥에 물이 조금 고였다. 거기서 난다. 물웅덩이가 숨을 쉰다. 웅덩이 표면이 숨 따라 조금씩 오르내린다.<br>소금을 웅덩이에 떨어뜨렸다. 숨이 멎었다. 웅덩이가 더는 오르내리지 않는다. 둘째와 셋째가 그제야 다리를 뻗었다. 둘 다 그 자리가 이상하게 차다고 했다.<br><br>안 보이는 것도 숨을 쉬면 숨 자리가 있다. 소리를 하나씩 지워 남는 하나를 짚는 법을 알았다. 셀 수 있으면 짚을 수 있다.`,
      ng:`어디서 나는지 찾는 사이 여섯째 숨이 이쪽 귀 바로 옆에서 난다.<br><br>느리다. 차다. 귓바퀴에 숨결이 닿는다. 입김은 없다.<br>움직이지 않았다. 움직이면 안 될 것 같았다. 숨이 멀어질 때까지 한참 굳어 있었다. 귀가 얼어 감각이 없어졌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20, spirit:-18 } },
    { l:'② 다 같이 숨을 멈춘다.', k:'steady', dc:22,
      ok:`손짓으로 다 같이 숨을 멈추게 했다. 다섯이 멈췄다. 여섯째만 남았다. 느리게, 혼자.<br><br>여섯째도 멈춘다. 들킨 걸 안다. 조용하다. 아무도 숨을 안 쉰다.<br>오래 참았다. 먼저 쉬는 쪽이 진다. 가슴이 터지기 직전 저쪽에서 숨이 새 나왔다. 길게. 그리고 멀어졌다. 다 같이 숨을 몰아쉬었다.`,
      ng:`다 같이 멈췄다. 여섯째도 멈췄다. 누가 먼저 쉬나.<br><br>일행 하나가 못 참고 숨을 터뜨렸다. 여섯째가 그 숨에 맞춰 같이 쉬었다. 그 사람 숨이 둘이 됐다.<br>그 일행이 밤새 숨이 차다고 했다. 숨 한 번에 두 번 쉬어야 숨이 찬다고. 이쪽도 밤새 그 사람 숨을 셌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'벽 — 사진 속 일행',
  x:`벽에 사진 한 장이 붙어 있다. 새것이다. 이 복도에서 찍은 사진이다. 이쪽 일행이다.<br><br>
    다섯이 서 있다. 지쳐 보인다. 그런데 여섯이다. 맨 끝에 하나가 더 서 있다. 얼굴이 흐리다. 이쪽 어깨에 손을 얹었다.<br>
    찍힌 기억이 없다. 이 복도에 처음 왔다.<br><br>
    사진 속 이쪽 어깨가 실제로 무겁다.`,
  o:[
    { l:'① 여섯째가 누구인지 본다.', k:'gaze', dc:22,
      ok:`흐린 얼굴을 오래 봤다. 흐린 데는 흐린 대로 봐야 한다. 윤곽만.<br><br>키가 크다. 손이 길다. 어깨에 얹은 손가락이 넷이다. 사람이 아니다. 사진에 끼어든 것이다. 다음엔 실제로 끼어든다.<br>어깨 위를 손으로 털었다. 아무것도 없는데 털었다. 사진 속 여섯째 손이 이쪽 어깨에서 미끄러졌다. 어깨가 가벼워졌다.`,
      ng:`보다 보니 여섯째 얼굴이 조금씩 또렷해진다. 이쪽 얼굴을 닮아 간다.<br><br>사진 속 원래 이쪽 얼굴은 흐려진다. 자리가 바뀌는 중이다.<br>사진을 손바닥으로 덮었다. 손바닥 밑에서 사진이 따뜻하다. 한참 덮은 뒤 떼었다. 둘 다 흐릿해져 있었다. 어깨가 여전히 무겁다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 소금을 사진에 문질러 여섯째만 지운다.', k:'fix', dc:22,
      ok:`소금 한 꼬집을 손가락에 묻혀 여섯째 얼굴을 문질렀다. 사진 약이 일어나며 흐려진다.<br><br>여섯째가 지워졌다. 이쪽 어깨에 얹힌 손도 같이. 다섯만 남았다.<br>사진을 떼어 품에 넣었다. 지친 다섯이 서 있다. 이 복도를 지나간 다섯이다. 지나갔다는 증거는 남겨 두고 싶었다.`,
      ng:`문지르는데 여섯째가 아니라 이쪽 얼굴이 지워진다. 소금이 미끄러졌다.<br><br>사진 속 이쪽이 얼굴 없는 사람이 됐다. 여섯째는 그대로다. 손이 아직 어깨에 있다.<br>사진을 찢었다. 어깨 무게는 다음 층까지 따라왔다. 찢은 조각이 바닥에서 바람도 없이 한쪽으로 쓸려 갔다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 사진을 떼어 등불에 태운다.', k:'break', dc:22,
      ok:`사진을 떼어 불에 댔다. 모서리부터 오그라든다.<br><br>타는 순서가 이상하다. 여섯째부터 탄다. 다른 다섯은 마지막까지 남는다. 불도 무엇이 남의 것인지 안다.<br>재가 됐다. 어깨가 가벼워졌다. 재에서 아주 짧게 비명 같은 소리가 났다.`,
      ng:`불에 대자 사진 속 다섯이 먼저 탄다. 여섯째는 안 탄다. 여섯째만 남은 사진 조각이 손에서 떨어졌다.<br><br>조각이 바닥을 미끄러져 벽 틈으로 들어간다. 사진 속 여섯째만 남아서.<br>다음 쉬는 자리까지 아무도 등을 벽에 대지 못했다. 다들 어깨가 무겁다고 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다',
  x:`놀이 세트 한쪽이 공 바다다. 빨강, 노랑, 파랑 공이 허리 깊이로 채워졌다.<br><br>
    공들이 조금씩 들썩인다. 아래에서 무엇이 헤엄친다. 공 사이로 작은 손 하나가 나와 허공을 쥔다.<br>
    공 바다를 건너야 미끄럼틀 탑으로 간다. 다른 길은 없다.<br><br>
    공 사이 손이 이쪽을 향해 펴진다. 꺼내 달라는 손이다.`,
  o:[
    { l:'① 공의 흐름을 보고 아래의 것을 피해 건넌다.', k:'sense', dc:22,
      ok:`공이 들썩이는 데를 봤다. 아래 것이 움직이면 공이 위로 밀린다. 움직이는 길이 보인다.<br><br>길은 둘이다. 작은 손이 움직이는 길과 큰 것이 움직이는 길. 큰 것이 작은 손 뒤를 따른다.<br>큰 것이 반대쪽 끝에 갔을 때 건넜다. 공을 헤치며. 허리까지 공에 묻혀 걸었다. 다 건너고 돌아보니 공들이 이쪽 발자국 모양으로 꺼져 있다가 천천히 메워졌다.`,
      ng:`들썩임을 따라 건넜는데 반쯤에서 공이 멈춘다. 다 멈췄다. 아래 것이 움직이지 않는다.<br><br>어디 있는지 모른다. 발밑일 수도 있다. 한 걸음 내딛자 공 아래에서 무엇이 정강이를 쓸었다.<br>공을 헤치며 뛰었다. 넘어져 공 속에 얼굴이 묻혔다. 겨우 빠져나왔을 때 발목에 작은 손톱자국이 줄줄이 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 공 사이 작은 손을 잡아 꺼낸다.', k:'gaze', dc:23,
      doom:{ title:'공 바다', what:'공 바다 밑으로 끌려 들어갑니다', dc:18, sec:45,
        text:`작은 손을 잡았다. 차다. 떨고 있다. 당겼다.<br><br>안 올라온다. 아래에서 누가 같이 당긴다. 작은 손 뒤에 큰 손이 있다. 작은 손을 쥐고, 이쪽을 낚는다.<br>작은 손이 이쪽 손을 놓지 않는다. 겁나서. 큰 손이 당긴다. 이쪽 팔이 공 속으로 들어간다. 어깨가, 머리가.<br><br>끌려 들어간다. 공 바다 밑으로. 공 사이로 빛이 알록달록하게 멀어진다. 아래는 생각보다 깊다.`,
        dieText:`공 바다 위로 공이 몇 개 튀어 올랐다가 떨어졌다. 그리고 잠잠해졌다.<br><br>공 사이로 손이 하나 나와 허공을 쥔다. 어른 손이다.<br>그 옆에 작은 손이 하나 더. 둘이 서로를 잡지 못하고 허공만 쥔다.` },
      ok:`잡기 전에 손바닥에 소금을 쥐었다. 소금 쥔 손으로 작은 손을 잡았다.<br><br>작은 손은 놓지 않는다. 그 뒤에서 큰 손이 당기다 소금에 닿아 움찔 놓친다. 작은 손만 딸려 올라왔다. 공 위로. 손목, 팔꿈치, 그다음은 없다. 손만 있다.<br>손이 이쪽 손을 한 번 꽉 쥐었다가 흩어졌다. 꺼내 준 것은 손 하나지만 손 하나도 넋이다. 공 바다를 건넜다. 아래 것이 더는 따라오지 않았다.`,
      win:{ exp:24, dream:4, spirit:6 } }
  ] },

{ at:'A2', t:'체육관 — 천장 밑 공기',
  x:`물 밑 체육관이다. 천장 철골 아래 공기가 한 뼘 남았다. 일행이 거기 얼굴만 내밀고 숨을 쉰다.<br><br>
    공기 주머니가 좁다. 얼굴이 다섯이 아니다. 여덟이다. 셋이 더 있다. 천장에 얼굴을 대고 숨을 쉰다.<br>
    물에 잠긴 지 오래된 얼굴들이다. 아직 숨 쉬는 법을 기억한다. 공기를 같이 나눈다.<br><br>
    공기가 빠르게 준다. 여덟이 나눠 쉬기에는 모자란다.`,
  o:[
    { l:'① 어느 얼굴이 일행이고 어느 얼굴이 아닌지 가린다.', k:'gaze', dc:22, wake:1,
      ok:`어둡다. 얼굴들이 다 젖었다. 다 창백하다. 숨을 봤다. 일행 숨은 물방울이 튄다. 급하다. 셋은 숨이 고르다. 숨 쉬는 척하는 숨이다. 들이쉬는데 공기가 안 준다.<br><br>공기를 먹는 건 일행뿐이다. 셋은 공기를 먹지 않는다. 같이 있고 싶을 뿐이다. 쫓을 까닭이 없다. 다만 일행이 겁에 질려 버둥대면 공기가 더 준다.<br>셋에게 들리게 말했다. 「같이 있어도 된다. 우리는 곧 간다.」 셋이 조금씩 비켜 주었다. 일행에게 숨을 길게 쉬게 했다.<br><br>모든 넋을 쫓으면 숨 쉴 자리도 줄어든다. 해 없는 것과 해 있는 것을 숨 하나로 가르는 눈. 무엇을 내버려 둘지 아는 것도 일이다.`,
      ng:`가리는 사이 공기가 더 줄었다. 셋이 이쪽 얼굴 쪽으로 다가온다. 같이 쉬려고.<br><br>찬 뺨이 이쪽 뺨에 닿는다. 물 냄새가 코로 들어온다. 숨이 막힌다.<br>물속으로 고개를 박았다가 다른 자리에 얼굴을 내밀었다. 물을 먹었다. 가슴이 찢어질 것처럼 기침이 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 일행 손을 서로 잡게 해 숨을 맞춘다.', k:'bond', dc:22,
      ok:`물속에서 일행 손을 하나씩 찾아 잡게 했다. 다섯이 한 줄. 손을 쥐었다 펴는 것으로 숨 박자를 맞췄다. 들이쉬고, 참고, 내쉬고.<br><br>박자를 맞추니 공기가 덜 준다. 버둥대는 사람이 없다. 세 얼굴이 그 박자를 따라 한다. 같이 있고 싶은 것이다.<br>숨이 고르게 되자 물속 출구 쪽으로 다 같이 잠수했다. 손을 놓지 않았다. 셋은 천장에 남았다.`,
      ng:`손을 잡게 했는데 하나가 많다. 여섯째 손이 줄 끝을 잡았다. 차다.<br><br>그 손이 박자를 다르게 친다. 들이쉴 때 참으라고, 참을 때 들이쉬라고. 일행 하나가 물을 들이켰다.<br>끌고 올라와 등을 쳤다. 물을 토했다. 겨우 숨이 돌아왔다. 다들 공기 주머니에서 한참 떨었다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-26, spirit:-20 } },
    { l:'③ 물 밑 체육 창고 쪽으로 먼저 잠수해 본다.', k:'luck', dc:22,
      ok:`공기를 한 번 깊이 들이쉬고 잠수했다. 체육 창고 문이 반쯤 열려 있다. 안쪽 천장에 공기가 따로 고여 있다. 넉넉하다.<br><br>돌아와 일행을 데려갔다. 창고 안 선반 위에 물이 안 닿은 상자가 있다. 운동회 날 나눠 주려던 물병들이다. 마개가 꼭 닫혀 있다.<br>맑은 물을 나눠 마셨다. 물 밑에서 마시는 맑은 물이다. 이상한 맛이 났다. 좋은 쪽으로.`,
      ng:`잠수했는데 창고 문이 안 열린다. 안에서 누가 밀고 있다.<br><br>숨이 다 됐다. 돌아오는 길을 잃었다. 철골 사이를 더듬었다. 공기 주머니를 찾았을 때 눈앞이 하얬다.<br>숨을 몰아쉬었다. 귀에서 물이 안 빠진다. 창고 쪽에서 문 두드리는 소리가 물을 타고 들렸다. 안에서 밖으로.`,
      win:{ exp:16, item:'맑은 물', hp:7 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'복도 — 벽 틈에서 나온 손',
  x:`복도 벽 틈에서 손 하나가 나와 있다. 손바닥이 위를 향했다. 펴져 있다.<br><br>
    손목까지만 나왔다. 그 너머는 벽 속이다. 손가락이 아주 조금씩 떨린다. 추운 손이다.<br>
    잡아 달라는 손인지, 잡으려는 손인지. 손바닥만 보고는 모른다.<br><br>
    일행이 지나가자 손이 따라 기운다. 조금씩.`,
  o:[
    { l:'① 손이 당기는 손인지 청하는 손인지 본다.', k:'gaze', dc:22,
      ok:`손바닥 굳은살을 봤다. 손가락 끝 안쪽이 닳았다. 무엇을 잡고 놓지 않으려 한 손이다. 그런데 엄지가 바깥으로 벌어졌다. 잡으려는 손은 엄지가 안으로 접힌다.<br><br>청하는 손이다. 무엇을 쥐여 달라는 손. 잡아 끌 생각은 없다. 그 손에 소금 한 꼬집과 마른 빵 부스러기를 얹어 주었다.<br>손이 천천히 오므려 쥐었다. 벽 속으로 들어갔다. 틈 너머에서 아주 작게, 고맙다는 숨이 새 나왔다.`,
      ng:`보려고 몸을 숙였다. 손이 기운다. 이쪽 쪽으로. 엄지가 안으로 접힌다.<br><br>손목을 잡혔다. 벽 쪽으로 당긴다. 세다. 어깨가 벽에 부딪혔다. 얼굴이 틈 앞에 왔다. 틈 너머가 깜깜하다.<br>일행이 허리를 잡아 끌어냈다. 손목에 손가락 자국이 넷. 틈 너머에서 손톱이 벽을 긁었다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 소금 쥔 손으로 그 손을 맞잡는다.', k:'heal', dc:22,
      ok:`소금을 손바닥에 쥐고 그 손을 맞잡았다. 차다. 떤다.<br><br>당기지 않는다. 맞잡은 손이 오래 그대로 있다. 소금이 둘 사이에서 녹아 물이 된다. 그 손이 그걸 다 쥐었다.<br>손이 놓았다. 벽 속으로 들어갔다. 이쪽 손바닥에 소금 대신 따뜻함이 남았다.`,
      ng:`맞잡는 순간 그 손이 이쪽 손가락 사이로 손가락을 엮는다. 깍지. 풀리지 않는다.<br><br>소금이 손바닥 사이에서 녹지 않는다. 그 손이 소금을 무서워하지 않는다.<br>칼끝으로 그 손등을 그었다. 피 대신 물이 났다. 손이 풀렸다. 이쪽 손가락 사이가 찢어져 피가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 이쪽 몸의 무게',
  x:`쉬려고 앉았는데 일어나기가 힘들다. 몸이 무겁다. 피곤해서가 아니다.<br><br>
    어깨 뒤가 차다. 목덜미가 차다. 손을 대 보면 아무것도 없다.<br>
    퇴마사는 남에게 붙은 것을 본다. 제 몸에 붙은 것은 제일 늦게 본다. 등은 제 눈으로 못 보니까.<br><br>
    언제부터인지 모른다. 아까 그 계단부터일 수도 있다.`,
  o:[
    { l:'① 일행에게 기대 버티며 붙은 것이 지칠 때까지 기다린다.', k:'steady', dc:22,
      ok:`일행 등에 등을 기댔다. 사람 등은 따뜻하다. 붙은 것은 따뜻한 데를 싫어한다.<br><br>오래 그대로 있었다. 어깨 뒤 찬 것이 이쪽 등과 일행 등 사이에 끼었다. 갈 데가 없다. 차가움이 조금씩 줄어든다.<br>한참 뒤 몸이 가벼워졌다. 등 사이에서 무엇이 빠져나가 바닥을 기어 어둠으로 갔다. 일행이 등이 서늘했다고 했다.`,
      ng:`기댔다. 일행 등이 차다. 그 사람 등에도 붙어 있다. 같은 것이다. 둘을 오가며.<br><br>둘이 서로 기댄 사이에서 찬 것이 넓어진다. 둘 다 무거워진다. 일어날 수가 없다.<br>다른 일행이 소금을 뿌려 겨우 떨어졌다. 둘 다 한참 어깨를 못 폈다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 이쪽 그림자를 보고 제 몸의 것을 떼어 낸다.', k:'gaze', dc:23, wake:1,
      ok:`등은 못 봐도 그림자는 볼 수 있다. 등불을 앞에 두고 벽에 비친 제 그림자를 봤다. 어깨 위가 볼록하다. 사람 그림자에 없는 혹.<br><br>그림자를 보며 손을 등 뒤로 넘겼다. 그림자 손이 그 혹에 닿는 자리까지. 잡았다. 차다. 미끄럽다. 그림자를 보며 천천히 떼어 앞으로 끌어냈다. 등불 앞에 내던졌다.<br>무엇이 등불 빛에 오그라들며 바닥 틈으로 숨었다. 몸이 가벼워졌다.<br><br>제 몸에 붙은 것은 남의 눈이나 제 그림자로 본다. 등 뒤를 보는 다른 눈을 갖는 법. 이제 쉬는 자리마다 제 그림자부터 한 번 본다.`,
      ng:`그림자를 보는데 혹이 움직인다. 이쪽 그림자 머리 쪽으로. 그림자 얼굴을 덮는다.<br><br>벽에 비친 이쪽 그림자가 머리가 없다. 혹이 머리 자리에 앉았다. 그림자가 이쪽과 다르게 고개를 갸웃한다.<br>등불을 껐다. 그림자가 사라졌다. 어둠 속에서 몸이 훨씬 더 무거웠다. 다시 불을 켤 때까지 한참 숨이 막혔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A1', t:'스튜디오 — 방글이 탈 속',
  x:`스튜디오 동산 세트 한가운데 방글이가 서 있다. 노란 해 얼굴 인형탈. 그려 넣은 입이 얼굴보다 길다.<br><br>
    탈 눈구멍은 그물로 막혔다. 그물 너머가 깜깜하다. 아무것도 안 보이는데, 보고 있다.<br>
    탈 안에 든 것이 무엇인지 아직 아무도 모른다. 사람이 들어갔던 적은 있다.<br><br>
    방글이가 두 팔을 벌린다. 카메라 셋의 빨간 불이 동시에 켜진다.`,
  o:[
    { l:'① 눈구멍 그물 너머를 들여다본다.', k:'gaze', dc:23,
      doom:{ title:'눈구멍', what:'방글이 탈 속으로 빨려 들어갑니다', dc:18, sec:45,
        text:`가까이 가서 눈구멍 그물에 얼굴을 댔다. 그물 너머가 보인다. 탈 안쪽. 텅 비었다.<br><br>안쪽 벽에 얼굴들이 붙어 있다. 그려 넣은 얼굴이 아니다. 납작해진 얼굴들. 다들 눈을 뜨고 눈구멍 쪽을 본다. 바깥을 보려고.<br>그물이 얼굴에 붙는다. 눈구멍이 넓어진다. 아니, 이쪽이 납작해진다. 안쪽에서 손들이 그물 너머로 이쪽 얼굴을 쥔다.<br><br>탈 속으로 빨려 들어간다. 안쪽 벽에 자리가 하나 비어 있다.`,
        dieText:`방글이가 팔을 내렸다. 카메라 불이 꺼졌다.<br><br>그려 넣은 입이 조금 더 길어졌다. 웃는 끝이 귀까지 올라갔다.<br>다음 방송 때 방글이는 노래를 더 잘 불렀다. 목소리가 하나 늘어서.` },
      ok:`그물에 얼굴을 대지 않았다. 등불을 들어 그물 너머로 빛만 들이밀었다.<br><br>안쪽 벽에 얼굴들이 붙어 있다. 납작하다. 빛에 눈을 찌푸린다. 사람이 들어갔던 적이 있다. 여럿이. 다 나오지 못했다.<br>탈에서 한 걸음 물러섰다. 방글이 팔이 허공을 안았다. 빛이 눈구멍에 들어가 있는 동안 탈은 앞을 못 봤다. 그 틈에 세트 뒤로 빠졌다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 마력을 써서 탈 속에 붙은 것들을 하나씩 떼어 낸다.', k:'break', dc:23, cost:{ mana:32 },
      ok:`방글이 등 뒤로 돌아가 등에 손바닥을 댔다. 마력을 밀어 넣었다. 안쪽 벽에 붙은 얼굴들이 손끝에 걸린다. 하나, 둘. 일곱.<br><br>하나씩 떼어 냈다. 벽에 너무 오래 붙어 있어 얇다. 찢어지지 않게. 떼어진 얼굴은 탈 입으로 빠져나가 등불 둘레에 흩어졌다.<br>마지막을 떼자 탈이 무릎을 꿇었다. 안에 아무것도 없다. 그려 넣은 입만 웃는다. 카메라 불이 꺼졌다.`,
      ng:`떼어 내는데 얼굴들이 떨어지지 않으려 한다. 떼어지면 갈 데가 없다고 버틴다.<br><br>마력이 얼굴들 사이에서 헛돈다. 탈이 이쪽 쪽으로 돈다. 등 뒤에서 앞으로. 그려 넣은 입이 이쪽 얼굴 앞에 있다.<br>뒤로 넘어지며 물러났다. 마력이 다 빠졌다. 방글이가 팔을 벌린 채로 한참 이쪽을 향해 서 있었다.`,
      win:{ exp:23, dream:3, spirit:8 }, lose:{ hp:-24, spirit:-26, mana:-5 } },
    { l:'③ 카메라 불이 꺼질 때까지 세트 기둥 뒤에 숨는다.', k:'hide', dc:22,
      ok:`세트 기둥 뒤에 몸을 붙였다. 카메라는 셋이다. 기둥 하나가 셋을 다 가려 주는 자리가 있다. 바닥 테이프 자국이 그 자리를 알려 준다. 출연자 대기 자리다.<br><br>방글이가 팔을 벌린 채 돈다. 안을 친구를 찾는다. 기둥 뒤까지는 안 온다. 대기 자리는 출연자 자리가 아니다.<br>불이 꺼지자 빠져나왔다. 방글이가 빈 팔을 내리는 소리가 들렸다. 천이 스치는 소리.`,
      ng:`숨었는데 카메라 하나가 고개를 돌린다. 기둥 너머까지. 빨간 불이 이쪽 어깨를 잡는다.<br><br>방글이가 이쪽을 향해 걸어온다. 큰 발이 세트 바닥을 쿵쿵 울린다.<br>기둥을 끼고 돌며 달아났다. 세트 소품에 걸려 넘어졌다. 무릎이 찢어졌다. 등 뒤에서 팔이 허공을 안는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A2', t:'강당 — 사감의 열쇠',
  x:`강당 관람석 통로로 사감이 지나간다. 열쇠 꾸러미 소리. 찰랑, 찰랑. 명찰 줄을 하나씩 짚으며 센다.<br><br>
    사감 몸이 이상하다. 걸음이 둘이다. 한 걸음은 서두르고 한 걸음은 끈다.<br>
    한 몸에 둘이 들었다. 하나는 세고, 하나는 세는 걸 늦춘다.<br><br>
    관람석 맨 끝에 일행이 숨어 있다. 세는 손이 가까워진다.`,
  o:[
    { l:'① 사감 몸 안의 둘을 가려 본다.', k:'gaze', dc:22, wake:1,
      ok:`걸음을 봤다. 서두르는 걸음은 열쇠를 흔든다. 끄는 걸음은 열쇠를 꽉 쥔다. 흔드는 쪽이 세는 쪽이다. 쥐는 쪽이 막는 쪽이다.<br><br>막는 쪽이 진짜 사감이다. 물이 든 날부터 아이들 대신 세어지면서 세는 것을 늦춰 왔다. 몸 안에서 오래 싸웠다.<br>사감이 이쪽 줄에 오기 직전 소금을 열쇠 꾸러미 쪽으로 던졌다. 흔드는 쪽이 움찔한다. 쥐는 쪽이 그 틈에 열쇠를 꽉 쥐어 소리를 죽였다. 세는 소리가 멈춘 채로 사감이 이쪽 줄을 지나갔다.<br><br>한 몸 안의 둘을 걸음과 손으로 가른다. 누가 몸을 쥐고 누가 버티는지. 버티는 쪽을 거드는 법을 알았다.`,
      ng:`가리는 사이 사감이 이쪽 줄에 섰다. 열쇠가 찰랑, 멈춘다.<br><br>얼굴이 이쪽으로 내려온다. 두 얼굴이 겹친 얼굴이다. 하나는 웃고 하나는 우는.<br>「하나.」 이쪽이 세어졌다. 우는 얼굴이 고개를 젓는다. 사감이 다음 줄로 갔다. 이쪽 가슴에 명찰 바늘 같은 것이 따끔하게 남았다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 숨을 죽이고 세는 소리가 지날 때까지 버틴다.', k:'steady', dc:22,
      ok:`몸을 관람석 의자 밑에 접어 넣었다. 숨을 아꼈다. 일행에게도 손짓했다.<br><br>열쇠 소리가 줄을 따라 온다. 이쪽 줄에서 멈칫한다. 그리고 끄는 걸음이 한 번 더 끈다. 세는 것을 놓친다.<br>사감이 지나갔다. 끄는 걸음이 이쪽을 한 번 돌아본 것 같았다. 의자 밑에서 나왔을 때 다리가 저려 한참 못 섰다.`,
      ng:`버티는데 일행 하나가 기침을 터뜨렸다. 물을 먹은 기침이다.<br><br>열쇠 소리가 뚝 멈춘다. 서두르는 걸음이 이쪽으로 온다. 끄는 걸음이 따라오지 못한다.<br>의자 밑에서 기어 나와 옆 통로로 달아났다. 등 뒤에서 찰랑찰랑 소리가 빨라졌다. 무대 밑까지 쫓겼다. 손바닥이 다 까졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 따라온 작은 손',
  x:`쉬는 자리에 앉자 옷자락이 당겨진다. 아래로. 보니 작은 손이 자락을 쥐고 있다.<br><br>
    아까 지나온 데서부터 따라왔다. 손만 있다. 손목 너머는 흐릿하다. 놓지 않는다.<br>
    해치지는 않는다. 그냥 쥐고 있다. 길 잃은 아이가 어른 옷자락을 쥐듯이.<br><br>
    다만 따라온 것은 밖까지 따라오려 한다. 밖에 데려가면 안 되는 것도 있다.`,
  o:[
    { l:'① 손이 어디서 왔는지 보고 그리로 보낸다.', k:'gaze', dc:22,
      ok:`손톱을 봤다. 물때가 끼었다. 손등에 분필 가루가 묻었다. 교실에 있던 손이다. 칠판 앞에 있던.<br><br>여기는 물에 잠긴 교실이 아니다. 이 손은 너무 멀리 왔다. 손을 감싸 쥐고 말했다. 「교실로 가라. 너희 반이 기다린다.」<br>손이 한참 쥐고 있다가 놓았다. 흐릿한 손목이 바닥을 따라 지나온 쪽으로 갔다. 옷자락에 젖은 손가락 자국이 남았다.`,
      ng:`보는데 손이 더 꼭 쥔다. 보낼 것을 안다. 손이 옷자락을 타고 올라온다. 이쪽 손목까지.<br><br>이쪽 손을 쥐었다. 차다. 놓지 않는다. 어른 손을 잡은 아이처럼 꽉.<br>밤새 그 손을 쥔 채로 쉬었다. 잠은 한숨도 못 잤다. 아침에 손이 저 혼자 놓고 갔다. 이쪽 손이 퍼렇게 얼어 있었다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 출구까지만 데려가 주기로 하고 쥐게 둔다.', k:'bond', dc:22,
      ok:`쥐게 두었다. 걸을 때마다 옷자락이 조금 당겨졌다. 어린아이 걸음만큼.<br><br>다음 층 계단 앞에서 손이 놓았다. 거기까지가 그 손이 갈 수 있는 데였다. 아무 말 없이 놓았다.<br>계단을 오르다 돌아봤다. 아래 어둠에서 작은 손이 한 번 흔들렸다. 잘 가라는 것인지 다시 오라는 것인지는 모른다.`,
      ng:`쥐게 두었는데 손이 하나 더 쥔다. 다른 손. 또 하나.<br><br>옷자락에 작은 손이 다섯이 매달렸다. 무겁다. 한 걸음마다 뒤로 당겨진다.<br>겉옷을 벗어 던졌다. 손들이 겉옷째 어둠으로 끌려갔다. 추위에 이가 딱딱 부딪혔다. 한참 걸어도 어깨가 시렸다.`,
      win:{ exp:18, dream:2, spirit:7 }, lose:{ hp:-22, mind:-20 } }
  ] }

]);

// ------------------------------------------
// 관상가 · 내공
// ------------------------------------------
kJob('physiog', 'A', [

{ at:'A', t:'복도 — 너무 오래 웃는 일행',
  x:`일행 하나가 웃고 있다. 아까부터다. 우스운 일은 없었다.<br><br>
    입꼬리가 귀 쪽으로 올라갔다. 이가 보인다. 웃음이 얼굴에서 내려오지 않는다. 말을 걸면 웃는 얼굴 그대로 대답한다.<br>
    본인은 웃는 줄 모른다. 볼이 좀 당긴다고만 한다.<br><br>
    웃음은 얼굴 가운데서 생긴다. 이 웃음은 가장자리에서 생겼다. 누가 양쪽에서 잡아당기는 것처럼.`,
  o:[
    { l:'① 웃음이 어디서 시작되는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`사람이 웃으면 눈가가 먼저 접힌다. 눈꼬리 아래 잔주름. 그다음 볼이 오르고 입이 따라간다.<br><br>이 얼굴은 눈가가 펴져 있다. 볼도 그대로다. 입꼬리만 귀 쪽으로 끌려 올라갔다. 웃음이 아니라 걸린 것이다. 입꼬리 끝에 보이지 않는 갈고리가 걸렸다.<br>엄지로 그 사람 입꼬리 끝을 눌러 안쪽으로 밀었다. 갈고리가 빠지는 감촉이 있었다. 얼굴이 제 얼굴로 돌아왔다. 그 사람이 한참 볼을 문질렀다.<br><br>얼굴은 순서로 읽는다. 어디가 먼저 움직였는지가 무엇이 움직였는지를 말한다. 표정 하나를 갈래갈래 나눠 보는 눈이 생겼다.`,
      ng:`읽으려 얼굴을 가까이 대는데 그 사람 웃음이 더 커진다. 이쪽을 보고.<br><br>이쪽 입꼬리가 저려 온다. 같이 올라간다. 웃음이 옮는다. 볼이 끌려 올라간다.<br>손으로 제 얼굴을 꽉 눌렀다. 한참 눌렀다. 손을 떼니 입가가 얼얼하다. 웃는 근육이 다 늘어난 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 내공을 써서 볼의 혈을 짚어 웃음을 푼다.', k:'heal', dc:22, cost:{ qi:28 },
      ok:`그 사람 양 볼 광대 아래를 손가락으로 짚었다. 내공을 가늘게 밀어 넣었다. 굳은 데가 있다. 사람 근육이 아닌 무엇이 웅크린 데.<br><br>내공으로 그것을 밀어냈다. 양쪽에서 동시에. 입꼬리가 툭 떨어졌다. 그 사람이 제 얼굴을 만져 보고 놀랐다.<br>이쪽 손가락 끝에 차가운 것이 묻었다. 털어 냈다. 바닥에 떨어진 것이 웃는 입 모양으로 잠깐 꿈틀했다.`,
      ng:`짚는데 굳은 데가 이쪽 내공을 문다. 손가락 끝에서 기운이 빨려 들어간다.<br><br>그 사람 웃음이 커진다. 이쪽 내공을 먹고. 입꼬리가 귀에 닿을 것 같다.<br>손을 뗐다. 손가락이 저렸다. 웃음은 한참 뒤에 저 혼자 내려왔다. 그 사람 볼에 손가락 자국이 붉게 남았다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-22, qi:-5 } },
    { l:'③ 왜 웃느냐고 묻는다.', k:'bond', dc:23,
      doom:{ title:'걸린 웃음', what:'웃는 것에게 입꼬리를 걸려 어둠으로 끌려갑니다', dc:18, sec:50,
        text:`「왜 웃어.」 물었다. 그 사람이 웃는 얼굴 그대로 이쪽을 본다.<br><br>「네가 웃으니까.」 대답한다. 이쪽 얼굴을 만져 보았다. 웃고 있다. 언제부터인지 모른다. 입꼬리가 귀 쪽으로 당겨진다.<br>당기는 것이 세진다. 입꼬리가 아니라 얼굴 전체를. 얼굴이 어둠 쪽으로 기운다. 몸이 따라간다.<br><br>끌려간다. 웃는 얼굴로. 어둠 속에서 무엇이 갈고리 둘을 쥐고 감아들인다.`,
        dieText:`그 일행의 웃음이 내려왔다. 저 혼자.<br><br>복도 저편 어둠에서 웃음소리가 났다. 오래. 같은 길이로.<br>그 뒤로 일행은 서로 얼굴을 보지 않고 걸었다. 웃는 얼굴을 보면 따라 웃게 될까 봐.` },
      ok:`묻기 전에 제 얼굴을 손으로 가렸다. 손바닥 너머로 물었다. 「왜 웃어.」<br><br>「네가 웃으니까.」 손바닥 밑 이쪽 얼굴은 웃지 않는다. 손으로 가린 얼굴은 웃음이 옮지 않는다.<br>그 사람이 멈칫한다. 웃음이 흔들린다. 손을 그 사람 눈앞에 대고 가려 주었다. 한참 뒤 손을 떼자 그 사람 얼굴에서 웃음이 미끄러져 내려갔다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A1', t:'로비 — 텔레비전 속 그려 넣은 얼굴',
  x:`로비 텔레비전에 노란 해 얼굴이 가득하다. 방글이다. 그려 넣은 눈과 입이 움직인다.<br><br>
    그린 얼굴에도 상이 있다. 그린 사람 손이 그 얼굴에 남는다. 눈을 어디에 찍었는지, 입꼬리를 얼마나 올렸는지.<br>
    눈동자가 조금 위, 조금 왼쪽에 찍혔다. 정면을 보는 얼굴이 아니다.<br><br>
    입 모양이 말한다. 친구들, 어서 와.`,
  o:[
    { l:'① 그린 얼굴이 정말 어디를 보는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`그린 눈은 그린 사람이 보던 데를 본다. 위 왼쪽. 로비 천장 구석이다.<br><br>고개를 들지 않고 텔레비전 화면 유리에 비친 천장을 봤다. 구석에 무엇이 붙어 있다. 거꾸로. 팔다리가 길다. 방글이는 이쪽을 보는 게 아니라 그것을 본다. 그것에게 손님을 알려 준다.<br>천장 구석 바로 밑을 피해 벽을 따라 돌았다. 화면 속 눈동자가 천천히 이쪽을 따라 내려왔다. 그린 눈이 움직일 수 있다는 걸 그때 알았다.<br><br>그려진 얼굴도 얼굴이다. 그린 손의 버릇이 상으로 남는다. 사람 아닌 얼굴에서 눈길이 가리키는 곳을 읽는 법이 생겼다.`,
      ng:`어디를 보는지 오래 보는 사이 그린 눈동자가 이쪽으로 옮겨 왔다. 위 왼쪽에서 가운데로.<br><br>입 모양이 바뀐다. 친구 하나 찾았다.<br>천장 쪽에서 무엇이 떨어지는 소리가 났다. 돌아보지 않고 뛰었다. 로비 의자에 정강이를 찧었다. 접수처 뒤에 숨었을 때 텔레비전이 꺼져 있었다. 그게 더 무서웠다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 그린 눈과 마주치지 않게 고개를 숙이고 지난다.', k:'steady', dc:22,
      ok:`고개를 숙였다. 발끝만 보고 걸었다. 그린 얼굴은 마주 봐야 상대가 된다.<br><br>화면 쪽에서 입 모양 바뀌는 기척이 느껴진다. 보지 않았다. 일행에게도 고개를 들지 말라고 했다.<br>로비를 다 지날 때까지 목덜미가 화끈거렸다. 천장 구석 쪽에서 무엇이 기어가는 소리가 한 번 났다. 이쪽 반대로.`,
      ng:`숙이고 걷는데 바닥 타일이 반들거린다. 텔레비전이 비친다. 그린 눈이 바닥에서 이쪽을 올려다본다.<br><br>눈이 마주쳤다. 바닥에서.<br>그대로 굳었다. 일행이 팔을 끌어 겨우 지났다. 그 뒤로 반들거리는 바닥만 보면 그 눈이 떠올랐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'복도 — 학급 단체 사진',
  x:`복도 벽에 학급 단체 사진이 걸렸다. 액자 유리 안쪽까지 물방울이 맺혔다. 서른 얼굴이 세 줄로 섰다.<br><br>
    얼굴마다 상이 보인다. 귀가 얇고 인중이 짧다. 서른이 다 같다. 한날한시에 간 상이다.<br>
    맨 뒷줄 끝에 한 얼굴만 상이 다르다. 사진 종이도 다르다. 새것이다. 오려 붙였다.<br><br>
    그 얼굴은 이쪽 얼굴이다.`,
  o:[
    { l:'① 붙인 얼굴의 상을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`이쪽 얼굴이니 이쪽이 제일 잘 안다. 그런데 사진 속 얼굴은 조금 다르다. 인당이 검다. 귀가 하얗다. 인중이 짧아졌다. 서른 얼굴과 같은 상이 되어 가는 중이다.<br><br>사진은 상을 맞춘다. 서른하나째를 서른과 같게. 다 같아지면 사진이 맞는다.<br>손톱으로 사진 속 이쪽 얼굴 인당에 작은 흠을 냈다. 흠 난 상은 같아지지 않는다. 사진 속 이쪽 얼굴이 흐려졌다. 서른과 끝내 맞지 않는 얼굴로.<br><br>상은 타고나는 것이 아니라 맞춰 가는 것이기도 하다. 남이 이쪽 상을 무엇에 맞추려 하는지 보이는 눈이 생겼다. 맞춰지기 전에 흠을 낸다.`,
      ng:`읽는 사이 사진 속 이쪽 귀가 더 하얘진다. 이쪽 귀가 차가워진다. 실제로.<br><br>귀를 만져 보았다. 얼음장이다. 인중이 근질거린다. 짧아지는 느낌이다.<br>액자를 벽에서 떼어 엎었다. 귀가 한참 뒤에야 녹았다. 거울을 볼 엄두가 나지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 붙인 얼굴을 손톱으로 떼어 낸다.', k:'luck', dc:23,
      doom:{ title:'단체 사진', what:'사진 속 맨 뒷줄로 빨려 들어갑니다', dc:18, sec:45,
        text:`액자 유리를 열고 손톱으로 오려 붙인 얼굴 귀퉁이를 들었다. 붙어 있다. 풀이 아니다. 물이다.<br><br>떼어 낼수록 이쪽 얼굴 살갗이 당긴다. 이마가, 볼이. 사진 쪽으로.<br>서른 얼굴이 일제히 이쪽을 본다. 웃는다. 사진 속 맨 뒷줄 끝자리가 비어 있다. 거기 설 사람이 와 있다.<br><br>사진 속으로 빨려 들어간다. 얼굴부터. 물 냄새 나는 종이 속으로. 뒤에서 누가 셔터를 누른다. 찰칵.`,
        dieText:`액자 유리에 물방울이 다시 맺혔다.<br><br>사진 속 맨 뒷줄 끝에 한 얼굴이 섰다. 이제 오려 붙인 자국이 없다. 종이도 같다.<br>상도 같다. 귀가 얇고 인중이 짧다. 서른하나가 다 같다.` },
      ok:`떼어 내기 전에 사진 속 이쪽 얼굴 위에 젖은 손가락으로 선을 하나 그었다. 얼굴을 가르는 선. 갈린 얼굴은 한 사람 상이 아니다.<br><br>그다음 손톱으로 귀퉁이를 들었다. 이번엔 얼굴이 당기지 않는다. 사진 속 얼굴이 이쪽 얼굴이 아니게 됐으니까.<br>떼어 낸 조각을 구겨 물에 던졌다. 서른 얼굴이 그대로 서 있다. 맨 뒷줄 끝이 비었다. 오래 비어 있을 것이다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 내공을 써서 사진 속 서른의 기색을 짚는다.', k:'gaze', dc:22, cost:{ qi:29 },
      ok:`액자 유리에 손바닥을 대고 내공을 눈으로 끌어올렸다. 사진 속 얼굴 기색이 보인다. 서른이 다 같은 색이다. 물빛이다.<br><br>그 가운데 하나만 기색이 흔들린다. 둘째 줄 가운데. 다른 얼굴들보다 조금 밝다. 아직 다 가지 않았다. 이쪽을 보고 입술을 움직인다. 「뒤.」<br>돌아보지 않고 옆으로 비켰다. 등 뒤 물에서 무엇이 첨벙 덮쳤다가 빗나갔다. 사진 속 그 얼굴의 기색이 조금 더 밝아졌다.`,
      ng:`내공을 끌어올리는데 서른의 기색이 한꺼번에 눈으로 밀려든다. 물빛. 차다. 숨이 막힌다.<br><br>눈 안쪽이 얼어붙는 것 같다. 눈물이 났다. 물이었다.<br>손을 떼고 주저앉았다. 한참 앞이 흐렸다. 기색을 너무 많이 받으면 이쪽 기색도 물빛이 된다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24, qi:-5 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잠든 얼굴들',
  x:`일행이 잠들었다. 이쪽이 불침번이다. 등불을 낮춰 얼굴들을 본다.<br><br>
    잠든 얼굴은 감추지 못한다. 깨어 있을 때 숨긴 기색이 다 올라온다.<br>
    넷은 피곤한 얼굴이다. 하나는 다르다. 산근, 콧대가 시작하는 자리가 검게 내려앉았다. 잠들기 전에는 없었다.<br><br>
    그 사람 얼굴이 아주 조금 어둠 쪽으로 돌아가 있다. 자면서 무엇을 듣는 얼굴이다.`,
  o:[
    { l:'① 내공을 써서 산근의 그늘이 어디서 오는지 짚는다.', k:'gaze', dc:22, cost:{ qi:27 }, wake:1,
      ok:`눈에 내공을 모아 그늘을 봤다. 그늘은 가만있지 않는다. 가는 줄이 되어 어둠 쪽으로 이어진다. 그 끝에서 무엇이 그늘을 빨대처럼 빨아들인다. 그 사람의 기를.<br><br>줄은 얼굴이 향한 쪽으로 나 있다. 그 사람 머리를 손으로 감싸 반대쪽으로 돌려 눕혔다. 줄이 휘다가 끊겼다. 어둠 저편에서 무엇이 입맛을 다시는 소리가 났다.<br>산근의 그늘이 조금씩 옅어졌다. 새벽녘엔 그냥 피곤한 얼굴이었다.<br><br>그늘은 상이 아니라 흐름이다. 얼굴에 내려앉은 것이 어디서 왔고 어디로 가는지까지 따라가 보는 눈이 생겼다. 얼굴이 길을 가리킨다.`,
      ng:`그늘을 짚는 순간 그늘이 이쪽 눈으로 옮겨 온다. 내공을 타고.<br><br>눈앞이 컴컴해졌다. 한쪽 눈이 안 보인다. 그 사람 그늘은 그대로다. 이쪽에도 하나 생겼다.<br>새벽까지 한쪽 눈으로 불침번을 섰다. 아침에 시야가 돌아왔다. 거울을 보니 이쪽 산근이 조금 검다.`,
      win:{ exp:23, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-26, qi:-5 } },
    { l:'② 그 사람을 깨워 자리를 바꿔 앉는다.', k:'bond', dc:22,
      ok:`어깨를 짚어 깨웠다. 잠이 덜 깬 얼굴이다. 아무 말 없이 이쪽 자리와 바꿨다. 등불 바로 옆, 어둠에서 제일 먼 자리로.<br><br>그 사람이 다시 잠들었다. 얼굴이 등불 쪽을 향한다. 산근의 그늘이 등불 빛에 녹듯이 흐려진다.<br>이쪽은 어둠에 가까운 자리에 앉았다. 밤새 무엇이 이쪽 얼굴을 살피는 기척이 났다. 깨어 있는 얼굴은 빨기 어렵다.`,
      ng:`깨우는데 안 깬다. 얼굴이 어둠 쪽으로 더 돌아간다.<br><br>흔들자 눈을 뜬다. 이쪽을 안 본다. 어둠을 본다. 「누가 불렀어.」<br>그 사람을 붙들고 밤을 새웠다. 몇 번이나 일어나 걸어가려 했다. 그때마다 붙잡았다. 팔에 할퀸 자국이 났다. 그 사람은 아침에 아무것도 기억하지 못했다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'계단 — 거꾸로 내려다보는 얼굴',
  x:`계단을 내려가다 위를 봤다. 난간 사이 빈 틈 꼭대기에 얼굴 하나가 있다. 거꾸로. 이쪽을 내려다본다.<br><br>
    거꾸로 된 얼굴은 읽기 어렵다. 이마가 아래고 턱이 위다. 웃는지 우는지 모른다. 입꼬리가 올라갔으면 거꾸로는 내려간 것이다.<br>
    얼굴이 한 층씩 따라 내려온다. 이쪽이 내려가는 만큼.<br><br>
    읽어야 무엇인지 안다. 읽으려면 바로 봐야 한다.`,
  o:[
    { l:'① 고개를 거꾸로 꺾어 얼굴을 바로 읽는다.', k:'gaze', dc:23,
      doom:{ title:'거꾸로', what:'난간 사이로 계단 위까지 끌려 올라갑니다', dc:18, sec:50,
        text:`난간에 기대 고개를 뒤로 꺾었다. 거꾸로 된 얼굴이 바로 보인다. 웃는다. 이를 다 드러내고.<br><br>그 얼굴이 이쪽 얼굴을 바로 본다. 이쪽도 지금 거꾸로다. 둘이 서로 바로 본다. 눈이 맞는다.<br>얼굴 밑으로 팔이 내려온다. 난간 사이 빈 틈으로. 길다. 손가락이 이쪽 꺾인 목을 감는다.<br><br>끌려 올라간다. 난간 사이로. 거꾸로 매달려. 계단이 아래로 멀어진다. 웃는 얼굴이 가까워진다.`,
        dieText:`계단 꼭대기에서 얼굴 하나가 내려다본다. 거꾸로.<br><br>둘이다. 하나는 이를 드러내고 웃는다. 하나는 입을 벌리고 있다. 무슨 말을 하려는 듯이.<br>거꾸로 된 얼굴은 웃는지 우는지 모른다.` },
      ok:`고개를 꺾지 않았다. 품에서 깨진 거울 조각을 꺼내 위로 비스듬히 들었다. 거울에 비친 얼굴은 한 번 더 뒤집힌다. 바로 보인다.<br><br>웃는 얼굴이다. 눈꼬리가 내려가고 입꼬리만 올라간 웃음. 반가워서 웃는 얼굴이 아니다. 기다리던 것이 와서 웃는 얼굴이다.<br>거울을 내리고 다시는 위를 보지 않았다. 계단을 두 칸씩 내려갔다. 얼굴이 따라 내려오다 어느 층에서 멈췄다. 보지 않으면 따라올 수 없는 데까지.`,
      win:{ exp:24, dream:4 } },
    { l:'② 위를 보지 않고 벽 쪽으로 붙어 내려간다.', k:'steady', dc:22,
      ok:`난간 쪽을 버리고 벽 쪽으로 붙었다. 난간 틈 위에서는 벽 쪽이 안 보인다.<br><br>일행도 벽을 타고 내려왔다. 위에서 얼굴이 이쪽을 찾는 기척이 난다. 난간 너머로 숨소리가 내려온다.<br>바닥까지 내려왔다. 아무도 위를 안 봤다. 마지막 계단에서 위쪽 어딘가 난간이 삐걱 울었다. 무엇이 더 몸을 내민 것처럼.`,
      ng:`벽 쪽으로 붙었는데 벽에도 틈이 있다. 환기구다. 거기서 거꾸로 된 얼굴이 이쪽을 본다. 아주 가까이.<br><br>눈이 마주쳤다. 바로가 아니라 거꾸로. 그래서 무슨 얼굴인지 모른다. 모르는 얼굴이 제일 무섭다.<br>뒷걸음질 치다 계단을 헛디뎌 몇 칸을 굴렀다. 팔꿈치가 다 까졌다. 환기구 쪽에서 웃음인지 울음인지 모를 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A1', t:'방청석 — 바람잡이의 사진 얼굴',
  x:`방청석 가운데 통로에 바람잡이가 서 있다. 줄무늬 셔츠. 손에 마이크. 얼굴 자리에 사진이 붙어 있다. 웃는 남자 사진.<br><br>
    사진도 얼굴이다. 찍힌 사람의 상이 남는다. 오려 붙인 테두리가 들떴다.<br>
    웃고 있다. 이를 보이고. 방송용 웃음이다. 사진 속 남자는 이 웃음을 수천 번 지었다.<br><br>
    자, 오늘 친구들 목소리 한번 들어 볼까요! 사진 얼굴이 방청석을 훑는다.`,
  o:[
    { l:'① 사진 속 남자의 상을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`웃음은 입이 한다. 상은 눈이 한다. 사진 속 남자의 눈 밑이 검다. 흰자가 위로 조금 보인다. 겁에 질린 사람 눈이다. 사진을 찍던 그날도.<br><br>바람잡이는 사진 속 남자가 아니다. 남자 얼굴을 빌려 쓰는 것이다. 남자는 그 사진 안에 갇혀 매일 웃는다. 그래서 이쪽을 볼 때마다 눈이 떨린다. 오지 말라고.<br>사진 속 눈이 떨리는 쪽을 봤다. 오른쪽 출구다. 남자가 이쪽을 볼 때마다 눈동자가 그쪽으로 미끄러진다. 그 출구로 빠져나왔다. 등 뒤에서 마이크가 다른 쪽을 가리켰다.<br><br>웃는 얼굴에서 웃음을 걷어 내고 남은 눈을 읽는다. 표정에 가려진 상이 먼저 보이게 됐다. 가면 밑 맨얼굴을 찾는 눈이다.`,
      ng:`읽으려 사진을 오래 봤다. 사진 속 눈이 이쪽과 마주쳤다. 떨린다.<br><br>바람잡이가 그걸 알았다. 저기 눈이 반짝이는 친구! 마이크가 이쪽을 가리킨다. 스피커에서 박수가 터진다.<br>의자 등받이를 붙들고 버텼다. 보이지 않는 손들이 몸을 들어 올리려 한다. 박수가 멎을 때까지 손가락이 하얗게 질리도록 쥐고 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 의자 사이에 몸을 낮춰 얼굴을 가린다.', k:'hide', dc:22,
      ok:`의자 등받이 뒤로 몸을 낮췄다. 얼굴을 무릎에 묻었다. 사진 얼굴은 얼굴을 찾는다. 얼굴이 안 보이면 고를 게 없다.<br><br>마이크 소리가 머리 위를 지나간다. 앞으로 나와 볼 친구? 대답이 없다. 다들 얼굴을 묻었다.<br>바람잡이가 무대 쪽으로 내려갔다. 그제야 고개를 들었다. 이마에 등받이 자국이 났다.`,
      ng:`몸을 낮췄는데 의자 아래 틈으로 사진 얼굴이 보인다. 통로 바닥에 바람잡이가 엎드려 있다. 의자 밑을 들여다보고 있다. 웃으며.<br><br>숨은 친구 찾았다! 박수가 터진다.<br>의자 밑에서 다른 줄로 기어 나갔다. 무릎과 손바닥이 다 까졌다. 바람잡이가 일어나 천천히 따라왔다. 출구까지.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'③ 사진 얼굴에 마주 웃어 준다.', k:'bond', dc:23,
      doom:{ title:'앞으로 나와 볼 친구', what:'방청석 위로 손에서 손으로 실려 갑니다', dc:18, sec:50,
        text:`사진 얼굴과 눈이 마주쳤다. 마주 웃었다. 같은 웃음으로. 입만.<br><br>바람잡이가 반가워한다. 웃는 친구! 마이크가 이쪽을 가리킨다. 웃는 얼굴은 무대에 어울린다.<br>몸이 들린다. 보이지 않는 손들이 등을, 다리를 받친다. 손에서 손으로 넘어간다. 웃는 얼굴이 내려오지 않는다. 사진 속 남자처럼.<br><br>실려 간다. 무대 쪽으로. 몸 밑에서 박수가 끊이지 않는다.`,
        dieText:`바람잡이가 통로에 다시 섰다.<br><br>얼굴 자리에 사진이 두 장 겹쳐 붙어 있다. 위의 것이 새것이다. 웃는다. 이를 보이고.<br>눈 밑이 검다. 흰자가 위로 조금 보인다.` },
      ok:`마주 웃었다. 입은 웃고 눈은 사진 속 남자의 눈을 봤다. 겁먹은 눈. 그 눈에게만 고개를 끄덕였다. 안다고.<br><br>사진 속 눈이 한 번 깜빡였다. 사진이 깜빡일 리 없다. 바람잡이 마이크가 이쪽을 가리키려다 멈춘다. 얼굴이 제 말을 안 듣는다.<br>그사이 출구 쪽으로 빠졌다. 등 뒤에서 마이크가 헛소리를 했다. 사진 테두리가 조금 더 들떠 있었다.`,
      win:{ exp:24, dream:4, spirit:6 } }
  ] },

{ at:'A2', t:'기숙사 — 학생증 사진',
  x:`사물함 문 안쪽마다 학생증이 붙어 있다. 사진, 이름, 반. 사진 속 아이들이 다 정면을 본다. 사진기를.<br><br>
    한 장만 다르다. 사진 속 아이 눈이 옆으로 비껴 있다. 사진기 옆을 본다. 찍을 때 사진사 옆에 무엇이 있었다.<br>
    눈이 놀라 있다. 눈썹이 위로 몰렸다.<br><br>
    그 사물함이 이쪽 앞에 있다. 안쪽에서 물이 똑똑 떨어진다.`,
  o:[
    { l:'① 사진 속 눈이 본 것을 그 얼굴로 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`놀란 눈썹은 위로 몰린다. 무서운 눈썹은 가운데로 몰린다. 이 아이는 놀랐지 무서워하지 않았다. 아는 사람을 봤다.<br><br>눈이 향한 높이가 낮다. 키가 작은 사람. 사감이 아니다. 사감은 키가 크다. 아이 또래다. 찍던 날 사진사 옆에 아이가 하나 서 있었다. 아이들 사이에 처음부터 하나가 더 있었다.<br>그날부터 아이들 무리를 셀 때 눈높이 아래를 한 번 더 봤다. 다음 호실에서 침대 밑 그림자 하나가 그 눈길을 피해 움츠렸다.<br><br>얼굴은 그 얼굴이 본 것도 담는다. 눈썹 하나에서 그날 그 자리에 있던 것까지 읽어 내는 눈이 생겼다. 사진은 찍힌 사람만 찍지 않는다.`,
      ng:`읽는 사이 사진 속 눈이 옮겨 온다. 사진기 옆에서 이쪽 옆으로. 이쪽 어깨 너머를 본다.<br><br>어깨 너머에 무엇이 있다. 눈썹이 위로 몰린 그 얼굴처럼 이쪽 눈썹도 저절로 몰린다.<br>돌아보지 않았다. 사물함 문을 닫았다. 문 안쪽에서 손톱으로 두드리는 소리가 났다. 어깨가 오래 차가웠다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 내공을 써서 사물함 안에 남은 기운을 짚는다.', k:'sense', dc:22, cost:{ qi:28 },
      ok:`사물함 문짝에 손바닥을 대고 내공을 흘려 넣었다. 안에 남은 기운이 손에 걸린다. 오래된 아이 기운. 그리고 그것보다 새것인 차고 끈적한 기운.<br><br>새 기운은 사물함 아래 칸에서 난다. 문을 열지 않았다. 아래 칸 틈에 소금을 밀어 넣었다. 끈적한 기운이 움츠렸다.<br>위 칸 문을 조금 열었다. 아이 기운이 남은 데. 말린 고기 한 줄이 기름종이에 싸여 있다. 집에서 보내 준 것이다. 고맙다는 기색이 손끝에 스쳤다.`,
      ng:`내공을 흘려 넣는 순간 끈적한 기운이 이쪽 손바닥을 문다. 문짝을 통과해.<br><br>손바닥에서 기운이 빨려 들어간다. 사물함 안쪽에서 무엇이 배부르게 꿈틀거린다.<br>손을 떼어 냈다. 손바닥이 하얗게 질렸다. 사물함 문짝에 이쪽 손바닥 자국이 물기로 남았다. 안 마른다.`,
      win:{ exp:20, dream:2, item:'말린 고기' }, lose:{ hp:-24, spirit:-22, qi:-5 } }
  ] },

{ at:'A', t:'거울 — 너무 좋은 상',
  x:`복도 거울에 이쪽 얼굴이 비친다. 오랜만에 보는 제 얼굴이다.<br><br>
    좋은 상이다. 너무 좋다. 인당이 맑고 귀가 두툼하다. 법령이 길게 내려와 턱을 감쌌다. 오래 살 상이다.<br>
    이쪽 얼굴이 이랬던 적은 없다. 지금은 더더욱. 지치고 할퀴었다.<br><br>
    거울 속 좋은 상이 이쪽을 보고 조금 웃는다. 이쪽은 웃지 않았다.`,
  o:[
    { l:'① 거울 속 상이 누구 것인지 읽는다.', k:'gaze', dc:22,
      ok:`좋은 상만 보면 안 된다. 좋은 상 안에 어긋난 데를 찾았다. 귀. 귓불이 두툼한데 귓바퀴 위쪽이 뾰족하다. 사람 귀가 아니다.<br><br>남의 좋은 상을 입고 이쪽을 꾄다. 이리 오면 이 얼굴이 네 것이 된다고. 바꾸자는 것이다. 지친 얼굴과 좋은 얼굴을.<br>거울에 대고 제 할퀸 볼을 일부러 손으로 짚어 보였다. 이게 이쪽 얼굴이다. 거울 속 웃음이 굳었다. 좋은 상이 조금 일그러졌다.`,
      ng:`읽다 보니 좋은 상이 마음에 든다. 그 얼굴로 살면 덜 무서울 것 같다.<br><br>손이 거울 쪽으로 간다. 거울 표면에 손끝이 닿는다. 차지 않다. 따뜻하다.<br>일행이 손목을 쳤다. 손끝을 보니 지문이 반쯤 지워져 있다. 거울 속 손끝에 이쪽 지문이 찍혀 있었다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 거울을 깨 버린다.', k:'break', dc:22,
      ok:`등불 자루로 거울 한가운데를 쳤다. 금이 갔다. 좋은 상이 조각조각 갈렸다.<br><br>조각마다 다른 얼굴이 비친다. 다 좋은 상이다. 다 남의 것이다. 이쪽 얼굴은 하나도 없다.<br>그 조각들을 밟지 않고 지났다. 다음 물웅덩이에 비친 얼굴은 할퀴고 지친 이쪽 얼굴이었다. 반가웠다.`,
      ng:`쳤는데 거울이 깨지는 대신 이쪽 얼굴이 아프다. 볼이, 이마가.<br><br>거울에 금이 간 자리마다 이쪽 얼굴에 가는 생채기가 났다. 피가 맺힌다. 거울 속 좋은 상은 멀쩡하다.<br>손을 거두었다. 생채기는 오래 안 아물었다. 거울 속 얼굴은 끝까지 웃었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'A', t:'복도 — 앞서 걷는 뒷모습',
  x:`복도 앞에 누가 걸어간다. 등을 보이고. 일행이 아니다. 일행은 다 뒤에 있다.<br><br>
    같은 속도로 걷는다. 이쪽이 빨리 가면 빨리, 천천히 가면 천천히. 거리가 늘 그대로다.<br>
    얼굴은 안 보인다. 그래도 사람은 뒷모습에도 상이 있다. 귀, 목덜미, 어깨의 기울기.<br><br>
    뒷목에 머리카락이 한 올도 없다. 귀가 너무 높다.`,
  o:[
    { l:'① 뒷모습만으로 무엇인지 읽는다.', k:'gaze', dc:22,
      ok:`귀가 높으면 목이 길다. 목이 길어 보이는 게 아니라 실제로 길다. 어깨가 앞으로 말렸다. 무거운 것을 앞에 안고 걷는 어깨다.<br><br>앞에 안은 것은 얼굴이다. 얼굴을 앞으로 가슴에 안고 걷는다. 뒷모습만 보이게. 얼굴을 보는 사람의 얼굴을 바꾸려고.<br>걸음을 멈췄다. 그것도 멈췄다. 일행과 함께 옆 통로로 빠졌다. 등 뒤에서 무엇이 아주 천천히 돌아서는 소리가 났다. 보지 않았다.`,
      ng:`읽는 사이 거리가 줄었다. 이쪽이 빨라진 게 아니다. 저쪽이 뒷걸음질 친다.<br><br>등이 다가온다. 뒷목이 눈앞에 온다. 매끄럽다. 땀구멍이 없다.<br>뒤로 넘어지며 물러났다. 일행이 끌어당겼다. 그 등은 이쪽 코앞에서 멈춰 섰다. 한참을 그렇게 섰다가 다시 앞으로 걸어갔다. 같은 속도로.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 빨리 걸어 앞질러 얼굴을 본다.', k:'sense', dc:23,
      doom:{ title:'앞모습', what:'얼굴을 안은 것에게 붙들려 끌려갑니다', dc:18, sec:50,
        text:`걸음을 빨리했다. 거리가 그대로다. 뛰었다. 그제야 줄어든다. 어깨 옆을 지나 앞으로 나섰다.<br><br>돌아봤다. 얼굴이 없다. 얼굴 자리가 매끈하다. 두 팔이 가슴에 무엇을 안았다. 얼굴이다. 이쪽을 보고 있다.<br>안긴 얼굴이 웃는다. 팔이 풀린다. 그 얼굴을 이쪽에게 내민다. 이쪽 얼굴 자리에.<br><br>긴 팔이 이쪽 머리를 감싼다. 끌어안는다. 끌려간다. 복도 끝 어둠으로. 얼굴과 얼굴이 맞닿은 채로.`,
        dieText:`복도 앞에 누가 걸어간다. 등을 보이고.<br><br>목덜미에 머리카락이 있다. 이쪽 머리 색이다. 귀 높이도 맞다.<br>뒤에서 보면 이쪽이다. 앞에서 보면 무엇인지 아무도 보러 가지 않았다.` },
      ok:`앞지르지 않았다. 앞질러 얼굴을 보면 그 얼굴과 마주한다. 대신 걸음을 빨리해 거리를 조금만 좁히고 귀 옆을 비스듬히 봤다.<br><br>가슴께에 무엇을 안았다. 둥글다. 얼굴이다. 그것이 안은 얼굴의 눈이 팔 사이로 이쪽을 봤다. 앞에서 보는 얼굴이 아니라 옆에서 엿보는 얼굴이다.<br>걸음을 늦췄다. 거리가 다시 벌어졌다. 그것을 앞에 두고 갈림길에서 반대로 갔다. 안긴 얼굴이 아쉬운 눈으로 팔 사이에서 따라왔다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 내공을 써서 뒷모습의 기가 어디로 흐르는지 짚는다.', k:'gaze', dc:22, cost:{ qi:30 }, wake:1,
      ok:`눈에 내공을 모았다. 사람 기는 머리에서 발로 흐른다. 걸어가는 사람은 기가 앞으로 쏠린다.<br><br>저것은 기가 뒤로 쏠린다. 이쪽으로. 뒷모습이 앞이다. 저것은 처음부터 이쪽을 향해 걷고 있다. 등이 얼굴이다. 뒤로 걸으며 거리를 재고 있었다.<br>이쪽이 멈추자 저것도 멈췄다. 일행을 데리고 천천히 뒷걸음질 쳤다. 저것을 보면서. 저것은 이쪽 걸음에 맞춰 같은 만큼 다가왔다. 갈림길에서 옆으로 빠지자 따라오지 못했다. 등으로는 꺾을 수 없다.<br><br>상은 생김새만이 아니다. 몸에 흐르는 기가 앞과 뒤를 말해 준다. 생김새를 믿지 않고 흐름으로 읽는 눈이 생겼다.`,
      ng:`내공을 모으는데 저것의 기가 이쪽 기를 끌어당긴다. 뒤로 쏠린 기가 이쪽을 감아 들인다.<br><br>발이 저절로 앞으로 간다. 저것 등 쪽으로. 등이 얼굴처럼 이쪽을 맞는다.<br>내공을 끊었다. 그 반동에 피를 한 모금 토했다. 일행이 부축했다. 저것은 그 자리에 서서 이쪽이 사라질 때까지 등을 보였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-20, qi:-5 } }
  ] },

{ at:'A1', t:'분장실 — 웃는 화장',
  x:`분장실 전구 거울 앞에 앉았다. 앉으려던 게 아니다. 의자가 다리 뒤에 와 있었다.<br><br>
    거울 속에서 보이지 않는 손이 이쪽 얼굴에 분을 바른다. 볼에 붉은 동그라미. 입가에 웃는 선.<br>
    화장은 상을 바꾼다. 무대 화장은 멀리서 보면 웃는 얼굴로 보이게 그린다. 가까이서 보면 다른 얼굴이다.<br><br>
    붓이 입꼬리 끝에서 귀 쪽으로 선을 긋기 시작한다.`,
  o:[
    { l:'① 그려지는 상을 거울로 끝까지 읽는다.', k:'gaze', dc:22,
      ok:`선이 그어지는 대로 읽었다. 볼의 동그라미는 복이 드는 자리다. 입가 선은 웃음이 드는 자리다. 무대에 서는 사람 상이다.<br><br>마지막 선이 귀로 간다. 귀는 듣는 자리다. 거기까지 선이 닿으면 부르는 말을 다 듣게 된다. 그 선이 닿기 전에 손등으로 문질러 끊었다.<br>붓이 멈췄다. 끊긴 선은 상이 아니다. 의자에서 일어섰다. 거울 속 얼굴은 반쯤 웃는 얼굴이다. 반쯤은 이쪽 얼굴이다.`,
      ng:`읽는 사이 선이 귀에 닿았다. 순간 귀가 트인다. 멀리 무대 쪽 소리가 다 들린다.<br><br>언니 목소리. 친구야, 이리 와. 귓속에서 바로 들린다. 몸이 의자에서 일어서 무대 쪽으로 간다.<br>문틀을 붙잡았다. 손톱이 들렸다. 귀에서 소리가 빠질 때까지 버텼다. 귀 안쪽이 한참 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 눈을 감고 숨을 고르며 붓을 견딘다.', k:'steady', dc:22,
      ok:`눈을 감았다. 거울을 안 보면 상이 그려지는 걸 모른다. 모르는 상은 정해지지 않는다.<br><br>붓이 얼굴을 지나간다. 차다. 숨을 고르게 쉬었다. 붓이 멈칫한다. 표정 없는 얼굴에는 화장이 안 먹는다. 웃는 선은 웃는 얼굴 위에서 산다.<br>한참 뒤 붓이 떨어졌다. 눈을 떴다. 거울 속 얼굴이 하얗게 분만 발려 있다. 아무 상도 없는 얼굴. 수건으로 닦아 냈다.`,
      ng:`눈을 감았는데 붓이 눈꺼풀 위에 눈을 그린다. 감은 눈 위에 뜬 눈을.<br><br>눈꺼풀이 저려 온다. 감은 채로 거울이 보인다. 그려진 눈으로. 거울 속 이쪽이 웃고 있다.<br>눈을 번쩍 떴다. 수건으로 박박 닦았다. 눈꺼풀이 쓸려 벌겋다. 그 뒤로 잠깐씩 눈을 감아도 앞이 보였다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'수영장 — 물 밑에서 올려다보는 얼굴',
  x:`수영장 가장자리를 따라 걷는다. 물이 맑다. 바닥까지 보인다.<br><br>
    바닥에 얼굴들이 있다. 위를 보고 누웠다. 수십이다. 눈을 뜨고 수면을 올려다본다.<br>
    얼굴은 다 같은 쪽을 본다. 수면 위 한 점. 이쪽이 지날 때마다 그 한 점이 이쪽을 따라온다.<br><br>
    얼굴을 읽으면 무엇을 기다리는지 안다. 읽으려면 물을 들여다봐야 한다.`,
  o:[
    { l:'① 가장자리에 엎드려 물 밑 얼굴들을 읽는다.', k:'gaze', dc:23,
      doom:{ title:'수면', what:'물 밑 얼굴들에게 물속으로 끌려 들어갑니다', dc:18, sec:45,
        text:`가장자리에 엎드려 물을 들여다봤다. 얼굴 하나하나가 또렷하다. 다들 입을 조금 벌렸다. 숨을 기다리는 입이다.<br><br>한 얼굴이 이쪽 얼굴이다. 바닥에 누워 이쪽을 올려다본다. 이쪽이 들여다보는 만큼 그 얼굴이 떠오른다. 수면 가까이. 더 가까이.<br>수면이 이쪽 코끝에 닿는다. 물속 얼굴과 이쪽 얼굴이 수면을 사이에 두고 맞닿는다. 물속에서 손들이 올라와 뒷머리를 감싼다.<br><br>끌려 들어간다. 얼굴부터. 바닥 쪽으로. 위를 보는 얼굴들 사이에 자리가 하나 있다.`,
        dieText:`수면이 잔잔해졌다.<br><br>바닥에 얼굴이 하나 늘었다. 위를 보고 누웠다. 눈을 뜨고.<br>다음에 가장자리를 지나는 사람이 있으면 그 얼굴도 같이 그 사람을 따라 눈을 굴릴 것이다.` },
      ok:`엎드리지 않았다. 서서 물을 비스듬히 봤다. 수면에 천장이 비친다. 그 사이로 얼굴들이 보인다. 비스듬히 보면 얼굴들과 눈이 안 맞는다.<br><br>입을 조금 벌렸다. 다들. 숨을 기다리는 입이다. 해치려는 얼굴이 아니다. 물 밖으로 나가고 싶은 얼굴이다. 그런데 나가려면 다른 누가 들어와야 한다.<br>가장자리에서 한 걸음 물러나 걸었다. 물 밑 눈들이 실망한 듯 천천히 감겼다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 물에 비친 천장 쪽으로 얼굴들을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`물 밑을 보지 않았다. 수면에 비친 것을 봤다. 수면은 거울이다. 거울로 보면 물 밑 얼굴과 눈이 바로 맞지 않는다.<br><br>비친 천장에 얼굴들이 보인다. 물 밑 얼굴들 위로 겹쳐서. 표정이 수면에 비치면 반쯤 흐려진다. 흐린 데 남는 것만 읽었다. 눈썹. 다들 눈썹 끝이 처졌다. 지쳤다. 기다리는 데 지쳤다.<br>지친 얼굴은 급하지 않다. 서두르지 않고 가장자리를 끝까지 걸었다. 물 밑 얼굴들은 따라오기만 하고 잡지는 않았다.<br><br>얼굴을 직접 보지 않고 비친 것으로 읽는다. 마주치지 않고 읽는 법. 위험한 얼굴일수록 한 겹 건너서 본다.`,
      ng:`수면을 보는데 비친 천장에 이쪽 얼굴도 비친다. 그 아래 물 밑에 이쪽을 닮은 얼굴이 누워 있다. 비친 얼굴과 누운 얼굴이 겹친다.<br><br>눈이 맞았다. 수면을 사이에 두고. 다리가 물 쪽으로 기운다.<br>일행이 등덜미를 잡았다. 수면에 손바닥을 짚어 물보라를 일으켰다. 얼굴들이 흩어졌다. 손목까지 물에 잠긴 손이 한참 저렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 일행의 귓불',
  x:`쉬면서 일행 얼굴을 하나씩 봤다. 버릇이다. 쉴 때 상을 봐 둔다.<br><br>
    한 사람 귓불이 이상하다. 아래로 늘어졌다. 무엇이 매달린 것처럼. 그리고 조금 기울었다. 어둠 쪽으로.<br>
    귀는 듣는 자리다. 귓불이 기우는 쪽에서 누가 부른다. 본인은 아직 못 들었다.<br><br>
    곧 듣는다. 귓불이 어깨에 닿을 만큼 늘어졌다.`,
  o:[
    { l:'① 귓불이 기우는 정도로 부름이 얼마나 가까운지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`귓불을 다른 귀와 견줬다. 한쪽만 늘어졌다. 어둠 쪽 귀. 늘어진 길이가 손가락 한 마디. 아직 멀다. 두 마디면 들린다. 세 마디면 대답한다.<br><br>그 사람에게 반대쪽 귀를 어둠 쪽으로 돌리고 앉게 했다. 늘어진 귀는 손으로 덮게 했다. 들리는 귀를 바꾸면 부름이 다시 처음부터 와야 한다.<br>귓불이 천천히 올라왔다. 다음 쉬는 자리까지는 버틴다. 그때 또 보면 된다.<br><br>상은 멈춘 그림이 아니다. 얼마나 기울었는지가 얼마나 남았는지를 말한다. 얼굴로 시간을 재는 눈이 생겼다.`,
      ng:`재는 사이 그 사람 귓불이 한 마디 더 늘어진다. 그 사람이 고개를 든다. 「누가 불렀어?」<br><br>대답하지 말라고 할 틈도 없이 「응」 했다. 어둠 쪽에서 반가운 숨이 났다.<br>그 사람 입을 막고 끌어안았다. 그 사람이 밤새 어둠 쪽으로 가려 했다. 팔이 저렸다. 아침에 귓불이 어깨에 닿아 있었다. 천천히 올라왔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 그 사람 귀를 막고 이쪽 목소리로 계속 말을 건다.', k:'bond', dc:22,
      ok:`옆에 앉아 손바닥으로 그 사람 귀를 덮었다. 그리고 쉬지 않고 말을 걸었다. 아무 말이나. 여기 오기 전 이야기, 먹고 싶은 것.<br><br>부르는 소리는 빈 귀를 찾는다. 사람 말이 들어찬 귀에는 자리가 없다.<br>귓불이 조금씩 올라왔다. 그 사람이 지쳐 잠들 때까지 말했다. 목이 쉬었다. 그 사람은 꿈에서 이쪽 목소리를 들었다고 했다.`,
      ng:`말을 거는데 그 사람이 이쪽 말을 안 듣는다. 다른 데를 듣는다. 눈이 멍하다.<br><br>덮은 손바닥 밑 귀가 차다. 손바닥이 어둠 쪽으로 끌린다. 귀째.<br>귀를 놓지 않으려 버텼다. 그 사람이 아프다고 소리쳤다. 그제야 눈에 초점이 돌아왔다. 귓불에 이쪽 손톱자국이 났다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'문 앞 — 문구멍 너머의 눈',
  x:`문에 둥근 구멍이 나 있다. 안을 들여다보는 구멍이다. 그런데 구멍 너머에 눈이 있다. 저쪽에서 이쪽을 본다.<br><br>
    눈 하나만 보인다. 얼굴 없이 눈만. 깜빡이지 않는다.<br>
    상은 얼굴 전체로 본다. 눈 하나로는 반도 못 본다. 그래도 눈은 얼굴에서 제일 말이 많다.<br><br>
    문을 지나야 한다. 구멍 앞을.`,
  o:[
    { l:'① 눈 하나로 얼굴 전체를 읽는다.', k:'gaze', dc:22,
      ok:`눈동자 크기, 흰자의 핏발, 눈꺼풀이 덮인 정도. 눈동자가 크다. 어둠에 오래 있었다. 핏발이 없다. 피가 안 돈다. 눈꺼풀이 위로 끝까지 젖혀졌다. 감을 수 없다.<br><br>감을 수 없는 눈은 늘 본다. 늘 보는 것은 자는 법을 모른다. 그런데 오래 본 눈은 빛에 약하다.<br>등불 덮개를 열어 구멍에 빛을 바로 들이댔다. 저쪽 눈이 움찔 물러났다. 구멍이 비었다. 그 틈에 문을 지났다.`,
      ng:`눈을 읽는데 눈이 이쪽 눈을 읽는다. 이쪽 눈 안쪽까지 들어온다.<br><br>머릿속이 하얘진다. 무엇을 보고 있었는지 잊는다. 그 눈만 남는다.<br>일행이 이쪽 눈을 손으로 가렸다. 한참 뒤에야 정신이 들었다. 눈꺼풀이 감기지 않아 눈이 말라 아팠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 구멍보다 낮게 엎드려 지난다.', k:'hide', dc:22,
      ok:`구멍은 서 있는 사람 눈높이다. 그 아래로 기었다. 엎드려서.<br><br>구멍 너머 눈이 위만 본다. 아래는 문짝이 가린다. 일행도 하나씩 기어서 지났다.<br>다 지났을 때 구멍에서 눈이 사라졌다. 문 아래 틈에 눈 하나가 바닥에 붙어 있었다. 늦게 내려왔다.`,
      ng:`엎드려 기는데 문 아래 틈에서 눈이 이쪽을 본다. 구멍에서 내려왔다. 이쪽보다 먼저.<br><br>바로 코앞이다. 눈이 마주쳤다. 땅바닥에서.<br>뒤로 물러나다 일행과 부딪혔다. 둘이 엉켜 넘어졌다. 눈은 끝까지 깜빡이지 않았다. 일어나서도 한참 바닥을 못 봤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'③ 눈을 마주 보며 버틴다 — 먼저 피하지 않는다.', k:'steady', dc:23,
      ok:`구멍 앞에 서서 그 눈을 똑바로 봤다. 기세를 실어. 얼굴로 하는 싸움이다.<br><br>그쪽 눈은 감을 수 없다. 이쪽은 감을 수 있다. 그래서 이쪽이 더 오래 버틸 수 있다. 감고 싶을 때 감지 않으면 된다.<br>한참 뒤 그쪽 눈동자가 아주 조금 옆으로 미끄러졌다. 피한 것이다. 구멍이 비었다. 문을 열고 지났다. 눈이 따끔거려 한참 눈물이 났다.`,
      ng:`마주 보는데 저쪽 눈이 이쪽 눈과 똑같아진다. 눈동자 크기, 핏발, 눈꺼풀.<br><br>거울을 보는 것 같다. 어느 쪽이 이쪽인지 헷갈린다. 이쪽 눈꺼풀이 위로 젖혀진다. 감을 수가 없다.<br>일행이 이쪽 얼굴을 돌려세웠다. 눈을 감는 데 한참 걸렸다. 그 뒤로 눈이 뻑뻑해 자주 깜빡였다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'부조정실 — 모니터 속 방청객',
  x:`부조정실 모니터 벽에 방청석 얼굴들이 크게 잡혀 있다. 한 화면에 한 얼굴. 아이들 얼굴이다. 다 웃는다.<br><br>
    한 화면만 얼굴이 바뀌고 있다. 아이 얼굴에서 조금씩 어른 얼굴로. 눈썹이 짙어지고 턱이 길어진다.<br>
    바뀌어 가는 얼굴이 일행 하나를 닮아 간다. 그 일행은 지금 이쪽 옆에 서 있다.<br><br>
    화면 아래 자막. 오늘의 친구 — 섭외 중.`,
  o:[
    { l:'① 바뀌는 순서를 읽어 다 바뀌기 전에 끊는다.', k:'gaze', dc:22,
      ok:`얼굴이 바뀌는 순서를 봤다. 눈썹, 턱, 그다음 코. 마지막이 눈이다. 눈이 바뀌면 다 바뀐다.<br><br>사람 얼굴을 베끼는 것은 그 사람이 화면을 볼 때 눈을 베낀다. 일행의 눈을 손으로 가렸다. 「보지 마.」<br>화면 속 얼굴이 눈 앞에서 멈췄다. 아이 눈에 어른 얼굴. 반쯤 된 얼굴이 우스꽝스럽다. 자막이 바뀌었다. 섭외 실패. 일행이 손 밑에서 떨었다.`,
      ng:`순서를 읽는 사이 일행이 화면을 봤다. 제 얼굴을 닮아 가는 화면을. 눈을 떼지 못한다.<br><br>화면 속 얼굴의 눈이 바뀐다. 일행 눈이 된다. 일행이 화면 쪽으로 한 걸음 간다.<br>일행 머리를 감싸 화면에서 돌렸다. 일행이 비명을 질렀다. 화면 속 얼굴은 다 된 얼굴로 웃었다. 일행 얼굴의 무언가가 반쯤 빠져나간 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 모니터 속 얼굴을 끝까지 들여다본다.', k:'gaze', dc:23,
      doom:{ title:'섭외', what:'모니터 속으로 얼굴부터 빨려 들어갑니다', dc:18, sec:45,
        text:`일행을 밀어내고 이쪽이 화면을 봤다. 상을 다 읽으려고. 바뀌는 얼굴을 끝까지.<br><br>얼굴이 멈춘다. 그리고 다시 바뀐다. 일행이 아니라 이쪽으로. 이쪽 눈썹, 이쪽 턱. 이쪽 눈.<br>눈이 바뀌는 순간 화면 유리가 이쪽 얼굴에 닿는다. 차다. 유리가 물처럼 얼굴을 받아들인다.<br><br>빨려 들어간다. 얼굴부터. 화면 안쪽에서 방청석 아이들이 다 같이 박수를 친다.`,
        dieText:`화면 아래 자막이 바뀌었다. 오늘의 친구 — 섭외 완료.<br><br>모니터 속 얼굴이 웃는다. 다른 아이들처럼. 어른 얼굴이다.<br>일행이 화면을 껐다. 꺼진 화면 유리에 그 얼굴이 남아 있었다. 손을 흔들었다.` },
      ok:`화면을 보되 한쪽 눈만 썼다. 다른 쪽 눈은 감았다. 한쪽 눈으로 보는 얼굴은 반만 베낄 수 있다.<br><br>얼굴이 이쪽으로 바뀌다 멈칫한다. 반쪽은 이쪽, 반쪽은 아이. 반쪽 얼굴은 섭외가 안 된다.<br>그 반쪽 얼굴이 무엇을 닮았는지 다 읽었다. 이 건물이 데려간 아이들 얼굴이 겹쳐 있다. 화면을 껐다. 꺼진 유리 속 반쪽 얼굴이 천천히 흐려졌다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'사감실 앞 — 세는 얼굴',
  x:`복도 끝 사감실 앞에 사감이 서 있다. 키가 크다. 열쇠 꾸러미를 쥐었다. 얼굴이 이쪽을 향한다.<br><br>
    얼굴이 이상하다. 눈동자가 쉬지 않고 움직인다. 왼쪽에서 오른쪽으로. 한 칸씩. 무엇을 센다.<br>
    입술이 움직인다. 숫자다. 이백열, 이백열하나.<br><br>
    세는 눈이 이쪽 일행 쪽으로 오고 있다.`,
  o:[
    { l:'① 세는 얼굴이 무엇으로 세는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`눈동자가 한 칸씩 갈 때마다 멈추는 높이를 봤다. 다 같은 높이다. 얼굴 높이. 사감은 얼굴을 센다. 몸이 아니라.<br><br>그리고 멈출 때마다 눈꺼풀이 한 번 내려간다. 얼굴을 찍는다. 찍은 얼굴은 출석이다. 얼굴이 안 보이면 셀 수 없다.<br>일행 모두 얼굴을 손으로 가리고 벽을 보게 했다. 세는 눈이 이쪽 줄에 와서 멈추지 않고 지나갔다. 이백열둘. 사감 입술이 거기서 멈췄다. 맞았다.<br><br>얼굴은 사람만 읽는 게 아니다. 얼굴을 세는 것, 얼굴을 찾는 것도 얼굴로 일한다. 저쪽이 얼굴의 어디를 보는지 읽으면 감출 데가 보인다.`,
      ng:`읽는 사이 세는 눈이 이쪽 얼굴에 멈췄다. 눈꺼풀이 내려간다. 찍혔다.<br><br>「이백열셋.」 사감 입술이 숫자를 하나 넘겼다. 얼굴이 기뻐한다. 아니, 얼굴의 한쪽만.<br>사감 얼굴의 다른 쪽이 우는 것처럼 찡그렸다. 그 틈에 달아났다. 등 뒤에서 열쇠 소리가 따라왔다. 다음 층 계단까지 쫓겼다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 사감 눈길이 닿기 전에 옆 호실로 숨는다.', k:'hide', dc:22,
      ok:`세는 눈이 오른쪽으로 갈 때 왼쪽 호실 문을 밀고 들어갔다. 일행도 하나씩. 눈이 돌아오기 전에.<br><br>호실 안 침대 이불이 사람 모양으로 부풀었다. 그 옆 벽에 붙어 숨을 죽였다. 이 호실은 이미 센 호실이다.<br>열쇠 소리가 복도를 지나갔다. 문 앞에서 멈추지 않았다. 다 센 데는 다시 안 센다.`,
      ng:`숨는데 호실 문이 삐걱 운다. 세는 눈이 이쪽으로 휙 돈다.<br><br>사감이 호실로 온다. 문을 연다. 침대를 센다. 하나, 둘. 벽에 붙은 이쪽 일행도 센다. 하나가 많다.<br>침대 밑 물속으로 다 같이 잠겼다. 숨을 참았다. 사감이 나갈 때까지. 가슴이 찢어질 것 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 사감 얼굴을 마주 보고 이름을 말한다.', k:'steady', dc:23,
      ok:`사감 앞에 섰다. 세는 눈이 이쪽에 멈추기 전에 먼저 말했다. 「방문객입니다. 재적 아님.」<br><br>사감 얼굴이 멈춘다. 눈동자가 한 칸에서 서 있다. 세던 숫자가 입술에서 멎었다. 재적 아닌 사람은 셀 칸이 없다.<br>얼굴이 한참 이쪽을 봤다. 한쪽 입꼬리가 아주 조금 풀렸다. 열쇠 꾸러미로 계단 쪽을 가리켰다. 다 같이 고개를 숙이고 지났다.`,
      ng:`말했다. 사감 얼굴이 이쪽 얼굴을 읽는다. 찍는다. 「방문객.」 고개를 끄덕인다.<br><br>그리고 다시 센다. 「방문객 하나.」 그런 칸이 생겼다. 셀 칸이 생기면 세어진다.<br>열쇠 꾸러미가 이쪽 손목에 걸렸다. 뿌리치느라 손목이 쓸렸다. 사감은 세던 숫자를 다시 처음부터 셌다.`,
      win:{ exp:22, dream:3, spirit:7 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'벽 — 액자 속 초상들',
  x:`복도 양쪽 벽에 초상화가 줄지어 걸렸다. 다 같은 자세다. 손을 모으고 정면을 본다. 표정이 없다.<br><br>
    지나가며 뒤를 돌아봤다. 지나온 초상들 표정이 바뀌어 있다. 입이 조금 벌어졌다. 눈썹이 올라갔다.<br>
    앞의 초상들은 아직 표정이 없다. 지나가야 바뀐다.<br><br>
    마지막 초상까지 열둘이 남았다.`,
  o:[
    { l:'① 바뀐 표정들을 이어 읽는다.', k:'gaze', dc:22,
      ok:`지나온 초상들을 순서대로 다시 봤다. 첫째는 입만 벌렸다. 둘째는 눈썹까지. 셋째는 손이 풀렸다. 넷째는 손가락이 이쪽을 가리킨다.<br><br>지날수록 더 많이 움직인다. 열두 개를 다 지나면 마지막 초상은 액자 밖으로 나온다. 표정이 이야기다. 끝까지 지나면 이야기가 끝난다.<br>여덟째 앞에서 뒤로 돌아 일행과 뒷걸음질로 지났다. 초상들이 보는 쪽으로 지나가면 지나간 게 아니다. 나머지 초상들 표정이 바뀌지 않았다.`,
      ng:`읽느라 오래 서 있는 사이 지나온 초상들 표정이 한 단계씩 더 바뀐다. 보고 있는 동안에도.<br><br>넷째 초상 손가락이 액자 유리에 닿았다. 유리가 안쪽에서 톡 울린다.<br>뛰었다. 남은 열둘이 한꺼번에 바뀌었다. 등 뒤에서 유리가 줄줄이 금 가는 소리가 났다. 복도를 빠져나올 때까지 귀를 막았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 초상들을 보지 않고 눈을 감은 채 지난다.', k:'steady', dc:22,
      ok:`눈을 감았다. 일행에게도 감으라고 했다. 앞사람 어깨를 잡고 한 줄로 걸었다.<br><br>표정은 누가 볼 때 바뀐다. 보는 사람이 없으면 초상은 그냥 그림이다. 감은 눈 너머로 아무 소리도 나지 않았다.<br>복도 끝에서 눈을 떴다. 돌아보지 않았다. 등 뒤에서 그림이 아주 조금 한숨 쉬는 소리가 난 것 같았다.`,
      ng:`눈을 감고 걷는데 바로 옆에서 숨소리가 난다. 액자 높이에서.<br><br>눈을 뜨고 싶다. 참았다. 숨소리가 귓가로 온다. 차다. 얼굴 앞에 무엇이 와 있다.<br>참다못해 눈을 떴다. 초상이 액자 안에서 코앞까지 얼굴을 내밀고 있었다. 뒤로 넘어졌다. 머리를 벽에 찧었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'어둠 — 얼굴 없는 것',
  x:`복도 한가운데 무엇이 서 있다. 사람 키다. 사람 모양이다. 얼굴이 없다.<br><br>
    얼굴 자리가 매끈하다. 눈도 코도 입도 없다. 그런데 이쪽을 향해 있다.<br>
    얼굴이 없으면 상을 볼 수 없다. 관상가에게 제일 무서운 것이 이것이다. 읽을 것이 없는 것.<br><br>
    그것이 천천히 한 걸음 다가왔다.`,
  o:[
    { l:'① 읽을 수 없으니 기세로 버틴다.', k:'steady', dc:22,
      ok:`읽으려 하지 않았다. 숨을 고르고 발을 디뎠다. 얼굴이 없는 것에게 얼굴을 보여 줬다. 겁 없는 얼굴을.<br><br>그것이 멈췄다. 얼굴이 없는 것은 얼굴을 탐낸다. 겁먹은 얼굴은 쉽게 벗겨진다. 겁 없는 얼굴은 단단하다.<br>그것이 옆으로 비켜섰다. 지날 때 매끈한 얼굴 자리에 이쪽 얼굴이 아주 희미하게 비쳤다. 빌려 보다 마는 것처럼.`,
      ng:`버티는데 얼굴에서 겁이 새 나온다. 숨기지 못했다.<br><br>그것이 다가온다. 매끈한 얼굴이 이쪽 얼굴 앞에 온다. 닿을 듯이. 이쪽 얼굴 살갗이 그쪽으로 당겨진다.<br>뒤로 넘어지며 얼굴을 감쌌다. 그것이 지나갔다. 손을 떼니 볼이 얼얼하다. 얼굴 한 겹을 빼앗긴 것 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 그것을 보는 일행의 얼굴로 그것을 읽는다.', k:'gaze', dc:23, wake:1,
      ok:`그것을 보지 않고 일행 얼굴을 봤다. 사람 얼굴은 본 것을 비춘다. 다섯 얼굴에 그것이 비친다.<br><br>둘은 눈이 아래로 간다. 그것 발을 본다. 셋은 위로. 머리를 본다. 아무도 가운데를 안 본다. 가운데에 무엇이 있다. 다들 저도 모르게 피한다. 피하는 자리가 약한 자리다.<br>그것의 가슴 한가운데에 등불을 들이댔다. 그것이 처음으로 움찔했다. 얼굴 없는 몸이 뒤로 물러나 어둠으로 꺼졌다.<br><br>얼굴이 없는 것도 남의 얼굴에는 비친다. 읽을 얼굴이 없으면 그것을 보는 얼굴을 읽는다. 한 겹 돌아가는 눈이 생겼다.`,
      ng:`일행 얼굴을 보는데 일행 얼굴들이 하나씩 비어 간다. 그것을 오래 본 얼굴부터. 표정이 빠져나간다.<br><br>멍한 얼굴 다섯이 그것을 본다. 그것 얼굴 자리에 표정이 하나씩 생긴다. 일행 표정이다.<br>일행 눈을 하나씩 손으로 가려 돌려세웠다. 다들 한참 웃지도 울지도 못했다. 그것은 남의 표정을 입고 어둠으로 갔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'스튜디오 — 카메라 렌즈',
  x:`스튜디오 카메라 세 대가 동산 세트를 향해 있다. 셋 다 빨간 불이 켜졌다. 녹화 중이다. 찍을 사람이 아무도 없는데.<br><br>
    가운데 카메라 렌즈가 둥글고 크다. 렌즈 유리에 스튜디오가 작게 휘어져 비친다. 그 안에 이쪽 얼굴도 있다.<br>
    렌즈에 비친 이쪽 얼굴이 웃는다. 이쪽은 웃지 않았다.<br><br>
    카메라에 잡힌 얼굴은 방송에 나간다. 방송에 나간 얼굴은 이 건물 것이다.`,
  o:[
    { l:'① 렌즈에 얼굴을 대고 비친 상을 읽는다.', k:'gaze', dc:23,
      doom:{ title:'클로즈업', what:'렌즈에 얼굴을 빼앗깁니다', dc:18, sec:45,
        text:`렌즈 앞에 얼굴을 바짝 댔다. 비친 얼굴이 커진다. 화면 가득. 웃는다. 이를 다 드러낸다.<br><br>그 얼굴의 상이 읽힌다. 무대에 설 상. 오늘의 친구 상. 렌즈가 초점을 맞추는 소리가 난다. 지잉.<br>얼굴이 렌즈 쪽으로 당겨진다. 살갗이, 눈썹이, 입술이. 얼굴 한 겹이 유리에 붙는다. 떼어지지 않는다.<br><br>렌즈가 다시 지잉 돈다. 얼굴이 벗겨지는 소리가 난다. 아주 작게.`,
        dieText:`스튜디오 모니터에 얼굴 하나가 클로즈업으로 나간다. 웃는다.<br><br>카메라 앞에 누가 서 있다. 얼굴이 없다. 매끈하다.<br>빨간 불이 하나씩 꺼졌다. 오늘 녹화는 끝났다. 잘 나왔다.` },
      ok:`렌즈에 얼굴을 대지 않았다. 팔을 뻗어 렌즈 앞에 손바닥을 댔다. 렌즈는 손바닥만 찍는다.<br><br>손바닥에도 상이 있다. 손금. 손금은 얼굴만큼 말하지 않는다. 렌즈가 초점을 못 맞춘다. 지잉, 지잉.<br>손바닥을 댄 채로 렌즈 덮개를 찾아 씌웠다. 빨간 불이 깜빡였다. 렌즈 덮개 안쪽에서 무엇이 유리를 긁는 소리가 났다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 내공으로 기척을 죽이고 카메라 사이 사각을 지난다.', k:'hide', dc:22, cost:{ qi:30 },
      ok:`내공을 안으로 거둬 기척을 죽였다. 숨을 얕게. 얼굴의 기색까지 가라앉혔다. 카메라는 얼굴의 기색을 찍는다.<br><br>세 대가 겹치지 않는 자리를 봤다. 바닥 테이프 자국 사이. 거기를 밟고 지났다. 빨간 불이 이쪽을 지나쳐 세트를 찍었다.<br>세트 뒤에 닿아 내공을 풀었다. 숨이 한꺼번에 터졌다. 카메라 하나가 늦게 이쪽 쪽으로 돌았다. 아무것도 없는 데를 찍었다.`,
      ng:`기척을 죽였는데 얼굴 기색이 다 죽지 않았다. 겁이 남았다.<br><br>가운데 카메라가 휙 돈다. 겁먹은 얼굴은 화면에 잘 받는다. 빨간 불이 이쪽 얼굴을 잡는다. 지잉.<br>얼굴을 팔로 가리고 뛰었다. 세트 소품을 넘어뜨렸다. 넘어지며 이마를 찧었다. 모니터 하나에 팔로 가린 얼굴이 잡혀 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22, qi:-5 } },
    { l:'③ 렌즈를 천으로 감싸 묶는다.', k:'fix', dc:22,
      ok:`겉옷을 벗어 가운데 카메라 렌즈를 감쌌다. 소매로 묶었다. 세 대 가운데 하나만 막아도 화면이 빈다.<br><br>모니터에 검은 화면이 하나 생겼다. 나머지 둘은 옆모습만 찍는다. 옆모습은 상이 반이다. 방송에 나갈 얼굴로는 모자라다.<br>세트를 지나 출구까지 갔다. 겉옷은 두고 왔다. 춥지만 얼굴은 이쪽 것이다.`,
      ng:`감싸는데 렌즈가 천 너머로 이쪽 손을 찍는다. 천이 얇다. 렌즈가 지잉 돈다.<br><br>손등 살갗이 천을 통해 당겨진다. 손을 뗐다. 손등이 벌겋게 쓸렸다.<br>천은 렌즈에 붙어 버렸다. 렌즈가 천을 찍는다. 천에 손 모양 자국이 하얗게 떴다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'교실동 — 물에 비친 반 아이들',
  x:`허리까지 물이 찬 교실이다. 의자들이 물속에 잠겼다. 아무도 앉아 있지 않다.<br><br>
    그런데 물 위에 비친 교실에는 아이들이 앉아 있다. 수면에. 책상에 팔을 괴고, 앞을 본다.<br>
    비친 얼굴들이 보인다. 상이 다 다르다. 하나하나 다른 아이다. 그래도 표정은 하나다.<br><br>
    수면 위 아이들 얼굴이 이쪽이 물을 저을 때마다 흔들린다.`,
  o:[
    { l:'① 비친 얼굴들의 표정을 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`표정이 하나다. 무서운 얼굴이 아니다. 슬픈 얼굴도 아니다. 지루한 얼굴이다. 수업이 끝나기만 기다리는 얼굴.<br><br>아이들은 종을 기다린다. 해칠 마음이 없다. 다만 수업 중에 일어나 돌아다니는 사람은 아이들이 쳐다본다. 쳐다보는 눈이 서른이면 무겁다.<br>물을 젓지 않고 발을 끌어 천천히 지났다. 수업 중인 교실을 조용히 지나가는 사람처럼. 수면 위 아이들이 하나도 고개를 돌리지 않았다.<br><br>여럿의 얼굴에서 하나의 표정을 읽는다. 무리의 상을 보는 눈. 한 사람씩이 아니라 한 덩어리로 얼굴을 읽는 법이 생겼다.`,
      ng:`읽는 사이 물이 흔들렸다. 이쪽 걸음 때문에. 수면 위 얼굴들이 일그러진다.<br><br>다시 펴진 얼굴들이 다 이쪽을 본다. 수업 중에 떠드는 사람을 보는 얼굴로. 서른 눈.<br>몸이 무거워졌다. 물이 아니라 눈길이 무겁다. 교실을 나올 때까지 어깨를 펴지 못했다. 등 뒤가 오래 따가웠다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 교탁 서랍을 뒤진다.', k:'luck', dc:22,
      ok:`교탁 위 서랍이 물 밖이다. 열었다. 분필, 출석부, 그리고 종이 봉지.<br><br>담임이 수업 끝나고 아이들에게 나눠 주려던 것이다. 산에서 딴 나물을 말린 것. 봉지에 「착한 반」이라고 적혀 있다.<br>한 줌을 덜었다. 수면 위 아이들 몇이 이쪽을 보다가 고개를 돌렸다. 나눠 주는 것을 막는 아이는 없다.`,
      ng:`서랍을 여는데 출석부가 먼저 튀어나와 펼쳐진다. 물 위로 떨어진다.<br><br>펼쳐진 장의 이름들이 수면에 번진다. 수면 위 아이들이 일제히 출석부를 본다. 그리고 이쪽을 본다.<br>출석부를 건지려다 물에 빠졌다. 허우적대다 의자 다리에 정강이를 몇 번이고 찧었다.`,
      win:{ exp:16, item:'산나물', mind:6 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 밤에 얼굴을 만지는 손',
  x:`자다가 깼다. 얼굴 위에 무엇이 있다. 손이다. 손가락 끝이 이쪽 얼굴을 더듬는다.<br><br>
    이마, 눈썹, 콧대, 인중. 하나하나 천천히. 재는 손길이다. 생김새를 외우는 손이다.<br>
    관상가가 남의 얼굴을 읽을 때 손으로 짚는 순서와 같다. 누가 이쪽에게서 배웠다.<br><br>
    손가락이 입술에 닿았다. 다음은 턱이다. 다 외우면 무엇이 되는지는 안다.`,
  o:[
    { l:'① 눈을 감은 채 손이 외우는 순서를 거꾸로 흐트러뜨린다.', k:'gaze', dc:22,
      ok:`움직이지 않았다. 대신 얼굴을 움직였다. 손가락이 인중을 지날 때 입술을 비틀었다. 콧대로 돌아갈 때 눈썹을 찡그렸다.<br><br>재는 손은 재는 동안 얼굴이 가만있어야 한다. 매번 다른 얼굴을 재면 외울 얼굴이 없다. 손가락이 망설인다. 처음부터 다시 잰다. 또 흐트러뜨렸다.<br>새벽까지 그렇게 했다. 손이 지쳐 떨어졌다. 얼굴 근육이 다 쑤셨다. 그래도 이쪽 얼굴은 이쪽 것이다.`,
      ng:`흐트러뜨리는데 손이 그걸 따라 한다. 비튼 입술, 찡그린 눈썹까지 다 외운다.<br><br>손가락이 턱에 닿았다. 다 됐다. 손이 떨어져 어둠으로 간다.<br>아침에 일행 하나가 이쪽을 보고 흠칫했다. 어젯밤 어둠 속에서 이쪽 얼굴을 봤다고 했다. 이쪽은 계속 누워 있었다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 손목을 붙잡는다.', k:'steady', dc:22,
      ok:`눈을 번쩍 뜨며 손목을 잡았다. 차다. 가늘다. 놓치지 않았다.<br><br>손목 너머가 어둠이다. 몸이 안 보인다. 손이 빠져나가려 버둥거린다. 힘이 세지 않다. 얼굴을 외우는 손은 힘을 쓰는 손이 아니다.<br>잡은 채로 소금을 그 손바닥에 쥐여 주었다. 손이 소금을 쥐고 오그라들며 어둠으로 빠져나갔다. 손바닥에 남은 냉기가 오래 갔다.`,
      ng:`손목을 잡았는데 손목이 길다. 끝이 없다. 당기는 대로 손목이 늘어난다.<br><br>그사이 다른 손이 얼굴에 닿는다. 하나가 아니었다. 턱을 더듬는다.<br>얼굴을 팔로 감싸고 굴렀다. 일행이 깨어 등불을 키웠다. 아무것도 없었다. 이쪽 턱에 손가락 자국이 넷 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] }

]);

// ------------------------------------------
// 탐정 · 자원 없음
// ------------------------------------------
kJob('detective', 'A', [

{ at:'A', t:'복도 — 젖은 바닥의 마른 발자국',
  x:`복도 바닥이 젖었다. 물이 발목까지 고였다가 빠진 자리다. 걸으면 철벅거린다.<br><br>
    그 위에 마른 발자국이 찍혀 있다. 젖은 바닥에 마른 자국. 발 모양만 물이 비켜 갔다.<br>
    맨발이다. 저쪽에서 이쪽으로 온다. 이쪽 일행이 서 있는 데까지 와서 끊겼다.<br><br>
    젖은 데에 마른 자국이 생기려면 그 발이 물보다 먼저 와 있었어야 한다.`,
  o:[
    { l:'① 발자국을 하나씩 재며 따진다.', k:'gaze', dc:22, wake:1,
      ok:`보폭을 쟀다. 처음엔 넓다. 갈수록 좁아진다. 마지막 셋은 거의 붙어 있다. 다가오며 느려졌다. 살금살금.<br><br>마지막 발자국은 일행 맨 뒤 사람 발 바로 뒤에 있다. 그 사람 발과 크기가 같다. 모양도. 왼발 새끼발가락이 안으로 굽은 것까지.<br>맨 뒤 사람 신발을 벗겨 보았다. 그 발이다. 그러면 저 발자국은 그 사람이 걸어온 적 없는 길을 걸어왔다. 그 사람 발을 빌려서. 맨 뒤를 비우고 그 사람을 가운데 세웠다. 다음 복도에서 마른 발자국이 맨 뒤 빈자리까지 와서 서성이다 사라졌다.<br><br>발자국 하나로는 아무것도 아니다. 늘어놓으면 걸음이 되고 걸음은 뜻이 된다. 흔적을 줄 세워 그것이 하려던 일을 읽는 눈이 생겼다.`,
      ng:`재느라 쪼그려 앉은 사이 발자국이 하나 늘었다. 이쪽 발 바로 뒤에.<br><br>마른 자국이다. 이쪽 발 모양이다. 뒤꿈치에 숨결 같은 냉기가 닿는다.<br>일어나 뛰었다. 젖은 바닥에 미끄러져 넘어졌다. 손목을 짚었다가 삐었다. 돌아보니 마른 발자국이 이쪽이 넘어진 자리를 빙 둘러 찍혀 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 발자국이 처음 시작된 데를 찾아간다.', k:'sense', dc:22,
      ok:`거꾸로 따라갔다. 복도 끝 벽에서 시작된다. 벽 앞 첫 발자국 둘이 나란히 찍혔다. 벽에서 걸어 나왔다.<br><br>벽에 손자국이 있다. 안쪽에서 민 손바닥 자국. 회벽이 얇게 부풀었다. 그 안에 무엇이 있었다. 지금은 비었다. 나와서 어딘가에 있다.<br>벽 앞에 놓인 물통 하나를 챙겼다. 마개가 꼭 닫혀 있다. 나온 것이 남긴 게 아니라 들어가기 전의 누가 남긴 것이다. 맑은 물이 반쯤 들었다.`,
      ng:`따라가는데 발자국이 끝나지 않는다. 벽 앞에서 끝나는 줄 알았는데 벽을 타고 올라간다. 천장으로.<br><br>천장에 마른 발자국이 거꾸로 찍혀 있다. 이쪽 머리 위로 돌아온다. 일행이 있는 쪽으로.<br>뛰어 돌아갔다. 일행 머리 위 천장에 발자국이 멈춰 있었다. 다들 고개를 숙이고 그 밑을 빠져나왔다. 뒷목이 내내 오싹했다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 물을 피해 마른 발자국을 밟고 걷는다.', k:'evade', dc:23,
      doom:{ title:'마른 자리', what:'발자국 주인에게 발목을 잡혀 끌려갑니다', dc:18, sec:50,
        text:`젖은 데를 피해 마른 발자국만 골라 디뎠다. 꼭 맞는다. 이쪽 발 크기다.<br><br>세 걸음째에 발이 안 떨어진다. 발자국이 발바닥을 문다. 발밑에서 차가운 발바닥이 이쪽 발바닥에 맞닿는다. 거꾸로. 바닥 저편에서.<br>발목을 잡힌다. 바닥 저편의 손이다. 당긴다. 아래가 아니라 뒤로. 발자국이 시작된 쪽으로. 발이 미끄러진다.<br><br>끌려간다. 마른 발자국을 따라 거꾸로. 복도 끝 벽이 다가온다. 회벽이 부풀어 있다.`,
        dieText:`복도 바닥이 젖었다. 그 위에 마른 발자국이 찍혀 있다.<br><br>두 줄이다. 하나는 벽에서 나와 이쪽으로 온다. 하나는 이쪽에서 벽으로 간다. 신발 자국이다.<br>벽 회벽이 새로 부풀었다. 사람 키만큼.` },
      ok:`발자국 하나를 디뎌 보기 전에 발끝으로 건드렸다. 마른 자리가 미지근하다. 마른 게 아니다. 무엇이 아직 거기 서 있다.<br><br>안 디뎠다. 젖은 바닥을 철벅이며 걸었다. 소리가 나도 그게 낫다. 젖은 데는 아무도 서 있지 않다.<br>일행에게도 발자국을 피하게 했다. 지나간 뒤 돌아보니 마른 발자국들이 하나씩 젖어 가고 있었다. 자리를 떠나는 것처럼.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A1', t:'로비 — 시계와 방송 시간표',
  x:`로비 벽시계가 네 시 오십삼 분이다. 초침이 없다. 접수처 유리에 방송 시간표가 붙었다. 「방글 동산 — 오후 다섯 시 생방송」.<br><br>
    여기 들어온 지 꽤 됐다. 시계는 그대로다. 멈춘 줄 알았다.<br>
    그런데 아까 접수처에서 돌아봤을 때는 오십사 분이었다. 지금 보니 오십삼 분이다.<br><br>
    시계가 거꾸로 갔거나, 보는 사람에 따라 다르거나. 다섯 시가 되면 무대에 불이 들어온다.`,
  o:[
    { l:'① 언제 시계가 움직이는지 따진다.', k:'gaze', dc:22, wake:1,
      ok:`일행 하나에게 시계를 보고 있게 했다. 이쪽은 등을 돌렸다. 숫자를 셌다. 백.<br><br>돌아봤다. 오십삼 분. 그대로다. 이번엔 둘 다 등을 돌렸다. 백. 돌아봤다. 오십사 분.<br>시계는 아무도 안 볼 때만 간다. 누가 보고 있으면 멈춘다. 그러면 할 일은 하나다. 일행 하나가 늘 시계를 보며 따라오게 했다. 다섯 시는 오지 않았다. 보고 있는 동안은.<br><br>현상 하나를 두고 조건을 하나씩 바꿔 본다. 봤을 때, 안 봤을 때. 맞지 않는 것 하나를 시험으로 바꾸는 손이 생겼다. 무서운 것도 규칙이 있다.`,
      ng:`따지는 사이 다들 시계를 등졌다. 누구도 안 봤다. 짧은 사이.<br><br>돌아보니 오십팔 분이다. 한꺼번에 다섯 분이 갔다. 위층에서 박수가 연습처럼 한 번 났다.<br>다들 시계를 노려보며 뒷걸음질로 계단까지 갔다. 목이 꺾일 듯이 돌아보며 올랐다. 목이 한참 아팠다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 시간표 종이를 떼어 뒷면을 본다.', k:'fix', dc:22,
      ok:`시간표를 떼어 뒤집었다. 뒷면에 연필로 적혀 있다. 직원 메모다. 「5시 정각 — 방청객 착석 확인 후 입장. 미착석 시 대기.」<br><br>착석해야 시작한다. 방청석이 다 차야 시작한다. 빈자리가 있으면 기다린다. 기다리는 동안 다섯 시는 오지 않는다.<br>메모를 일행에게 돌려 읽혔다. 다들 방청석 근처에서는 절대 앉지 않기로 했다.`,
      ng:`떼는데 시간표가 유리에 붙어 안 떨어진다. 억지로 떼자 찢어졌다. 반쪽만 손에 남았다.<br><br>남은 쪽에 「착석」 한 단어만 보인다. 찢어진 쪽은 유리에 붙은 채다. 그쪽에 「미착석 시」 다음이 있다.<br>찢는 소리에 로비 의자들이 일제히 조금 돌았다. 이쪽을 향해. 앉으라는 듯이. 다리가 저절로 굽으려 했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'식당 — 하나 더 나오는 배식판',
  x:`식당 배식대에 배식판이 쌓여 있다. 끼니마다 내어 놓는 판이다. 배식대 옆 칠판에 숫자가 적혔다. 「아침 212 · 점심 212 · 저녁 212」.<br><br>
    다 쓴 판이 반납대에 쌓였다. 세 끼마다 213장이다. 한 장씩 남는다.<br>
    남는 판은 깨끗하다. 먹은 흔적이 없다. 다만 숟가락 자리에 젖은 자국이 있다.<br><br>
    배식대 위 오늘 저녁 판이 하나 더 나왔다. 214.`,
  o:[
    { l:'① 남는 판의 흔적으로 누구 몫인지 따진다.', k:'gaze', dc:22, wake:1,
      ok:`213번째 판들을 늘어놓았다. 끼니마다 한 장. 깨끗하다. 숟가락 자리만 젖었다. 숟가락을 들었다가 안 먹은 것이다.<br><br>먹으려 했는데 못 먹은 사람. 판을 받아 놓고 자리에 못 앉은 사람. 칠판 숫자에 들지 못한 사람이다. 재적에 없는 학생이 밥때마다 판을 받는다.<br>214번째는 오늘 생겼다. 이쪽 일행이 온 날이다. 판이 이쪽을 세기 시작했다. 214번째 판을 엎어 반납대 맨 아래에 넣었다. 엎은 판은 먹은 판이다. 배식대에서 판이 더는 안 나왔다.<br><br>남는 것 하나가 셈 전체를 말한다. 맞지 않는 숫자에서 거기 끼어든 사람을 세는 눈이 생겼다.`,
      ng:`늘어놓는 사이 배식대에서 판이 하나 더 나왔다. 215. 일행 수만큼 늘어난다.<br><br>판마다 숟가락 자리가 젖어 간다. 이쪽 일행 손 크기 젖은 자국.<br>판을 모조리 엎었다. 손이 떨려 판이 바닥에 떨어졌다. 쨍그랑 소리가 물속까지 울렸다. 식당 저편에서 의자 끄는 소리가 났다. 다 같이 식당을 빠져나왔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 214번째 판을 받아 먹는다.', k:'luck', dc:23,
      doom:{ title:'214', what:'식탁 밑 물속으로 끌려 내려갑니다', dc:18, sec:45,
        text:`배가 고팠다. 214번째 판을 들었다. 밥, 국, 나물. 김이 오른다. 숟가락을 들었다.<br><br>판을 든 순간 칠판 숫자가 바뀐다. 「저녁 213」. 이쪽이 세어졌다. 밥을 받은 사람은 학생이다.<br>식탁 앞에 섰다. 의자가 저절로 빠진다. 앉으라고. 의자 밑 물에서 손들이 올라와 무릎 뒤를 친다. 털썩 앉는다. 앉은 자리가 물 밑으로 꺼진다.<br><br>끌려 내려간다. 판을 든 채로. 식탁 밑은 깊다. 거기서 212명이 숟가락을 들고 기다린다.`,
        dieText:`칠판 숫자가 다시 고쳐졌다. 「저녁 213」.<br><br>반납대에 쌓인 판이 213장이다. 남는 판이 없다. 다 먹었다.<br>다음 날 아침 배식대에 판이 214장 나왔다. 하나가 남는다.` },
      ok:`판을 받았다. 받자마자 밥을 다른 판에 덜었다. 213번째 판으로. 214번째는 빈 판으로 반납대에 바로 올렸다.<br><br>받은 판이 비어서 돌아왔다. 다 먹은 판이다. 칠판 숫자가 바뀌지 않는다. 판은 먹은 사람이 아니라 받은 판을 센다. 받은 판을 돌려주면 받은 적이 없다.<br>덜어 낸 밥은 213번째 판 주인의 몫이다. 거기서 나물 한 줌만 덜어 챙겼다. 나머지는 두었다.`,
      win:{ exp:24, dream:4, item:'산나물' } },
    { l:'③ 배식대 뒤 조리실로 숨어 들어간다.', k:'hide', dc:22,
      ok:`배식대 아래로 몸을 낮춰 조리실 문을 밀었다. 조리실은 판을 세지 않는다. 세는 건 배식대다.<br><br>조리실 저장고 위 칸이 물 밖이다. 굵은 소금 자루가 있다. 조리 아주머니가 국 간을 하던 소금이다. 한 덩이를 챙겼다.<br>조리실 뒷문으로 빠져나왔다. 배식대 쪽에서 판 놓는 소리가 났다. 받을 사람이 안 왔다는 듯이 한참 그대로였다.`,
      ng:`숨어 들어갔는데 조리실 솥에 김이 오른다. 아무도 없는데 끓는다.<br><br>국자가 저 혼자 국을 휘젓는다. 그리고 멈춘다. 이쪽 쪽으로 국자가 들린다. 간을 보라는 듯이.<br>뒷문으로 뛰쳐나왔다. 국자에서 튄 국물이 팔에 닿았다. 국물인데 차가웠다. 데인 것처럼 벌겋게 부었다.`,
      win:{ exp:16, item:'소금 덩이', hp:7 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 하룻밤에 한 몫',
  x:`아침마다 식량이 준다. 한 사람 몫씩. 밤새 누가 먹는다.<br><br>
    일행은 서로를 의심한다. 다들 아니라고 한다. 다들 그럴 만큼 배가 고프다.<br>
    짐 자루 매듭은 그대로다. 매듭을 풀고 다시 맨 흔적이 없다. 그런데 안이 준다.<br><br>
    먹은 자리는 남는다. 부스러기, 자국, 냄새. 범인은 늘 무엇을 남긴다.`,
  o:[
    { l:'① 부스러기와 자국으로 먹은 것을 따진다.', k:'gaze', dc:22, wake:1,
      ok:`자루를 뒤집어 털었다. 부스러기를 등불 아래 늘어놓았다. 말린 고기 가장자리에 이빨 자국. 작다. 아이 이다. 앞니가 둘 빠졌다.<br><br>일행 중에 앞니 빠진 사람은 없다. 자루 매듭을 안 풀었으니 자루 밑을 봤다. 손톱만 한 구멍. 안에서 밖으로 실밥이 터졌다. 안에서 먹고 안에서 나갔다.<br>자루 안을 손으로 쓸었다. 바닥에 젖은 머리카락 한 올. 길다. 자루를 뒤집어 볕에 말리듯 등불에 쬐었다. 다음 날 아침엔 식량이 줄지 않았다.<br><br>의심은 사람을 보고, 증거는 자국을 본다. 서로를 보던 눈을 부스러기로 돌리는 법을 알았다. 일행을 쪼개지 않는 셈이다.`,
      ng:`늘어놓은 부스러기를 보는데 이빨 자국이 일행 하나의 이와 비슷해 보인다. 앞니가 조금 벌어진 사람.<br><br>입 밖에 냈다. 그 사람 얼굴이 굳는다. 아니라고 한다. 다른 일행들이 그 사람을 본다.<br>그날 하루 일행이 갈라졌다. 밤에 자루가 또 줄었다. 그 사람은 밤새 묶여 있었다. 아무도 사과하지 못했다.`,
      win:{ exp:23, dream:3, item:'말린 고기' }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 밤새 자루를 끌어안고 지킨다.', k:'bond', dc:22,
      ok:`자루를 품에 안고 등을 벽에 댔다. 일행 하나와 번갈아 깼다.<br><br>새벽녘 품 안 자루가 꿈틀했다. 안에서. 자루 천 너머로 작은 손이 더듬는다. 바스락. 자루를 꽉 조였다. 꿈틀대던 것이 멈췄다. 그리고 빠져나갔다. 바닥으로.<br>아침에 식량은 그대로였다. 자루 밑에 손톱만 한 구멍이 있었다. 기워 막았다.`,
      ng:`끌어안고 졸았다. 꿈속에서 누가 이쪽 품을 파고든다. 따뜻해서 그냥 두었다.<br><br>깨어 보니 품이 젖었다. 자루가 비었다. 다 먹었다. 이쪽 품 안에서.<br>품 안쪽 옷에 작은 이빨 자국이 줄줄이 났다. 살까지는 안 닿았다. 다행인지 아닌지 모른다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A', t:'문 — 안에서 잠긴 방',
  x:`복도 가운데 방 하나가 잠겼다. 열쇠 구멍에 열쇠가 꽂혀 있다. 안쪽에서.<br><br>
    안에서 잠그고 열쇠를 꽂아 두었다. 방에 창은 없다. 다른 문도 없다. 문틈 아래로 먼지가 고르다. 오래 아무도 안 나왔다.<br>
    그러면 잠근 사람은 아직 안에 있다.<br><br>
    방 안에서 아무 소리도 안 난다. 일행은 열어 보자고 한다. 그 방 너머에 길이 있을지도 모른다고.`,
  o:[
    { l:'① 문을 따고 들어가 안을 확인한다.', k:'fix', dc:23,
      doom:{ title:'잠근 사람', what:'문 뒤에 있던 것에게 방 안쪽으로 끌려갑니다', dc:18, sec:50,
        text:`철사로 열쇠를 밀어냈다. 안쪽에서 열쇠가 떨어지는 소리. 자물쇠를 땄다. 문을 밀었다.<br><br>방은 비었다. 의자 하나, 탁자 하나. 아무도 없다. 한 걸음 들어섰다.<br>등 뒤에서 문이 닫힌다. 문 뒤에 누가 서 있었다. 벽에 얼굴을 대고. 열린 문짝 뒤에 숨어 있었다. 오래.<br><br>그것이 돌아선다. 팔이 이쪽 어깨를 감싼다. 방 안쪽 구석으로 끌려간다. 문고리가 안쪽에서 철컥 잠긴다.`,
        dieText:`복도 가운데 방 하나가 잠겼다. 열쇠 구멍에 열쇠가 꽂혀 있다. 안쪽에서.<br><br>문틈 아래 먼지가 고르다. 오래 아무도 안 나왔다.<br>방 안에서 아무 소리도 안 난다. 문 뒤에 누가 서 있다. 둘이다.` },
      ok:`따기 전에 문짝을 끝까지 밀어 열 수 있는지 봤다. 경첩이 안쪽이다. 문이 안으로 열린다. 열리면 문짝 뒤에 사람 하나 설 자리가 생긴다.<br><br>자물쇠를 따고 문을 발로 밀었다. 끝까지. 문짝이 무엇에 부딪혀 멈췄다. 벽까지 가지 않았다. 문 뒤에 누가 있다.<br>들어가지 않았다. 문을 다시 당겨 닫고 바깥에서 잠갔다. 열쇠는 이쪽 주머니에 넣었다. 다른 길로 돌았다. 그 방에서는 끝까지 아무 소리도 나지 않았다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 열지 않고 먼지와 열쇠로 안의 사정을 맞춘다.', k:'gaze', dc:22, wake:1,
      ok:`열쇠가 안에 꽂혔다. 먼지가 고르다. 그런데 문 밑 먼지 위에 가는 선이 하나 있다. 손톱 하나 폭. 안에서 밖으로 무엇이 나오려다 멈춘 자국이다. 손가락 끝이다.<br><br>안의 사람은 나오고 싶었다. 그런데 열쇠를 안에서 잠갔다. 스스로 가뒀다. 나오고 싶은 것과 가둔 것이 한 사람이다. 가둔 것이 이겼다. 아직은.<br>문에 손대지 않았다. 일행에게 그 선을 보여 주고 다른 길로 돌았다. 지나고 나서 등 뒤에서 문 밑 선이 한 뼘 길어지는 소리가 났다. 사각.<br><br>잠긴 문 하나에도 그 안의 사정이 다 적혀 있다. 열지 않고 아는 법. 손대기 전에 현장을 먼저 끝까지 읽는 버릇이 붙었다.`,
      ng:`먼지를 보려고 엎드렸다. 문 밑 틈으로 안이 조금 보인다. 바닥에 누가 엎드려 있다. 이쪽을 보고. 같은 자세로.<br><br>눈이 마주쳤다. 문 밑 틈을 사이에 두고. 손가락이 틈으로 나온다. 이쪽 손가락을 찾는다.<br>손을 빼며 굴렀다. 손등이 긁혔다. 틈으로 나온 손가락이 먼지 위에 선을 하나 더 긋고 들어갔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'접수처 — 보호자 서명란',
  x:`접수처 책상에 방청객 명단이 있다. 아이 이름, 나이, 보호자 서명. 칸이 빼곡하다.<br><br>
    보호자 서명이 다 같은 손이다. 이름은 다르게 썼는데 획 끝이 다 같다. 한 사람이 수백 명 보호자를 했다.<br>
    서명 맨 끝마다 작은 동그라미가 붙었다. 털 뭉치처럼 삐죽삐죽한 동그라미.<br><br>
    명단 맨 아래 빈칸에 이쪽 일행 이름이 적혀 있다. 보호자 칸만 비었다.`,
  o:[
    { l:'① 서명한 손이 누구 손인지 따진다.', k:'gaze', dc:22, wake:1,
      ok:`삐죽삐죽한 동그라미. 로비에서 털북숭이 인형탈을 봤다. 뭉치. 서명 끝에 제 얼굴을 그렸다.<br><br>아이들은 보호자와 같이 왔다. 보호자가 뭉치였다. 아이를 데려온 것도 뭉치고 아이를 넘긴 것도 뭉치다. 보호자 칸이 빈 아이는 아직 넘겨지지 않은 아이다.<br>이쪽 일행 이름 옆 보호자 칸에 이쪽이 서명했다. 이쪽 이름으로. 이쪽 손으로. 다른 손이 채우기 전에. 명단이 잠잠해졌다. 보호자가 있는 아이는 다른 보호자가 데려가지 못한다.<br><br>여러 장의 글씨를 한 손으로 묶는다. 수백 개 이름 아래 한 사람이 숨어 있으면 그 사람이 범인이다. 버릇 하나로 손을 잡는 눈이 생겼다.`,
      ng:`따지는 사이 등 뒤에서 털 냄새가 난다. 먼지 냄새.<br><br>돌아봤다. 로비 한가운데 뭉치가 서 있다. 두 팔을 벌렸다. 안아 줄 자세다. 보호자 자세다.<br>접수처 책상 밑으로 숨었다. 털북숭이 발이 책상 앞에 멈췄다. 오래. 책상 위에서 펜 굴러가는 소리가 났다. 보호자 칸이 하나 채워지는 소리 같았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 명단 장을 뜯어 품에 넣고 빠져나간다.', k:'hide', dc:22,
      ok:`이쪽 일행 이름이 적힌 장을 소리 안 나게 뜯었다. 접어 품에 넣었다.<br><br>명단에 없는 아이는 방청객이 아니다. 방청객이 아닌 아이는 데려갈 까닭이 없다.<br>로비를 지날 때 뭉치가 두 팔을 벌리고 섰다. 그 앞을 지났다. 팔이 안지 않았다. 안을 명단이 없다.`,
      ng:`뜯는데 종이가 질기다. 찌익. 소리가 로비에 울렸다.<br><br>로비 한가운데 뭉치 머리가 이쪽으로 돈다. 몸은 그대로. 털북숭이 팔이 천천히 벌어진다.<br>뜯다 만 종이를 놓고 뛰었다. 계단을 오르다 무릎을 찧었다. 뒤에서 큰 발이 천천히 계단을 밟는 소리가 났다. 두 층을 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 보호자 칸에 아무 이름이나 써서 채운다.', k:'bond', dc:23,
      doom:{ title:'보호자 동반', what:'뭉치에게 안겨 커튼 안으로 끌려갑니다', dc:18, sec:50,
        text:`보호자 칸에 아무 이름이나 적었다. 지어낸 이름. 칸이 채워지면 된다고 생각했다.<br><br>지어낸 이름은 아무 사람도 아니다. 아무 사람도 아닌 보호자는 뭉치가 대신한다. 서명 끝에 저절로 동그라미가 생긴다. 삐죽삐죽.<br>뒤에서 털 냄새. 두 팔이 이쪽을 감싼다. 폭신하다. 따뜻하다. 놓지 않는다. 들어 올린다.<br><br>끌려간다. 안긴 채로. 로비 옆 대기실 커튼 쪽으로. 커튼이 열린다. 안이 깜깜하다.`,
        dieText:`명단 맨 아래 칸이 다 채워졌다. 보호자 서명 끝에 털 뭉치 동그라미.<br><br>로비 한가운데 뭉치가 두 팔을 벌리고 섰다. 안을 아이를 기다린다.<br>대기실 커튼 아래로 신발 한 켤레가 가지런히 나와 있다.` },
      ok:`아무 이름이 아니라 이쪽 일행 가운데 제일 나이 많은 사람 이름을 썼다. 그 사람에게 직접 서명하게 했다. 제 손으로.<br><br>진짜 보호자다. 진짜 손이다. 서명 끝에 동그라미가 생기려다 멈춘다. 획 끝이 다르다.<br>로비 한가운데 뭉치가 벌렸던 팔을 천천히 내렸다. 보호자 동반 아이는 안지 않는다. 대기실 커튼이 조금 흔들리다 잠잠해졌다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'기숙사 — 끝나지 않는 일기장',
  x:`호실 책상 서랍에 일기장이 있다. 학생 일기다. 날짜마다 몇 줄씩.<br><br>
    물이 들어온 날 일기는 짧다. 「비가 많이 온다. 사감 선생님이 방에 있으라고 했다.」<br>
    그다음 날짜에도 일기가 있다. 그다음도. 오늘까지. 글씨가 조금씩 번진다. 젖은 손으로 쓴다.<br><br>
    오늘 일기가 반쯤 쓰였다. 「손님이 왔다. 다섯 명.」`,
  o:[
    { l:'① 물 든 뒤의 일기를 처음부터 맞춰 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`날짜를 하나씩 맞췄다. 물이 든 뒤 일기는 매일 같다. 「점호. 밥. 점호.」 몇 해를. 그러다 드문드문 다른 날이 있다. 「손님이 왔다. 셋.」 그다음 날. 「손님이 갔다. 둘.」<br><br>하나는 못 갔다. 손님이 왔다 간 날마다 다음 날 일기에 「새 친구」가 생긴다. 못 간 손님이 새 친구다. 그리고 새 친구가 생긴 날 일기는 늘 같은 데서 끝난다. 「밤 점호 때 이름을 불렀더니 대답했다.」<br>오늘 일기 아래 빈 줄에 이쪽이 적었다. 「손님이 갔다. 다섯.」 이쪽 글씨다. 일기를 쓰는 젖은 손이 한참 그 줄 앞에서 멈췄다. 고치지 않았다.<br><br>매일 같은 기록 사이에서 다른 날만 골라 이으면 그게 사건이다. 같은 줄 천 개를 헤치고 다른 줄을 엮는 눈이 생겼다.`,
      ng:`읽는 사이 오늘 일기가 이어서 쓰인다. 펜이 저 혼자 움직인다. 「손님 하나가 내 일기를 읽는다.」<br><br>이쪽이다. 다음 줄. 「같이 있자고 해야지.」<br>일기장을 덮었다. 덮은 일기장 안에서 펜 소리가 계속 났다. 서랍에 넣고 닫았다. 서랍 안에서 펜 소리가 났다. 호실을 나올 때까지.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 서랍 깊숙한 데를 뒤진다.', k:'luck', dc:22,
      ok:`일기장 밑에 깡통이 있다. 집에서 보낸 소포 깡통이다. 꿀이 반쯤 남았다. 봉한 뚜껑이 그대로다. 아껴 먹었다.<br><br>깡통 안쪽 뚜껑에 쪽지. 「아껴 먹어라. 엄마.」<br>한 줌만 떴다. 뚜껑을 닫아 서랍에 도로 넣었다. 다 먹으면 안 될 것 같았다. 아껴 먹던 사람이 아직 있으니까.`,
      ng:`서랍 깊숙이 손을 넣자 젖은 것이 손에 닿는다. 머리카락이다. 서랍 안쪽에 한 뭉치. 길다.<br><br>당기자 서랍 안쪽 벽 너머로 이어져 있다. 벽 너머에서 누가 머리를 잡힌 듯 아파한다.<br>놓았다. 머리카락이 스르륵 벽 너머로 들어갔다. 손바닥에 젖은 감촉이 오래 남았다. 씻어도 안 씻겼다.`,
      win:{ exp:15, item:'꿀 한 줌', mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'계단참 — 시계 셋',
  x:`계단참 벽에 시계가 셋 걸렸다. 다 다른 시각이다. 세 시 오십 분. 다섯 시 정각. 아홉 시.<br><br>
    셋 다 초침이 돈다. 셋 다 맞는다고 우기듯이 째깍거린다.<br>
    시계 아래 문이 셋이다. 시계마다 문 하나.<br><br>
    한 시계만 맞다. 나머지 둘은 무엇이 일어난 시각에서 다시 시작한 시계다.`,
  o:[
    { l:'① 세 시각이 무엇의 시각인지 따진다.', k:'gaze', dc:22,
      ok:`세 시 오십 분은 물이 든 시각이다. 학교 칠판에 그 시각이 있었다. 다섯 시는 생방송 시각이다. 방송국 로비가 그 시각을 기다린다. 아홉 시는 밤 점호다.<br><br>셋 다 무엇이 시작되는 시각이다. 맞는 시계가 아니라 부르는 시계다. 그러면 셋 다 틀렸다. 맞는 시각은 시계에 없다.<br>세 문 다 버렸다. 계단참 바닥을 두드렸다. 비었다. 판자를 들어 아래로 내려갔다. 위에서 세 시계가 한꺼번에 울렸다. 부를 사람이 사라졌다는 듯이.`,
      ng:`따지는 사이 시계 하나가 아홉 시를 친다. 땡. 땡.<br><br>아홉 번을 다 칠 때까지 일행 하나가 숫자를 따라 셌다. 홉. 마지막 소리에 그 사람이 「네」 했다.<br>입을 막았다. 늦었다. 아홉 시 시계 아래 문이 조금 열렸다. 그 사람이 그쪽으로 가려 했다. 끌어안고 버텼다. 그 사람 팔에 이쪽 손톱자국이 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 세 문 밑으로 바람이 어느 쪽에서 오는지 본다.', k:'sense', dc:22,
      ok:`문마다 밑에 손등을 댔다. 첫 문은 바람이 없다. 둘째는 따뜻한 바람. 기름 냄새, 조명 냄새. 셋째는 찬 바람. 물 냄새.<br><br>둘 다 어딘가로 이어진다. 그런데 이어진 데가 다 이쪽을 부르는 데다. 바람 없는 첫 문이 막힌 문이 아니다. 아무것도 안 부르는 문이다.<br>첫 문을 열었다. 좁은 계단이 아래로 이어진다. 조용하다. 내려갔다.`,
      ng:`손등을 대는데 셋째 문 밑에서 찬 손이 나와 손등을 잡는다. 젖었다.<br><br>문 밑으로 끌어당긴다. 손가락이 문틈에 끼었다. 문틈이 손가락을 문다.<br>빼냈다. 손톱 하나가 들렸다. 문틈에 피가 묻었다. 셋째 문 시계가 갑자기 빨리 돌기 시작했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'벽 — 앞서 온 사람들의 쪽지',
  x:`벽에 쪽지가 줄줄이 붙어 있다. 앞서 온 사람들이 남겼다. 길 안내다. 「왼쪽은 막힘」 「계단 셋째 칸 무름」 「이름 부르면 대답 마시오」.<br><br>
    처음 쪽지들은 글씨가 제각각이다. 여러 사람이 썼다. 다 쓸모 있다. 지나온 길과 맞는다.<br>
    뒤로 갈수록 글씨가 고르다. 한 사람 글씨처럼.<br><br>
    맨 끝 쪽지. 「출구는 오른쪽 끝 문. 이 방에서 쉬어 가시오.」`,
  o:[
    { l:'① 쪽지들의 글씨를 견주어 바뀐 데를 찾는다.', k:'gaze', dc:22,
      ok:`처음 쪽지들은 연필, 숯, 손톱. 손에 있던 걸로 썼다. 뒤쪽 쪽지는 다 같은 붉은 것으로 썼다. 마르지 않았다.<br><br>바뀐 데는 열두째 쪽지다. 거기서부터 글씨가 고르다. 앞의 쪽지 글씨를 골고루 섞어 흉내 냈다. 흉내 낸 글씨는 너무 고르다.<br>열둘째부터는 하나도 믿지 않았다. 오른쪽 끝 문 말고 왼쪽 막힌 길을 밀어 봤다. 앞사람들 말대로라면 막혔어야 한다. 열렸다. 앞사람들은 거기서 막힌 줄 알고 돌아섰다. 그 뒤를 무엇이 고쳐 썼다.`,
      ng:`견주는 사이 쪽지 하나가 새로 붙는다. 이쪽 눈앞에서. 손은 안 보인다. 「글씨 보지 마시오.」<br><br>앞사람들 글씨다. 여러 사람 글씨가 한 장에 섞였다.<br>뒤로 물러났다. 쪽지들이 일제히 한 장씩 젖어 간다. 위에서 아래로. 붉은 물이 벽을 타고 내려왔다. 다들 그 벽을 등지지 않고 지났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-22 } },
    { l:'② 맨 끝 쪽지대로 오른쪽 끝 문으로 간다.', k:'sense', dc:23,
      doom:{ title:'쉬어 가시오', what:'방 바닥이 꺼져 아래로 떨어집니다', dc:18, sec:45,
        text:`오른쪽 끝 문을 열었다. 작은 방이다. 쉬기 좋다. 마른 바닥, 벽에 기대 앉을 자리.<br><br>들어섰다. 등 뒤 문이 닫힌다. 바닥 판자가 발밑에서 휜다. 판자 아래가 비었다. 아주 깊이.<br>판자 틈으로 쪽지가 수십 장 보인다. 아래 어둠에 떠 있다. 다 같은 글씨다. 「이 방에서 쉬어 가시오.」<br><br>판자가 부러진다. 몸이 아래로 꺼진다. 손이 벽을 긁는다. 잡을 데가 없다.`,
        dieText:`오른쪽 끝 문이 다시 열려 있다. 작은 방이다. 쉬기 좋다.<br><br>벽에 쪽지가 하나 늘었다. 「출구는 오른쪽 끝 문.」 글씨가 고르다.<br>그 글씨 획 끝 하나가 이쪽 버릇과 꼭 같다.` },
      ok:`문을 열기만 하고 들어가지 않았다. 문턱에 엎드려 바닥 판자를 손으로 눌렀다. 휜다. 판자 아래가 비었다.<br><br>쉬어 가라는 방은 떨어지는 방이다. 쪽지를 쓴 것은 앞사람들이 아니다. 문을 닫고 문에 숯으로 크게 썼다. 「들어가지 마시오.」 이쪽 글씨로. 거칠게. 흉내 내기 어렵게.<br>뒤에 오는 사람이 이쪽 글씨를 믿을지는 모른다. 그래도 썼다.`,
      win:{ exp:24, dream:4 } },
    { l:'③ 쪽지에 없는 것을 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`처음 쪽지들에는 다른 것도 적혀 있었다. 「물 아껴라」 「다리 아프다」 「배고프다」. 길과 상관없는 말. 사람이라 적은 말.<br><br>뒤쪽 쪽지에는 그런 말이 하나도 없다. 길만 있다. 배고프지도 지치지도 않은 손이 썼다. 사람은 지칠수록 쓸데없는 말을 적는다.<br>쓸데없는 말이 마지막으로 적힌 쪽지를 찾았다. 「목마르다. 저 문 뒤 물통 비었음.」 그다음부터는 사람이 쓴 게 아니다. 그 쪽지까지만 믿고 나머지는 거꾸로 했다. 왼쪽 길이 열렸다.<br><br>무엇이 적혔는지보다 무엇이 안 적혔는지가 범인을 말한다. 기록에서 사람 냄새가 끊기는 데를 찾는 눈이 생겼다.`,
      ng:`없는 것을 찾는다고 쪽지를 하나씩 떼어 읽었다. 떼어 낸 자리마다 벽이 축축하다.<br><br>마지막 쪽지를 떼자 벽에 손바닥 자국이 드러났다. 쪽지가 그 자리를 가리고 있었다. 손바닥 자국이 꿈틀한다.<br>쪽지를 도로 붙였다. 손이 떨려 비뚤게 붙었다. 벽 안쪽에서 무엇이 쪽지를 똑바로 고쳐 붙이는 소리가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 같은 회차 두 개',
  x:`테이프 보관실 선반에 같은 회차 번호가 두 개 꽂혀 있다. 이름표가 똑같다. 날짜까지.<br><br>
    하나는 이름표가 누렇게 바랬다. 오래된 것이다. 하나는 새것이다. 이름표를 바랜 것처럼 보이게 차를 묻혀 물들였다. 얼룩이 고르다.<br>
    같은 날 방송이 두 번 나갔을 리 없다.<br><br>
    부조정실 데크가 빈 채로 돌아간다. 다음에 걸 테이프를 기다린다.`,
  o:[
    { l:'① 두 테이프의 다른 데를 따져 가짜를 가린다.', k:'gaze', dc:22,
      ok:`바랜 쪽은 감긴 테이프 두께가 끝까지 꽉 찼다. 다 녹화한 테이프다. 새 쪽은 반만 감겼다. 반은 비었다.<br><br>새 테이프는 그날 방송을 다시 녹화하는 테이프다. 반까지 됐다. 그날 방송 후반에 무슨 일이 있었는지 지금 다시 찍고 있다. 오늘의 친구 순서가 후반이다.<br>새 테이프를 뽑아 리본을 끝까지 당겨 빼냈다. 반만 남은 그림이 엉켜 바닥에 쌓였다. 부조정실 데크가 멈췄다. 걸 테이프가 없다.`,
      ng:`따지는 사이 새 테이프가 저절로 감긴다. 선반 위에서. 두께가 늘어난다. 반을 넘었다.<br><br>부조정실에서 화면 켜지는 소리. 스피커에서 언니 목소리. 자, 오늘의 친구를 소개합니다.<br>테이프를 뽑아 바닥에 내리쳤다. 케이스가 깨졌다. 리본이 손에 감겨 손가락을 조였다. 풀어내는 데 한참 걸렸다. 손가락 마디가 쓸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 선반 맨 위 칸 상자를 내린다.', k:'luck', dc:22,
      ok:`맨 위 칸에 상자가 있다. 「촬영 소품 — 식품」. 내려 열었다.<br><br>요리 놀이 코너에 쓰던 진짜 재료다. 소금 덩이가 기름종이에 싸여 있다. 굳었지만 소금이다. 소금은 썩지 않는다.<br>한 덩이를 챙겼다. 상자 바닥에 작은 앞치마가 개어져 있다. 아이 것이다. 이름표가 없다. 도로 덮었다.`,
      ng:`상자를 내리는데 무겁다. 안에서 무엇이 한쪽으로 쏠린다. 굴러가듯이.<br><br>뚜껑이 열리며 쏟아진다. 소품 음식들. 플라스틱 사과, 나무 생선. 그리고 테이프 하나. 이름표에 이쪽 이름.<br>테이프가 바닥에서 저 혼자 감긴다. 발로 밟아 깨뜨렸다. 깨진 케이스 조각에 발목을 베었다.`,
      win:{ exp:16, item:'소금 덩이', mind:6 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 — 계단 벽의 물 자국',
  x:`종탑 나선 계단 벽에 물 자국이 줄줄이 남았다. 물이 올라왔다 빠진 자리다. 수평으로 고르다.<br><br>
    맨 아래 자국은 오래됐다. 이끼가 꼈다. 위로 갈수록 새것이다. 맨 위 자국은 아직 젖었다.<br>
    물이 빠지는 게 아니다. 오르고 있다. 조금씩.<br><br>
    맨 위 자국과 지금 물 높이 사이에 한 뼘이 남았다.`,
  o:[
    { l:'① 물가에 엎드려 맨 아래 자국까지 헤아린다.', k:'gaze', dc:23,
      doom:{ title:'물 높이', what:'물속 손에 손목을 잡혀 끌려 들어갑니다', dc:18, sec:45,
        text:`계단 맨 아래 칸까지 내려가 물가에 엎드렸다. 물 밑 자국까지 세려고. 손을 물에 넣어 벽을 더듬었다.<br><br>자국마다 홈이 있다. 손톱 하나 깊이. 자국은 물이 남긴 게 아니다. 손톱이 남겼다. 물속에서 누가 벽을 긁으며 물 높이를 표시했다.<br>더듬던 손목을 무엇이 잡는다. 물속에서. 작은 손. 자국을 긁던 손이다. 이쪽 손을 벽에 대고 다음 자국을 긁게 한다.<br><br>당긴다. 물속으로. 계단 칸이 무릎 밑에서 미끄러진다. 끌려 들어간다.`,
        dieText:`계단 벽에 물 자국이 하나 더 생겼다. 맨 위에. 아직 젖었다.<br><br>물이 한 뼘 올라왔다.<br>그 자국은 다른 자국보다 조금 높다. 어른 키만큼.` },
      ok:`엎드리지 않았다. 물 위 자국만 셌다. 맨 위에서부터 아래로 다섯 칸. 간격이 다 같다. 손가락 두 마디.<br><br>물 밑 자국은 세지 않았다. 같은 간격이면 셀 필요가 없다. 물은 같은 빠르기로 오른다. 한 마디 오르는 데 점호 두 번. 아침 일곱 시와 밤 아홉 시.<br>남은 한 뼘이면 점호 네 번이다. 그 안에 다 내려가 하교 종을 쳐야 한다. 일행에게 숫자를 말했다. 다들 말없이 짐을 줄였다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 자국 간격으로 물이 언제 차는지 계산한다.', k:'gaze', dc:22, wake:1,
      ok:`자국 간격을 손가락으로 쟀다. 다 같다. 자국 옆에 아주 작게 숫자가 긁혀 있다. 211, 212, 211, 212. 점호 인원이다.<br><br>212인 날은 물이 안 오른다. 211인 날에 한 칸 오른다. 누가 빠지면 물이 오른다. 물이 빠진 사람을 찾으러 올라온다. 찾으면 212가 되고 멈춘다.<br>이쪽 일행은 재적에 없다. 세어지지 않으면 빠진 것도 아니다. 다음 점호 때 일행 누구도 대답하지 않게 했다. 물이 올라오지 않았다.<br><br>숫자 둘을 겹치면 원인과 결과가 된다. 물 높이와 출석. 따로 있던 기록 둘을 잇는 눈이 생겼다. 한쪽만 보면 영영 모른다.`,
      ng:`계산하다 숫자가 하나 틀어졌다. 간격 하나가 남들보다 좁다. 다시 쟀다. 그사이 물이 발목까지 올라왔다.<br><br>계단을 오르려는데 물이 따라 오른다. 이쪽 발 높이만큼. 물이 이쪽을 찾는다.<br>계단을 두 칸씩 뛰었다. 물이 발뒤꿈치에서 찰랑댔다. 위층에 닿자 물이 멈췄다. 허벅지까지 젖은 데가 얼음처럼 시렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 비어 있는 일 분',
  x:`쉬다가 일행 하나가 잠깐 안 보였다. 다들 그 사람이 계속 옆에 있었다고 한다.<br><br>
    한 사람씩 물었다. 등불 기름을 갈 때 그 사람이 거들었다고 한다. 물을 나눌 때도 있었다고 한다.<br>
    그런데 기름을 간 것과 물을 나눈 것 사이에 일 분쯤이 빈다. 그때 그 사람이 어디 있었는지 아무도 말하지 못한다.<br><br>
    그 사람도 모른다. 그 일 분이 기억에 없다고 한다.`,
  o:[
    { l:'① 일행 진술을 맞춰 빈 일 분을 메운다.', k:'gaze', dc:22, wake:1,
      ok:`한 사람씩 따로 불러 그 일 분 동안 무엇을 봤는지 물었다. 그 사람이 아니라 다른 것을.<br><br>하나는 등불이 한 번 흔들렸다고 했다. 하나는 발소리가 하나 덜 났다고 했다. 하나는 그 사람 자리에서 물 냄새가 났다고 했다. 다 같은 쪽을 가리킨다. 그 사람 등 뒤 벽 틈이다.<br>그 사람 신발 밑창이 젖었다. 쉬는 자리는 말랐다. 벽 틈 안쪽 바닥에 젖은 발자국이 둘. 들어갔다가 나왔다. 그 사람 몸이. 그 사람은 아니었다. 벽 틈을 돌로 막았다. 그 사람 신발을 말렸다. 다음부터 쉴 때마다 서로 손을 잡고 잤다.<br><br>사람에게 사람을 물으면 기억이 흐리다. 그 둘레의 것을 물으면 또렷하다. 진술을 빙 둘러 맞춰 빈 데를 메우는 법이 생겼다.`,
      ng:`맞추는 사이 다른 일행 하나도 기억이 빈다고 한다. 아까 물 나눌 때 일 분.<br><br>또 하나. 또 하나. 다들 일 분씩 비었다. 순서대로.<br>마지막이 이쪽이다. 이쪽 일 분은 언제였는지 생각해 보았다. 등불 기름을 갈 때. 기름을 간 기억이 없다. 손에 기름 냄새가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 그 사람 손을 잡고 서로 놓지 않기로 한다.', k:'bond', dc:22,
      ok:`그 사람 손을 잡았다. 따뜻하다. 사람 손이다. 다른 일행들도 손을 잡게 했다. 한 줄로.<br><br>빈 일 분이 무엇이었든 손을 잡고 있으면 또 비지 않는다. 비면 옆 사람이 안다.<br>밤새 손을 잡고 쉬었다. 새벽에 그 사람 손이 한 번 차가워졌다가 다시 따뜻해졌다. 그 사람이 꽉 쥐었다. 이쪽도 꽉 쥐었다.`,
      ng:`잡았는데 그 사람 손이 미지근하다. 따뜻하지도 차지도 않다. 물에 오래 담근 손 같다.<br><br>그 사람은 아무렇지 않다고 웃는다. 웃음이 일 분 늦다.<br>밤새 그 손을 놓지 못했다. 놓으면 그 사람이 어딘가 갈 것 같았다. 아침에 그 손이 다시 따뜻해졌다. 이쪽 손이 차가워졌다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 떨어진 단추들',
  x:`복도 바닥에 단추가 떨어져 있다. 하나, 또 하나. 일정한 간격으로. 옆길로 이어진다.<br><br>
    옷에서 뜯긴 단추다. 실밥이 달렸다. 끌려가던 사람이 남긴 것 같다. 따라오라고.<br>
    단추 크기가 다 같다. 색도 같다. 한 벌 옷 단추로는 너무 많다. 스무 개가 넘는다.<br><br>
    너무 친절한 흔적은 흔적이 아니다.`,
  o:[
    { l:'① 단추와 실밥으로 흔적을 따진다.', k:'gaze', dc:22,
      ok:`단추마다 실밥이 붙었다. 실밥 끝이 다 같다. 가위로 자른 끝이다. 뜯긴 실밥은 끝이 보풀거린다.<br><br>끌려가며 뜯긴 게 아니다. 잘라서 놓았다. 같은 간격으로. 누가 미끼로 깔았다. 옷 한 벌에서 나올 수 없는 수만큼.<br>단추를 하나 주워 반대쪽 복도로 굴렸다. 단추 길 끝에서 무엇이 굴러온 단추 소리를 따라 움직이는 기척이 났다. 그쪽으로 가지 않았다.`,
      ng:`따지려고 단추를 하나 주웠다. 실밥이 손가락에 감긴다. 실이 길다. 옆길 저편까지 이어진다.<br><br>실이 당겨진다. 손가락이 끌린다. 단추 길 쪽으로.<br>단추째 실을 끊었다. 손가락에 실 자국이 깊게 패었다. 옆길 저편에서 실이 감겨 들어가는 소리가 한참 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 단추 길 반대쪽에서 진짜 흔적을 찾는다.', k:'sense', dc:22,
      ok:`미끼가 한쪽으로 깔렸으면 진짜는 반대쪽이다. 반대 복도 바닥을 등불로 쓸었다.<br><br>희미하게 손톱 긁힌 자국. 단추 길만큼 친절하지 않다. 듬성듬성. 진짜 끌려간 사람은 이렇게 남긴다. 그 자국 끝에 작은 틈. 틈 안에 그 사람이 숨겨 둔 꾸러미.<br>말린 고기다. 끌려가기 전에 숨겼다. 일행 몫으로. 고맙게 받았다. 틈 앞에 이쪽 단추 하나를 놓아 두었다. 진짜로 뜯어서.`,
      ng:`반대쪽을 찾는 사이 단추 길 쪽에서 소리가 난다. 단추 하나가 이쪽으로 굴러온다.<br><br>또 하나. 또. 단추가 이쪽 발 앞까지 줄지어 굴러와 선다. 길이 이쪽에서 시작되게.<br>밟지 않고 뛰었다. 등 뒤에서 단추 굴러오는 소리가 오래 따라왔다. 다음 층까지.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ mind:-20, spirit:-22 } },
    { l:'③ 단추를 하나도 밟지 않고 그대로 지나간다.', k:'steady', dc:22,
      ok:`단추 길을 넘어 지나갔다. 보지 않았다. 일행에게도 단추를 넘으라고 했다. 하나도 줍지 말라고.<br><br>단추가 줍는 손을 기다린다. 줍지 않으면 그냥 단추다.<br>다 지나고 나서도 아무도 단추 이야기를 하지 않았다. 다만 다들 제 옷 단추를 한 번씩 만져 보았다.`,
      ng:`넘어가는데 일행 하나가 단추를 주웠다. 저도 모르게. 반짝여서.<br><br>그 사람이 단추 길로 걷는다. 하나 더 줍는다. 하나 더. 이쪽 말이 안 들린다.<br>쫓아가 등을 붙잡았다. 손에 단추가 일곱 개다. 다 털어 버리게 했다. 그 사람은 한참 제 손을 내려다봤다. 손바닥에 단추 자국이 동그랗게 찍혀 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A1', t:'세트 뒤 — 분실물 상자',
  x:`세트 뒤 구석에 큰 상자가 있다. 「분실물」. 방청객 아이들이 두고 간 것.<br><br>
    신발이 많다. 한 짝씩. 다 오른쪽이다. 크기가 다르다. 날짜 꼬리표가 붙었다. 회차 번호와 같다.<br>
    왼쪽 신발은 하나도 없다.<br><br>
    상자 맨 위 신발 꼬리표 날짜가 오늘이다. 크기가 일행 하나의 발과 같다.`,
  o:[
    { l:'① 왜 오른쪽만 남았는지 따진다.', k:'gaze', dc:22,
      ok:`오른쪽만 남은 건 오른쪽만 벗겨졌기 때문이다. 아이를 끌고 가면 끌리는 쪽 발 신발이 벗겨진다. 오른발을 잡혀 끌려갔다.<br><br>그리고 오늘 날짜 신발. 아직 아무도 안 끌려갔다. 미리 꼬리표를 붙였다. 일행 하나 발 크기로. 그 사람이 오른쪽 신발을 벗겨질 차례다.<br>그 사람 오른쪽 신발 끈을 풀고 왼쪽과 바꿔 신겼다. 오른발에 왼쪽 신발. 꼬리표 붙은 신발이 맞지 않는 발이 됐다. 상자 맨 위 신발이 저절로 굴러 떨어졌다.`,
      ng:`따지는 사이 일행 하나가 신발 끈이 풀렸다고 한다. 오른쪽.<br><br>매 주려고 쪼그려 앉는데 세트 바닥 틈에서 손이 나와 그 사람 오른발을 잡는다.<br>둘이 같이 그 발을 붙잡았다. 신발이 벗겨졌다. 손이 신발만 쥐고 틈으로 들어갔다. 맨발이 퍼렇게 손자국이 났다. 상자에 신발이 하나 늘었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 상자 밑바닥에 무엇이 있는지 손을 넣어 본다.', k:'luck', dc:23,
      doom:{ title:'분실물', what:'분실물 상자 속으로 끌려 들어갑니다', dc:18, sec:45,
        text:`신발 사이로 팔을 넣었다. 아래로. 바닥에 무엇이 있는지. 팔꿈치까지 넣었는데 바닥이 안 닿는다.<br><br>어깨까지. 상자는 무릎 높이다. 바닥이 있어야 한다. 손끝에 무엇이 닿는다. 작은 발이다. 맨발. 왼발이다.<br>그 발 주인이 이쪽 손목을 잡는다. 아래에서. 작은 손이 여럿. 왼쪽 신발을 찾는 손들이다. 이쪽 신발을.<br><br>끌려 들어간다. 상자 속으로. 신발 무더기가 얼굴을 덮는다. 아래는 깊다. 맨발 아이들이 기다린다.`,
        dieText:`분실물 상자 맨 위에 신발이 하나 올라왔다. 오른쪽이다. 어른 것이다.<br><br>꼬리표가 붙었다. 오늘 날짜.<br>상자 아래 어디선가 왼쪽 신발이 바닥을 걷는 소리가 났다. 작은 발들 사이에서.` },
      ok:`손을 넣지 않았다. 등불 자루를 넣었다. 끝까지. 자루가 다 들어가도 바닥이 안 닿는다.<br><br>자루를 빼 보니 끝이 젖었다. 작은 손자국이 묻어 있다. 상자는 바닥이 없다. 분실물이 아니라 입구다.<br>상자 뚜껑을 닫고 그 위에 무거운 세트 판자를 올렸다. 안에서 신발들이 한꺼번에 들썩였다. 판자가 버텼다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'A2', t:'교무실 — 결석계',
  x:`교무실 담임 책상 서랍에 결석계 철이 있다. 물 든 날 뒤로 한 장도 없다. 아무도 결석하지 않았다.<br><br>
    맨 위에 한 장이 새로 꽂혔다. 오늘 날짜다. 이쪽 이름이다. 사유 칸. 「전학 수속 중 — 곧 등교」.<br>
    보호자 서명이 있다. 이쪽 보호자 이름이다. 글씨는 다르다.<br><br>
    결석계는 결석한 학생을 위한 것이다. 결석한 학생은 이 학교 학생이다.`,
  o:[
    { l:'① 결석계를 누가 썼는지 따진다.', k:'gaze', dc:22, wake:1,
      ok:`결석계 사유 칸 글씨와 보호자 서명 글씨가 같다. 같은 손이 둘 다 썼다. 보호자인 척.<br><br>그 손을 교무실 안에서 찾았다. 생활기록부 담임 의견 칸, 칠판의 오늘의 업무, 교무 수첩. 칠판 글씨가 같다. 「전입생 서류」라고 쓴 손. 담임 자리에 앉은 손이다.<br>결석계 보호자 칸 옆에 한 줄을 적었다. 「서명 위조 — 무효」. 담임 책상 위에 반듯이 올려 두었다. 교무실 의자들이 일제히 조금 돌았다. 학교는 서류에 약하다. 무효인 서류는 처리할 수 없다.<br><br>문서 하나에서 손을 찾고, 그 손으로 다른 문서를 찾는다. 서류끼리 이으면 사람이 나온다. 종이 더미에서 범인을 꺼내는 눈이 생겼다.`,
      ng:`따지는 사이 결석계 사유 칸이 바뀐다. 「전학 수속 완료 — 금일 등교」.<br><br>교무실 의자 스물이 이쪽을 향해 돈다. 출근한 선생들처럼. 담임 자리 의자가 빠진다. 학생은 담임 앞에 서야 한다.<br>교무실 문을 박차고 나왔다. 복도 물에 미끄러져 무릎을 찧었다. 등 뒤에서 결석계 넘기는 소리가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 전학 서류 대신 퇴학 처리 서류를 꾸민다.', k:'fix', dc:22,
      ok:`서랍에서 빈 서식을 찾았다. 「자퇴원」. 학생이 스스로 학교를 그만두는 서류다. 이쪽 이름으로, 이쪽 손으로 적었다. 사유 칸에 「본인 희망」.<br><br>본인이 쓴 서류가 보호자인 척한 서류보다 앞선다. 결석계 위에 자퇴원을 겹쳐 꽂았다.<br>교무실 칠판 오늘의 업무에 한 줄이 생겼다. 「자퇴 1」. 이쪽 일행 이름이 학적에서 빠졌다. 점호가 이쪽을 부를 까닭이 없어졌다.`,
      ng:`적는데 펜이 제 손을 안 따른다. 「자퇴원」 사유 칸에 「본인 희망」 대신 「등교 희망」이 써진다.<br><br>찢으려는데 종이가 손에서 안 떨어진다. 교무실 전화가 울린다. 따르릉. 보호자 확인 전화다.<br>종이를 물에 던졌다. 종이가 가라앉지 않고 떴다. 전화벨이 이쪽이 교무실을 나올 때까지 울렸다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 결석계를 빼내 품에 넣고 교무실을 빠져나간다.', k:'hide', dc:22,
      ok:`결석계를 빼서 품에 넣었다. 서류가 없으면 처리할 일도 없다.<br><br>교무실 의자들이 가만있다. 서류철에서 한 장이 빠진 걸 아무도 모른다. 학교는 철을 넘겨 보기 전에는 모른다.<br>복도로 나와 결석계를 물에 적셨다. 글씨가 번져 아무것도 아니게 됐다. 이쪽 이름도 보호자 이름도.`,
      ng:`품에 넣는데 결석계가 따뜻하다. 품 안에서 종이가 이쪽 옷에 달라붙는다.<br><br>교무실 의자 하나가 끼익 돈다. 서류를 들고 나가는 학생은 교무실이 붙잡는다.<br>문까지 갔을 때 발목이 물속에서 잡혔다. 뿌리치느라 넘어졌다. 품 안 결석계가 젖어 이쪽 가슴에 이름 모양으로 붙었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'어둠 — 두 번 들린 같은 비명',
  x:`어둠 저편에서 비명이 들렸다. 사람 목소리. 짧고 높다.<br><br>
    한참 뒤에 또 들렸다. 같은 비명이다. 높이도 길이도 숨 끊기는 데도 똑같다.<br>
    사람은 같은 비명을 두 번 못 지른다. 두 번째는 쉬거나, 더 커지거나, 작아진다.<br><br>
    일행 하나가 구하러 가자고 한다. 그 사람 목소리가 떨린다.`,
  o:[
    { l:'① 두 비명이 정말 똑같은지 따진다.', k:'gaze', dc:22,
      ok:`세 번째 비명이 왔다. 손가락으로 길이를 쟀다. 숨 셋. 끝에 숨 들이켜는 소리. 세 번 다 같은 데서 같은 크기로.<br><br>녹음이다. 아니면 녹음처럼 따라 하는 것이다. 처음 한 번은 진짜였을 것이다. 그 진짜를 무엇이 외워 되풀이한다. 구하러 오는 사람을 부르려고.<br>그쪽으로 가지 않았다. 일행 어깨를 잡고 비명이 나는 쪽 반대로 걸었다. 네 번째 비명은 오지 않았다. 듣는 사람이 떠나면 소용이 없다.`,
      ng:`세 번째를 기다리는데 이번엔 다르다. 비명이 일행 목소리다. 이쪽 일행 하나의.<br><br>그 사람이 옆에 있는데. 일행이 다 그쪽을 본다. 떨리는 목소리의 그 사람이 제 비명을 듣고 얼어붙었다.<br>다 같이 반대로 달렸다. 등 뒤에서 비명이 일행 목소리 하나씩으로 돌아가며 났다. 이쪽 목소리도 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 일행을 붙잡고 소리가 그칠 때까지 버틴다.', k:'steady', dc:22,
      ok:`가자는 일행 팔을 잡았다. 놓지 않았다. 다른 일행도 그 사람을 둘러쌌다.<br><br>비명이 다섯 번, 여섯 번 났다. 똑같이. 그 사람이 비명을 들을수록 조용해진다. 똑같은 소리는 사람 소리로 안 들린다. 결국 그 사람이 먼저 고개를 저었다.<br>열 번째쯤 비명이 끊겼다. 중간에서. 그다음엔 아무것도 없었다. 숨소리조차.`,
      ng:`붙잡았는데 그 사람이 뿌리친다. 비명 쪽으로 뛴다. 쫓아갔다.<br><br>어둠 속에서 그 사람을 붙들었을 때 바로 앞에서 비명이 났다. 귀가 찢어질 듯이. 아무도 없다. 비명만 있다.<br>그 사람을 끌고 돌아왔다. 둘 다 귀에서 한동안 소리가 안 빠졌다. 그 사람은 끝내 울었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A', t:'복도 끝 — 유류품 상자',
  x:`복도 끝 탁자에 상자가 놓였다. 「유류품」. 꼬리표 붙은 물건들이 들어 있다.<br><br>
    등불, 신발 한 짝, 수첩, 반지. 꼬리표마다 날짜와 짧은 글. 「계단 셋째 층 — 등불」 「거울 앞 — 반지」.<br>
    앞서 온 사람들이 남긴 것이다. 남긴 게 아니라 떨군 것이다.<br><br>
    맨 위 꼬리표가 빈 꼬리표다. 날짜만 적혔다. 오늘.`,
  o:[
    { l:'① 꼬리표를 건드리지 않고 지나간다.', k:'steady', dc:22,
      ok:`상자를 들여다보지 않았다. 꼬리표를 읽지 않았다. 상자 옆을 그대로 지났다.<br><br>빈 꼬리표는 물건을 기다린다. 이쪽이 아무것도 떨구지 않으면 빈 채로 남는다. 일행에게 주머니를 다 여미게 했다. 흘릴 것이 없게.<br>복도 끝 문을 지날 때 등 뒤에서 꼬리표가 바람에 팔랑이는 소리가 났다. 바람은 없었다.`,
      ng:`지나가는데 일행 하나 주머니에서 무엇이 떨어진다. 동전 하나. 굴러서 상자 밑으로 간다.<br><br>빈 꼬리표에 글씨가 생긴다. 「복도 끝 — 동전」.<br>그 사람을 데리고 서둘러 문을 지났다. 그 사람이 그날 내내 무엇을 잃은 것 같다고 했다. 무엇인지 끝내 몰랐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 꼬리표의 날짜와 글을 늘어놓아 순서를 맞춘다.', k:'gaze', dc:22, wake:1,
      ok:`꼬리표를 날짜 순으로 늘어놓았다. 같은 날짜끼리 묶었다. 한 날짜에 물건이 넷. 넷째 날짜에 다섯. 그 날짜에 온 일행들이다.<br><br>꼬리표 글의 자리를 이었다. 계단 셋째 층, 거울 앞, 복도 끝. 다 같은 순서다. 어느 일행이든 같은 데서 같은 순서로 떨궜다. 같은 자리에서 같은 것이 일어났다. 그 순서대로 다음 자리를 알 수 있다. 「문지방 — 신발」.<br>다음 문지방에서 다들 신발 끈을 꽉 매고 넘었다. 넘을 때 문지방 아래에서 손이 발목을 더듬다 미끄러졌다.<br><br>남은 물건을 줄 세우면 앞사람들의 길이 된다. 그 길에서 다음 자리가 보인다. 남의 흔적으로 이쪽 앞날을 미리 읽는 눈이 생겼다.`,
      ng:`늘어놓는 사이 빈 꼬리표가 저절로 상자에서 빠져나와 이쪽 소매에 달라붙는다.<br><br>떼어 내도 다시 붙는다. 꼬리표에 글씨가 생긴다. 「복도 끝 —」. 무엇을 쓸지 고르는 중이다.<br>소매를 찢어 버렸다. 꼬리표가 소매 조각에 붙은 채 상자로 돌아갔다. 「복도 끝 — 소매」. 찢긴 팔이 추웠다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'탕비실 — 출퇴근 기록기',
  x:`탕비실 벽에 출퇴근 기록기가 달렸다. 옆 꽂이에 직원 카드들이 꽂혀 있다. 이름, 날짜, 출근, 퇴근 시각.<br><br>
    카드마다 마지막 퇴근 칸이 비었다. 건물이 문 닫은 날 출근하고 아무도 퇴근하지 않았다.<br>
    한 카드만 매일 출근 도장이 찍혔다. 문 닫은 뒤로 몇 해치를. 퇴근은 한 번도 없다. 「무대 감독」.<br><br>
    꽂이 맨 끝에 새 카드가 하나 있다. 이쪽 이름이다.`,
  o:[
    { l:'① 이쪽 카드를 기록기에 넣어 퇴근 도장을 찍는다.', k:'fix', dc:23,
      doom:{ title:'출근 처리', what:'출근 처리되어 스튜디오로 끌려갑니다', dc:18, sec:45,
        text:`퇴근 도장을 찍으면 나갈 수 있을 것 같았다. 카드를 기록기에 넣었다. 철컥.<br><br>카드를 빼 보니 출근 칸에 도장이 찍혔다. 퇴근 칸이 아니다. 출근한 적이 없는 사람은 퇴근할 수 없다. 먼저 출근부터 한다.<br>등 뒤에서 하얀 장갑들이 이쪽 어깨를 짚는다. 손가락이 넷. 출근한 직원을 제자리로 모시는 손이다.<br><br>끌려간다. 계단 위로. 스튜디오로. 헤드셋 낀 무대 감독이 카드를 넘긴다. 신입 직원 입장.`,
        dieText:`출퇴근 기록기 옆 꽂이에 카드가 하나 더 꽂혔다.<br><br>매일 출근 도장이 찍힌다. 퇴근 칸은 비었다.<br>위층 스튜디오에서 무대 감독 옆에 헤드셋 낀 사람이 하나 더 섰다. 카드를 대신 넘긴다. 웃어요. 박수.` },
      ok:`넣기 전에 카드를 뒤집어 봤다. 출근 칸이 앞, 퇴근 칸이 뒤다. 기록기는 넣는 쪽 칸에 찍는다.<br><br>카드를 거꾸로, 뒤쪽이 앞으로 오게 넣었다. 철컥. 퇴근 칸에 도장이 찍혔다. 출근 없이 퇴근만. 그런 직원은 없다. 기록기가 지잉 하고 멈췄다.<br>카드를 빼서 반으로 접어 주머니에 넣었다. 출근하지 않고 퇴근한 사람은 이 건물이 다시 부를 수 없다. 장부에 맞지 않는다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 무대 감독의 카드를 끝까지 읽는다.', k:'gaze', dc:22,
      ok:`무대 감독 카드를 꺼냈다. 출근 도장이 날마다 찍혔다. 시각이 다 같다. 오후 네 시 오십삼 분. 로비 시계 시각이다.<br><br>그 사람은 네 시 오십삼 분에 출근해서 다섯 시를 기다린다. 매일. 다섯 시가 오면 방송이 나가고 다시 네 시 오십삼 분이다. 그 사람 하루는 칠 분이다.<br>카드 뒷면에 연필로 적혀 있다. 「오늘은 집에 가자.」 몇 해치 같은 글씨가 겹쳐 새카맣다. 카드를 꽂이에 도로 꽂았다. 맨 앞으로.`,
      ng:`읽는데 기록기가 저절로 철컥 울린다. 꽂이의 무대 감독 카드에 도장이 찍혔다. 출근.<br><br>위층에서 헤드셋 소리가 계단을 타고 내려온다. 대기해 주세요. 탕비실 문 밖에 무엇이 섰다. 카드를 들고.<br>냉장고 옆 틈으로 숨었다. 문이 열리고 닫혔다. 꽂이에서 이쪽 카드가 빠져나가는 소리가 났다. 다시 꽂히는 소리도 났다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 직원 냉장고를 연다.', k:'sense', dc:22,
      ok:`탕비실 냉장고가 아직 찬 바람을 낸다. 전기가 없는데. 열었다.<br><br>안에 이름표 붙은 도시락통이 몇 개. 다 비었다. 맨 아래 칸에 투명한 통 하나. 물에 담긴 버섯이다. 촬영 소품 텃밭에서 키우던 진짜 버섯이 거기서 자랐다. 하얗고 단단하다.<br>냄새를 맡았다. 버섯 냄새다. 다른 냄새가 안 난다. 몇 개 땄다. 냉장고를 닫는데 안쪽 벽에 손가락 넷 자국이 서리에 찍혀 있었다.`,
      ng:`열었는데 안에 찬 바람이 아니라 숨이 나온다. 냉장고 안에서 누가 숨을 쉰다.<br><br>맨 아래 칸에 웅크린 것이 있다. 헤드셋을 꼈다. 이쪽을 올려다본다. 「대기해 주세요.」<br>문을 닫고 등으로 막았다. 안에서 문을 민다. 한참 버텼다. 등뼈가 냉기에 얼어붙는 것 같았다.`,
      win:{ exp:16, item:'야생 버섯', mind:6 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'보일러실 — 멈춘 손목시계들',
  x:`보일러실 선반에 손목시계가 줄지어 놓였다. 수십 개. 학생들 것이다. 수영 수업 전에 벗어 둔 것.<br><br>
    다 멈췄다. 세 시 오십 분. 물이 든 시각이다.<br>
    한 개만 간다. 초침이 돈다. 째깍. 시각도 맞다. 지금 시각이다.<br><br>
    태엽 시계다. 몇 해를 아무도 안 감았으면 멈췄어야 한다.`,
  o:[
    { l:'① 가는 시계 하나가 왜 가는지 따진다.', k:'gaze', dc:22, wake:1,
      ok:`시계를 들어 봤다. 태엽 꼭지가 젖었다. 금방 감았다. 누가 매일 감는다.<br><br>시계 뒤 뚜껑에 이름이 새겨졌다. 학생 이름이 아니다. 「사감」. 학생들 시계 사이에 사감 시계가 섞였다. 사감은 시간을 지킨다. 점호 시각을 위해 날마다 태엽을 감는다.<br>시계를 들고 시각을 봤다. 다음 점호까지 얼마 남았는지. 남은 시간에 맞춰 내려갈 층을 셌다. 시계는 제자리에 두었다. 가져가면 사감이 찾으러 온다. 이 학교에서 정확한 것은 이것 하나다.<br><br>멈춘 것들 사이에서 가는 하나를 본다. 그 하나가 누가 손대고 있다는 증거다. 증거가 곧 시간표가 되는 법을 알았다.`,
      ng:`따지려고 들었는데 시계가 손목에 감긴다. 저절로. 줄이 채워진다. 딸깍.<br><br>초침 소리가 이쪽 맥박에 맞춰진다. 째깍, 쿵. 시계를 차면 점호 시각을 몸이 안다. 안다는 건 따른다는 뜻이다.<br>칼로 줄을 끊었다. 손목에 시계 자국이 눌려 패었다. 맥박이 한참 시계 박자로 뛰었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 보일러 옆 저장 칸을 뒤진다.', k:'luck', dc:22,
      ok:`보일러 옆 칸이 따뜻하다. 꺼지지 않은 불 옆이라 습기가 없다. 상자가 있다.<br><br>겨울 비상식이다. 말린 고기가 줄줄이 묶였다. 기름종이가 바삭하다. 아직 먹을 만하다.<br>두 줄을 챙겼다. 상자 뚜껑 안쪽에 사감 글씨. 「아이들 몫. 하나씩.」 하나만 가져갈 걸 그랬다. 한 줄을 도로 넣었다.`,
      ng:`칸을 여는데 보일러 불이 확 커진다. 뜨거운 김이 쏟아진다.<br><br>얼굴과 손등이 데었다. 물러섰다. 불 속에서 무엇이 이쪽을 본다. 불이 꺼지지 않는 까닭이 거기 있다.<br>칸은 비어 있었다. 다른 손이 먼저 다 가져갔다. 데인 손등에 물집이 잡혔다.`,
      win:{ exp:15, item:'말린 고기', hp:7 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 바뀐 잠자리',
  x:`아침에 깼다. 다들 자리가 바뀌어 있다. 잠들 때 이쪽은 벽 쪽이었다. 지금은 가운데다.<br><br>
    다섯 다 바뀌었다. 아무도 밤에 움직인 기억이 없다.<br>
    바닥에 끌린 자국이 있다. 다섯 줄. 사람을 눕힌 채 끌어 옮긴 자국이다.<br><br>
    끌린 자국 다섯 줄 가운데 하나가 다른 넷보다 길다.`,
  o:[
    { l:'① 끌린 자국으로 밤에 무슨 일이 있었는지 따진다.', k:'gaze', dc:22,
      ok:`자국마다 시작과 끝을 맞췄다. 넷은 짧다. 자리 하나씩 옮겼다. 하나는 길다. 쉬는 자리 밖 어둠까지 갔다가 돌아왔다.<br><br>긴 자국 끝은 일행 하나의 지금 자리다. 그 사람만 밖에 갔다 왔다. 다른 넷을 옮긴 건 그 하나가 어디 갔는지 섞어 숨기려는 것이다. 한 사람을 데려가 본 것이다. 데려갈 수 있는지.<br>그 사람 뒷덜미에 차가운 손자국이 있었다. 그날부터 밤에는 서로 발목을 끈으로 이어 묶고 잤다. 끌어 가면 다 같이 끌려가게.`,
      ng:`따지는 사이 긴 자국이 하나 더 생긴다. 이쪽 발밑에서 시작해서.<br><br>이쪽이 밤에 밖에 갔다 왔다. 기억이 없다. 신발 밑창이 젖었다. 쉬는 자리는 말랐는데.<br>다들 이쪽을 본다. 이쪽도 모른다. 그날 내내 일행이 이쪽 뒤를 걸었다. 이쪽은 앞에서 뒤가 무서웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 서로 밤새 무엇을 봤는지 묻고 몸을 살핀다.', k:'bond', dc:22,
      ok:`한 사람씩 몸을 살폈다. 뒷덜미, 발목, 손목. 끌려간 사람은 어딘가를 잡혔다.<br><br>한 사람 발목에 손가락 자국. 넷. 그 사람은 그 자국을 처음 본다. 다른 사람들은 깨끗하다.<br>그 사람을 가운데 눕히고 넷이 둘러 눕기로 했다. 다음 날 아침 자리는 그대로였다. 그 사람 발목 자국도 옅어졌다.`,
      ng:`살피다 보니 다섯 다 자국이 있다. 다 다른 데. 다섯이 다 한 번씩 끌려갔다 왔다.<br><br>순서대로. 하룻밤에 하나씩이 아니라 하룻밤에 다섯 다. 다 돌아왔다. 아직은.<br>그 뒤로 아무도 깊이 자지 못했다. 잠들 때마다 서로의 발목을 쥐었다. 손이 저려 깨면 다른 손이 쥐고 있었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-22, mind:-20 } }
  ] }

]);
